window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0073", [{"word":"mutualism","ipa_uk":"/ˈmjuːtʃuəlɪzəm/","ipa_us":"/ˈmjuːtʃuəlɪzəm/","definition_zh":"互利共生；互利主义；互惠互助","definition_en":"a lasting association between two species in which each partner gains a net benefit, and by extension any doctrine or practice of reciprocal benefit between parties","core_image":"两株植物的根系在地下相互缠绕，一侧输出糖分、另一侧输出磷盐，两端都抽出新叶","scene":"The fig and its pollinating wasp form a textbook mutualism in which neither species can reproduce without the other.","sceneCN":"这里 mutualism 指「互利共生」（第 1 个义项：双方都获得净收益的共生关系）；无花果与传粉榕小蜂构成教科书式的互利共生，彼此离开对方都无法繁殖。图中可辨识物件：榕果、小蜂、交织的根系、磷盐结晶。","pos":[{"tag":"n.","zh":"互利共生；互利主义；互惠互助（指关系或学说时不可数，指一例具体共生时可用复数 mutualisms）"}],"collocations":[{"phrase":"obligate mutualism","zh":"专性互利共生；双方离开对方都无法生存的共生"},{"phrase":"facultative mutualism","zh":"兼性互利共生；有互利好处但并非必需"},{"phrase":"plant-pollinator mutualism","zh":"植物与传粉者之间的互利共生"},{"phrase":"gut mutualism","zh":"肠道互利共生；肠道菌与宿主之间的互惠关系"},{"phrase":"mutualism theory","zh":"互利主义理论；主张以互惠而非竞争解释社会协作"},{"phrase":"economic mutualism","zh":"经济互惠主义；以相互授信、互助合作为基础的经济主张"},{"phrase":"break down a mutualism","zh":"使一段互利共生关系瓦解"}],"forms":[{"label":"复数","form":"mutualisms（指多种或一例例的共生关系）"},{"label":"形容词","form":"mutualistic（互利共生的；基于互利的）"},{"label":"副词","form":"mutualistically（以互利共生的方式）"},{"label":"施动名词","form":"mutualist（互利共生的一方；互惠主义者）"}],"derivatives":[{"word":"mutual","pos":"adj.","zh":"相互的；共同的；彼此之间的"},{"word":"mutually","pos":"adv.","zh":"相互地；彼此地"},{"word":"mutuality","pos":"n.","zh":"相互性；互惠性；共同性"},{"word":"mutualist","pos":"n.","zh":"互利共生的一方；互惠主义者"},{"word":"mutualistic","pos":"adj.","zh":"互利共生的；体现互惠的"},{"word":"commensalism","pos":"n.","zh":"偏利共生；一方受益、另一方不受影响"}],"senses":[{"no":"01","title":"Both partners gain","titleCN":"互利共生：双方都获得净收益","definition":"in ecology, a lasting association between two species in which each partner receives a net benefit from the other","definitionCN":"生态学中指两个物种长期共处，且每一方都从对方获得净收益的关系","example":"Coral polyps and their photosynthetic algae live in an obligate mutualism.","exampleCN":"珊瑚虫与共生光合藻类处于一种专性互利共生关系。","why":"The word names the plus-plus corner of symbiosis, where a relationship can be scored by what each partner gains rather than by who dominates.","whyCN":"这个词标出共生关系里的「双赢」一角：衡量一段关系，看双方各自得到什么，而不是看谁占上风。"},{"no":"02","title":"The pollination contract","titleCN":"传粉契约：花给报酬，虫送花粉","definition":"a mutualism in which a plant supplies nectar or a place to lay eggs and an animal moves its pollen between flowers","definitionCN":"指植物提供花蜜或产卵场所、动物替它把花粉在花间搬运的互利共生","example":"Fig-wasp mutualism depends on the wasp entering the fruit to pollinate it while laying its eggs.","exampleCN":"榕树与榕小蜂的互利共生依赖小蜂钻进果实产卵，同时完成授粉。","why":"Here the benefit is a service rather than a substance: pollen is delivered, and the insect is paid in food and nursery space.","whyCN":"这里的收益不是物质而是服务：花粉被送达，昆虫得到食物与育幼空间作为报酬。"},{"no":"03","title":"Cleaning stations","titleCN":"清洁站：小鱼取食寄生虫，大鱼得到清洁","definition":"a mutualism in which one animal removes parasites or debris from another and gains food in return","definitionCN":"指一种动物替另一种清除寄生虫或残渣，并以此换取食物的互利共生","example":"Cleaner fish at the reef station remove ticks from larger fish, a well-studied mutualism.","exampleCN":"礁石清洁站上的清洁鱼替大鱼清除寄螨、吸血虫，这是一种被充分研究过的互利共生。","why":"The pairing is a service trade, so ecologists call it mutualism rather than parasitism: both sides leave better off.","whyCN":"这组关系是服务交换，因此生态学家称其为互利共生而非寄生：双方离开时都更好。"},{"no":"04","title":"Gut microbiome","titleCN":"肠道共生：菌群发酵，宿主获得养分","definition":"a mutualism between a host animal and its resident microbes, in which the microbes receive habitat and the host receives nutrients or protection","definitionCN":"指宿主动物与常驻微生物之间的互利共生：微生物获得栖息地，宿主获得养分或保护","example":"Gut mutualism lets bacteria ferment fibre into acids the human body can absorb.","exampleCN":"肠道互利共生让细菌把膳食纤维发酵成人体可吸收的酸。","why":"The relationship is scored inside one body: habitat is paid for with metabolic work, so the label fits the ecological definition exactly.","whyCN":"这段关系发生在一个身体内部：栖息地由代谢劳动来支付，正好符合互利共生的生态学定义。"},{"no":"05","title":"Mutualist doctrine","titleCN":"互利主义：以相互授信取代中央权力","definition":"in political economy, a doctrine that organises credit, exchange and federation through reciprocal agreements among equals","definitionCN":"政治经济学中主张以平等者之间的相互授信、交换与联合来组织经济与社会的主张","example":"Proudhon's mutualism proposed interest-free credit banks run by the workers themselves.","exampleCN":"蒲鲁东的互利主义主张由劳动者自己经营无息信贷银行。","why":"The biological word has an older political life: mutualisme named a society built on reciprocity rather than hierarchy.","whyCN":"这个生物学词汇有更早的政治生命：mutualisme 指以互惠而非等级构建的社会。"},{"no":"06","title":"Mutual aid in practice","titleCN":"互助实践：团体之间的自愿互惠","definition":"the everyday practice of voluntary reciprocal help among people or groups, as in mutual aid funds and cooperatives","definitionCN":"指个人或团体之间自愿互惠的日常互助实践，如互助基金与合作社","example":"The mutualism of the village cooperative kept grain prices stable through the winter.","exampleCN":"村合作社的互惠机制让粮价在整个冬天保持稳定。","why":"Once reciprocity is organised into a habit, the abstract suffix -ism turns it into a named way of doing things.","whyCN":"当互惠被组织成习惯，抽象后缀 -ism 就把它变成一种有名有姓的做法。"},{"no":"07","title":"Coevolved partnership","titleCN":"共同演化：相互选择塑造出的伙伴","definition":"a partnership so tight that each partner's traits have been shaped by selection acting through the other","definitionCN":"指紧密到每一方的性状都被对方所施加的选择塑造过的伙伴关系","example":"The long mutualism left both the flower and the bee with matching tube lengths.","exampleCN":"长期的互利共生让花与蜂都演化出彼此匹配的管长。","why":"Mutualism is not only a present exchange but a history: reciprocal selection leaves anatomical evidence on both sides.","whyCN":"互利共生不只是当下的交换，也是一段历史：相互选择会在双方身上留下解剖学证据。"},{"no":"08","title":"Institutional reciprocity","titleCN":"机构互惠：借生物学词汇描述合作","definition":"a figurative use for two institutions or sectors that each supply what the other lacks, such as shared data and shared funding","definitionCN":"比喻用法，指两个机构或部门各自提供对方所缺之物，如共享数据与共享经费","example":"The university and the hospital describe their joint research as a mutualism.","exampleCN":"大学与医院把他们联合开展的科研称作一种互利共生。","why":"The metaphor works because the test is the same: if either side stops gaining, the arrangement no longer deserves the name.","whyCN":"这个比喻成立，因为检验标准相同：只要有一方不再获益，这种安排就不配叫这个名字。"}],"etymology":{"intro":{"en":"Mutualism joins Latin mutuus 'reciprocal, borrowed' with the noun suffix -ism; ecology gave an old word for reciprocity a biological body.","cn":"mutualism 把拉丁语 mutuus「相互的、借来的」与名词后缀 -ism 结合；生态学让这个表示互惠的旧词有了生物学躯体。"},"items":[{"era":"LATIN MUTUUS","en":"Latin mutuus meant 'reciprocal, exchanged, borrowed'. It described things that pass back and forth between parties, not things that merely look alike.","cn":"拉丁语 mutuus 意为「相互的、交换的、借来的」，描述在双方之间来回传递之物，而不是仅仅长得相似之物。"},{"era":"THE MUTARE LINK","en":"Mutual is often connected with Latin mutare 'to change, exchange', the source of mutate and commute. The link is plausible but not proved, so the deeper root connection is uncertain.","cn":"一般认为 mutual 与拉丁语 mutare「改变、交换」有关，该词根也是 mutate 与 commute 的来源；但这一联系只是合理推测、未获确证，更深的词根关联属来源不确定。"},{"era":"LATIN -ISMUS","en":"The suffix came into Latin as -ismus from Greek -ismos, which formed nouns for doctrines, practices and conditions.","cn":"该后缀以 -ismus 形式进入拉丁语，源自希腊语 -ismos，用来构成表示学说、实践与状态的抽象名词。"},{"era":"ENGLISH MUTUAL","en":"Mutual reached English in the fifteenth century through Old French mutuel, first describing shared feelings and shared obligations.","cn":"mutual 于 15 世纪经古法语 mutuel 进入英语，最初描述共同的情感与共同的义务。"},{"era":"ECOLOGY ADOPTS IT","en":"In the 1870s the Belgian zoologist Pierre-Joseph van Beneden applied mutualism to symbioses that benefit both partners. The exact first printing and date are uncertain, and older uses in political economy complicate the record.","cn":"19 世纪 70 年代，比利时动物学家皮埃尔-约瑟夫·范贝内登把 mutualism 用于双方都受益的共生关系；确切的首见文本与年代存疑，政治经济学中更早的用法也让文献记录变得复杂。"},{"era":"POLITICAL MUTUELLISME","en":"French mutualisme named a scheme of reciprocal credit and voluntary federation in the nineteenth century. It is generally dated to the 1840s and predates the biological sense, but the first citation is not fixed.","cn":"法语 mutualisme 在 19 世纪指相互授信与自愿联合的方案；一般认为其年代在 1840 年代、早于生物学义项，但确切首见书证仍不确定。"}]},"similar":{"note":{"en":"The first group shares the mut- stem and must be kept apart by part of speech; the second group is the three-way symbiosis vocabulary that beginners most often mix up.","cn":"第一组共享 mut- 词干，需按词性区分；第二组是初学者最容易混淆的共生三分法词汇。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mutual","ipa":"/ˈmjuːtʃuəl/","tag":"the adjective, not the system","definition":"An adjective meaning shared by two or more parties. It describes the quality of an exchange, while mutualism names the relationship or doctrine built on it.","definitionCN":"形容词，意为两方或多方共同拥有的。它描述交换的性质，而 mutualism 指建立在这种性质之上的关系或学说。"},{"word":"mutuality","ipa":"/ˌmjuːtʃuˈæləti/","tag":"the abstract quality","definition":"A noun for the state of being reciprocal. It is a quality, not a biological relationship, so it cannot replace mutualism in ecology.","definitionCN":"名词，指相互性这一状态。它表示性质而非生物关系，因此在生态学语境中不能替换 mutualism。"},{"word":"mutualist","ipa":"/ˈmjuːtʃuəlɪst/","tag":"one party or one believer","definition":"A count noun for one partner in a mutualism, or for a person who advocates mutualist economics. The system itself is mutualism.","definitionCN":"可数名词，指互利共生中的一方，或主张互利主义经济的人。制度或关系本身叫 mutualism。"}]},{"heading":"NEAR MEANING","entries":[{"word":"symbiosis","ipa":"/ˌsɪmbaɪˈəʊsɪs/","tag":"the umbrella term","definition":"Any close, lasting association between two species. It covers mutualism, commensalism and parasitism, so it is broader and neutral about who gains.","definitionCN":"指两个物种之间任何紧密而持久的共处。它涵盖互利共生、偏利共生与寄生，范围更广且不判断谁获益。"},{"word":"commensalism","ipa":"/kəˈmensəlɪzəm/","tag":"one gains, one unaffected","definition":"A symbiosis in which one partner benefits and the other is neither helped nor harmed. The plus-zero counterpart of mutualism.","definitionCN":"指一方受益、另一方既不受益也不受害的共生。它是互利共生的「加零」对应项。"},{"word":"parasitism","ipa":"/ˈpærəsɪtɪzəm/","tag":"one gains, one is harmed","definition":"A symbiosis in which one partner benefits at the expense of the other. The plus-minus counterpart of mutualism.","definitionCN":"指一方获益、另一方受损的共生。它是互利共生的「加减」对应项。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"mutuus means reciprocal, and -ism turns a quality into a system: reciprocal benefit as a system.","cn":"mutuus 意为相互的，-ism 把性质变成制度：把互惠互利做成一套关系。"},{"en":"The family runs mutual, mutually, mutuality, mutualist and mutualistic.","cn":"同族词包括 mutual、mutually、mutuality、mutualist、mutualistic。"},{"en":"Fixed phrases mark the field: obligate mutualism, facultative mutualism, plant-pollinator mutualism, gut mutualism.","cn":"固定搭配标出领域：专性互利共生、兼性互利共生、植物与传粉者互利共生、肠道互利共生。"},{"en":"Place it in the triad: mutualism is plus-plus, commensalism is plus-zero, parasitism is plus-minus.","cn":"放进三分法：互利共生是加加，偏利共生是加零，寄生是加减。"},{"en":"Van Beneden applied the term to beneficial symbiosis in the 1870s, and political mutualisme came earlier.","cn":"范贝内登在 1870 年代把这个词用于有益共生，而政治上的互惠主义用法更早出现。"}],"abstract":[{"en":"Picture two root systems trading sugar for phosphate underground, both pushing up new shoots.","cn":"想象两套根系在地下用糖分换磷盐，两侧都抽出新芽。"},{"en":"Picture a cleaner fish entering a large fish's mouth and leaving fed, while the host leaves clean.","cn":"想象一条清洁鱼游进大鱼口中，离开时吃饱了，而宿主也变干净了。"},{"en":"Picture two workshops keeping a shared ledger of favours, each entry owed by one and paid by the other.","cn":"想象两个作坊共用一本恩惠账簿，每一笔都由一方欠下、另一方偿还。"}]},"examples":[{"en":"The coral-algae mutualism collapses when water temperatures rise too far.","cn":"水温升得过高时，珊瑚与藻类的互利共生就会崩溃。"},{"en":"Ecologists distinguish obligate mutualism from relationships that are merely convenient.","cn":"生态学家把专性互利共生与仅仅图方便的关系区分开来。"},{"en":"The cooperative's mutualism is written into its rules on shared credit.","cn":"这家合作社的互惠机制写进了它关于共享信贷的章程。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"mutual（相互的）+ ism（主义）→ 相互受益的一套关系 → mutualism 互利共生","word":"mutualism"},"root":"拉丁 mutuus「相互的、借来的」+ -ism；19 世纪生态学用它命名双方都受益的共生关系，政治经济学中的互惠主义用法更早。","sensesIntro":{"en":"Eight senses follow one test: does each side leave better off? Ecology applies the test to species, economics to credit, and the metaphor to institutions.","cn":"八个义项都围绕同一条检验：双方离开时是否都更好？生态学用它检验物种，经济学用它检验信贷，比喻用法用它检验机构。"},"semanticMap":{"core":{"en":"CORE IMAGE: two root systems trading sugar for phosphate, both growing new shoots.","cn":"核心意象：两套根系用糖分换磷盐，两侧都长出新芽。"},"chain":["RECIPROCAL EXCHANGE","BOTH BENEFIT","SYMBIOSIS","SERVICE TRADE","MUTUAL AID","RECIPROCAL DOCTRINE"],"branches":[{"senses":"01","en":"ECOLOGY: the basic definition is a plus-plus score for two species living together.","cn":"生态学：基本定义是两个物种共处时得到加加评分。"},{"senses":"02 · 03 · 04","en":"SERVICE TRADE: pollination, cleaning and gut fermentation are the same bargain in different currencies.","cn":"服务交换：传粉、清洁与肠道发酵是同一笔交易换了不同货币。"},{"senses":"05 · 06","en":"SOCIAL PRACTICE: reciprocity becomes a doctrine when credit and aid are organised on purpose.","cn":"社会实践：当授信与互助被有意组织起来，互惠就成了一种主张。"},{"senses":"07","en":"DEEP TIME: reciprocal selection writes the partnership into both bodies.","cn":"深层时间：相互选择把这段伙伴关系写进双方的身体。"},{"senses":"08","en":"METAPHOR: institutions borrow the word, and the same test still applies.","cn":"比喻：机构借用这个词，检验标准依然不变。"}]},"affixes":{"intro":{"en":"Mutualism is built from a Latin adjective plus a Greek-derived noun suffix, so the word means 'the system of the reciprocal'.","cn":"mutualism 由拉丁形容词加希腊来源的名词后缀构成，字面意思是「相互性所成的制度」。"},"latinIntro":{"en":"Latin mutuus supplies the stem, Greek -ismos reaches English through Latin -ismus, and the family also grows through -ity, -ist and -istic.","cn":"拉丁语 mutuus 提供词干，希腊语 -ismos 经拉丁语 -ismus 进入英语，这一族还通过 -ity、-ist 与 -istic 扩展。"},"items":[{"word":"mutualism","structure":"mutual + -ism (system, doctrine)","meaning":"a system of reciprocal benefit, especially between species","meaningCN":"互惠受益的体系，尤指物种之间的互利共生","example":"Reef mutualism keeps both coral and algae alive.","exampleCN":"礁体互利共生让珊瑚与藻类都得以生存。"},{"word":"mutual","structure":"Latin mutuus (reciprocal) + -al (adjective)","meaning":"shared or felt by both sides","meaningCN":"双方共享或共同感受到的","example":"The two labs signed a mutual data agreement.","exampleCN":"两个实验室签署了共享数据的互惠协议。"},{"word":"mutually","structure":"mutual + -ly (adverb)","meaning":"in a reciprocal way","meaningCN":"以相互的方式","example":"The two species depend mutually on each other.","exampleCN":"这两个物种相互依赖。"},{"word":"mutuality","structure":"mutual + -ity (state, quality)","meaning":"the quality of being reciprocal","meaningCN":"相互性；互惠性","example":"The contract stresses mutuality of obligations.","exampleCN":"合同强调义务的相互性。"},{"word":"mutualist","structure":"mutual + -ist (one who practises or supports)","meaning":"one partner in a mutualism; an advocate of mutualist economics","meaningCN":"互利共生的一方；互利主义的支持者","example":"Each mutualist gains something the other cannot make.","exampleCN":"每个互利共生方都得到对方无法自造的东西。"},{"word":"mutualistic","structure":"mutualist + -ic (adjective)","meaning":"of or marked by mutual benefit","meaningCN":"互利共生的；带有互惠特征的","example":"The ants and the acacia have a mutualistic bond.","exampleCN":"蚂蚁与金合欢之间存在互利共生纽带。"},{"word":"mutualistically","structure":"mutualistic + -ally (adverb)","meaning":"in a mutually beneficial manner","meaningCN":"以互利共生的方式","example":"The two fungi grow mutualistically on the same log.","exampleCN":"这两种真菌在同一根木头上互利共生地生长。"},{"word":"commensalism","structure":"com- (together) + mensa (table) + -ism","meaning":"one-sided benefit with no harm","meaningCN":"一方受益而另一方无损的偏利共生","example":"Barnacles on a whale are a case of commensalism.","exampleCN":"鲸身上的藤壶是偏利共生的一例。"},{"word":"symbiosis","structure":"syn- (together) + bios (life) + -osis (process)","meaning":"any close and lasting living-together","meaningCN":"任何紧密而持久的共处关系","example":"Symbiosis covers all three plus-minus scores.","exampleCN":"共生涵盖加加、加零、加减三种评分。"}],"latinEntries":[{"word":"mutuus","structure":"mutuus, mutua, mutuum (adj., first/second declension)","meaning":"reciprocal, exchanged, borrowed","meaningCN":"相互的、交换的、借来的"},{"word":"mutare","structure":"mutare, muto, mutavi, mutatum (v., first conjugation)","meaning":"to change, to exchange; its link to mutuus is plausible but unproved","meaningCN":"改变、交换；它与 mutuus 的关联只是合理推测，未获确证"},{"word":"-ismus","structure":"-ismus (suffix; from Greek -ismos)","meaning":"doctrine, practice, condition","meaningCN":"学说、实践、状态"}]}},{"word":"mutualistic","ipa_uk":"/ˌmjuːtʃuəˈlɪstɪk/","ipa_us":"/ˌmjuːtʃuəˈlɪstɪk/","definition_zh":"互利共生的；互惠互利的；以互利为基础的","definition_en":"describing a relationship or partner in which both sides gain, especially in ecology, and by extension any arrangement built on reciprocal benefit","core_image":"一头大鱼的嘴边停着一条清洁小鱼，小鱼啄食寄生虫，大鱼张开鳃盖放行","scene":"The association is mutualistic because the cleaner gains a meal while the host loses its parasites.","sceneCN":"这里 mutualistic 指「互利共生的」（第 1 个义项：双方都获得净收益）；这层关系之所以是互利共生，是因为清洁鱼得到一顿饭，而宿主摆脱了寄生虫。图中可辨识物件：大鱼、清洁鱼、鳃盖、寄生虫。","pos":[{"tag":"adj.","zh":"互利共生的；互惠互利的；以互利为基础的（作定语或表语，比较级用 more/most）"}],"collocations":[{"phrase":"mutualistic relationship","zh":"互利共生关系；互惠关系"},{"phrase":"mutualistic symbiosis","zh":"互利共生；双方受益的共生"},{"phrase":"mutualistic interaction","zh":"互利互动；物种间的互惠作用"},{"phrase":"mutualistic partner","zh":"互利共生伙伴"},{"phrase":"mutualistic arrangement","zh":"互惠安排；机构间的互利合作"},{"phrase":"mutualistic cooperation","zh":"互惠合作"},{"phrase":"highly mutualistic","zh":"高度互利的；互利程度很高的"}],"forms":[{"label":"比较级","form":"more mutualistic（生物学描述中一般不用比较级，需要时用 more）"},{"label":"最高级","form":"most mutualistic"},{"label":"副词形式","form":"mutualistically（以互利共生的方式）"},{"label":"名词形式","form":"mutualism（互利共生）；mutualist（共生一方）"},{"label":"作定语","form":"mutualistic + 名词（如 mutualistic relationship、mutualistic network）"}],"derivatives":[{"word":"mutualism","pos":"n.","zh":"互利共生；互利主义"},{"word":"mutualist","pos":"n.","zh":"互利共生的一方；互惠主义者"},{"word":"mutual","pos":"adj.","zh":"相互的；共同的"},{"word":"mutually","pos":"adv.","zh":"相互地；彼此地"},{"word":"mutuality","pos":"n.","zh":"相互性；互惠性"},{"word":"commensal","pos":"adj./n.","zh":"偏利共生的；偏利共生生物"}],"senses":[{"no":"01","title":"Both sides profit","titleCN":"双方获利：关系本身是加加评分","definition":"describing a relationship in which each participant receives a net benefit from the other","definitionCN":"描述每一方都从对方获得净收益的关系","example":"The cleaner fish and the reef fish have a mutualistic relationship.","exampleCN":"清洁鱼与礁鱼之间是互利共生关系。","why":"The adjective attaches the plus-plus score to a specific relationship, so it answers the question of what kind of association this is.","whyCN":"这个形容词把「加加评分」挂到具体关系上，用来回答这究竟是怎样一种关系。"},{"no":"02","title":"Describing a partner","titleCN":"描述伙伴：作为其中一方的属性","definition":"describing one organism as a beneficial partner that supplies a service or resource to another","definitionCN":"描述某个生物作为有益伙伴，向另一方提供服务或资源","example":"Certain fungi are mutualistic partners that help tree roots absorb phosphorus.","exampleCN":"某些真菌是互利共生伙伴，帮助树根吸收磷。","why":"The same adjective can modify the partner rather than the pair, because a partnership is named from the side that gives as well as from the whole.","whyCN":"同一个形容词既可以修饰伙伴、也可以修饰整对关系，因为伙伴关系既能从整体命名，也能从给予的一方命名。"},{"no":"03","title":"Coevolved traits","titleCN":"共同演化的性状：解剖结构彼此匹配","definition":"describing traits that have been shaped by reciprocal selection, such as matching flower depth and insect tongue length","definitionCN":"描述被相互选择塑造出的性状，如花管深度与昆虫舌长彼此匹配","example":"The long proboscis is a mutualistic adaptation to the deep flower tube.","exampleCN":"长口器是对深花管的一种互利共生适应。","why":"The adjective extends from the relationship to its anatomical footprint, marking a history of reciprocal selection.","whyCN":"这个形容词从关系扩展到它留下的解剖学痕迹，标示一段相互选择的历史。"},{"no":"04","title":"Microbial partnership","titleCN":"微生物伙伴：菌群与宿主的互惠","definition":"describing microbes that supply nutrients or protection to a host while receiving habitat and food","definitionCN":"描述向宿主提供养分或保护、同时获得栖息地与食物的微生物","example":"The gut hosts a mutualistic community that digests fibre for its animal host.","exampleCN":"肠道中栖居着一个互利共生群落，替动物宿主消化纤维。","why":"Microbiology borrowed the adjective because the accounting is the same as in a reef: both the bug and the body gain.","whyCN":"微生物学借用这个形容词，因为账目与礁石上相同：细菌与身体都获益。"},{"no":"05","title":"Economic reciprocity","titleCN":"经济互惠：组织之间的互利安排","definition":"describing a commercial or institutional arrangement in which each party supplies something the other needs","definitionCN":"描述商业或机构安排中，每一方都提供对方所需之物","example":"The two firms formed a mutualistic alliance to share distribution networks.","exampleCN":"两家公司结成互利联盟，共享配送网络。","why":"The biological adjective travels into business because the test is unchanged: each side must leave better off, or the alliance is not mutualistic.","whyCN":"这个生物学形容词进入商业领域，因为检验标准没变：双方必须都更受益，否则联盟就称不上互利。"},{"no":"06","title":"Social cooperation","titleCN":"社会合作：互助组织的互惠性质","definition":"describing cooperation among people or groups that is organised so that every participant gains","definitionCN":"描述人与人、团体与团体之间被组织成让每个参与者都获益的合作","example":"The village's mutualistic grain bank lent seed in spring and received grain after harvest.","exampleCN":"村里的互惠粮库春天借出种子，秋收后收回粮食。","why":"Once people copy the ecological pattern, the adjective describes a designed institution rather than a natural symbiosis.","whyCN":"当人们仿照生态模式行事，这个形容词描述的就是被设计出来的制度，而非自然共生。"},{"no":"07","title":"The contrastive label","titleCN":"对照标签：与偏利、寄生相对","definition":"used to classify a relationship when it is placed beside commensal or parasitic ones","definitionCN":"在把关系与偏利共生、寄生并列分类时使用的标签","example":"Field data showed the association was mutualistic rather than commensal.","exampleCN":"野外数据表明这段关系是互利共生的，而不是偏利的。","why":"Classification needs an adjective, not a noun phrase: mutualistic marks the plus-plus cell of the three-cell table.","whyCN":"分类需要一个形容词而不是名词短语：mutualistic 标出三分表格里的「加加」格。"},{"no":"08","title":"Figurative mutual benefit","titleCN":"比喻式互利：抽象关系也可用","definition":"used figuratively of abstract exchanges, such as a writer and an editor who each improve the other's work","definitionCN":"比喻地用于抽象交换，如作者与编辑互相提升对方的工作","example":"Their long collaboration was mutualistic: each made the other sharper.","exampleCN":"他们长期合作是互利的：彼此都让对方更敏锐。","why":"The metaphor survives because there is still a measurable trade, even though neither side is a species.","whyCN":"这个比喻站得住，因为仍存在可衡量的交换，即便双方都不是物种。"}],"etymology":{"intro":{"en":"Mutualistic is the adjective built on mutualism with -istic, so its history is the history of mutuus plus two layers of suffix.","cn":"mutualistic 是在 mutualism 上加 -istic 构成的形容词，它的历史就是 mutuus 加两层后缀的历史。"},"items":[{"era":"LATIN MUTUUS","en":"Mutuus meant reciprocal or exchanged, and it names the core of every later form in this family.","cn":"mutuus 意为相互的、交换的，它命名了这一词族后世所有形式的核心。"},{"era":"ENGLISH MUTUAL","en":"Old French mutuel brought the adjective into English by the fifteenth century, where it first described shared feelings and duties.","cn":"古法语 mutuel 在 15 世纪把这个形容词带进英语，最初描述共同的情感与义务。"},{"era":"MUTUALISM","en":"The noun added -ism to name a system of reciprocity, first in political economy and later in ecology.","cn":"名词形式加 -ism，用来命名一套互惠体系，先见于政治经济学，后用于生态学。"},{"era":"GREEK -ISTIKOS","en":"The suffix -istic descends from Greek -istikos through Latin -isticus, forming adjectives for people or things that practise or embody something.","cn":"后缀 -istic 经拉丁语 -isticus 源自希腊语 -istikos，构成表示「从事或体现某事」的形容词。"},{"era":"MODERN USE","en":"The adjective became common in ecology in the twentieth century as textbooks needed to classify relationships quickly. Its first use is not precisely dated.","cn":"20 世纪生态学教科书需要快速给关系分类，这个形容词因而普及；其首见年代没有精确记载。"}]},"similar":{"note":{"en":"The look-alike group differs only by suffix but changes part of speech; the near-meaning group names the neighbouring relationship types.","cn":"形近组只差后缀却改变词性；近义组则列出相邻的关系类型。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"mutualism","ipa":"/ˈmjuːtʃuəlɪzəm/","tag":"the noun","definition":"The relationship or doctrine itself. You can study mutualism, but you cannot say that a pair of species is mutualism.","definitionCN":"指关系或学说本身。可以说研究 mutualism，但不能说一对物种是 mutualism。"},{"word":"mutualist","ipa":"/ˈmjuːtʃuəlɪst/","tag":"the participant","definition":"A noun for one partner or one supporter. It is a person or organism, not a property.","definitionCN":"名词，指一方伙伴或一名支持者，是人或生物，而非性质。"},{"word":"mutuality","ipa":"/ˌmjuːtʃuˈæləti/","tag":"the quality","definition":"The abstract quality of being reciprocal. It cannot describe a species or a relationship type.","definitionCN":"指相互性的抽象性质，不能用来描述某个物种或某类关系。"}]},{"heading":"NEAR MEANING","entries":[{"word":"symbiotic","ipa":"/ˌsɪmbaɪˈɒtɪk/","tag":"the broader adjective","definition":"Describes any close lasting association, whether mutualistic, commensal or parasitic. It does not commit to who gains.","definitionCN":"描述任何紧密持久的共处，无论互利、偏利还是寄生，不判定谁获益。"},{"word":"commensal","ipa":"/kəˈmensəl/","tag":"one gains, one unaffected","definition":"Describes the plus-zero case. Using it where both sides gain understates the benefit to the second partner.","definitionCN":"描述加零情形。若双方都获益却用这个词，就低估了第二方的收益。"},{"word":"parasitic","ipa":"/ˌpærəˈsɪtɪk/","tag":"one gains, one loses","definition":"Describes the plus-minus case. It is the opposite of mutualistic in ecological scoring.","definitionCN":"描述加减情形，在生态学评分上是互利共生的反面。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"mutualism + -istic: the adjective form of the plus-plus system.","cn":"mutualism + -istic：加加体系的形容词形式。"},{"en":"The chain runs mutual, mutualism, mutualist, mutualistic, mutualistically.","cn":"词族链条是 mutual、mutualism、mutualist、mutualistic、mutualistically。"},{"en":"Typical collocations: mutualistic relationship, mutualistic symbiosis, mutualistic interaction.","cn":"典型搭配：互利共生关系、互利共生、互利互动。"},{"en":"Contrast the three adjectives: mutualistic, commensal, parasitic.","cn":"对照三个形容词：互利、偏利、寄生。"},{"en":"The suffix -istic builds adjectives from -ism nouns, as in capitalistic and mutualistic.","cn":"后缀 -istic 从 -ism 名词构成形容词，如 capitalistic 与 mutualistic。"}],"abstract":[{"en":"Picture a cleaner fish leaving a host's mouth fed, while the host leaves clean.","cn":"想象清洁鱼从宿主口中离开时吃饱了，宿主也变干净了。"},{"en":"Picture two tree roots locked together, each sending the other a mineral it cannot make.","cn":"想象两条树根缠在一起，各自送出对方无法制造的矿物。"},{"en":"Picture two companies swapping warehouse space, both cutting costs without hiring anyone.","cn":"想象两家公司互换仓库空间，双方都降了成本，却没多雇一个人。"}]},"examples":[{"en":"The fig-wasp relationship is mutualistic because the insect both pollinates and reproduces.","cn":"榕树与榕小蜂的关系是互利共生的，因为昆虫既完成授粉又完成繁殖。"},{"en":"A mutualistic fungus can supply a tree with phosphorus in exchange for sugar.","cn":"互利共生真菌能向树木供应磷，以换取糖分。"},{"en":"The report called the joint venture mutualistic rather than merely contractual.","cn":"报告称这家合资企业是互利性质的，而不只是合同关系。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"mutual（相互的）+ istic（……的）→ 相互受益的 → mutualistic 互利共生的","word":"mutualistic"},"root":"拉丁 mutuus「相互的」→ mutual → mutualism（互利共生）+ 希腊来源后缀 -istic。","sensesIntro":{"en":"Eight senses all answer one question with an adjective: in this particular relationship, does each participant gain?","cn":"八个义项都用同一个形容词回答同一个问题：在这段具体关系里，每个参与者是否都获益？"},"semanticMap":{"core":{"en":"CORE IMAGE: a cleaner fish at a host's mouth, fed on parasites, with the host left clean.","cn":"核心意象：清洁鱼停在宿主嘴边，以寄生虫为食，宿主因此变干净。"},"chain":["BOTH GAIN","PARTNER QUALITY","COEVOLVED TRAIT","MICROBIAL ALLIANCE","INSTITUTIONAL ALLIANCE","CLASSIFICATION"],"branches":[{"senses":"01","en":"DEFINITION: the adjective scores a relationship as plus-plus.","cn":"定义：这个形容词把一段关系评为加加。"},{"senses":"02 · 03 · 04","en":"EMBODIMENT: the benefit can sit in a partner, in a trait, or in a microbe.","cn":"体现：收益可以落在伙伴身上、落在某个性状上，或落在微生物身上。"},{"senses":"05 · 06","en":"EXTENSION: firms and villages copy the pattern on purpose.","cn":"延伸：公司与村庄有意复制这一模式。"},{"senses":"07","en":"CLASSIFICATION: the adjective locates a case in the three-cell table.","cn":"分类：这个形容词把个案定位到三分表格中。"},{"senses":"08","en":"METAPHOR: abstract exchanges still require a measurable gain on both sides.","cn":"比喻：抽象交换仍要求双方都有可衡量的收益。"}]},"affixes":{"intro":{"en":"The word carries two suffixes stacked on a Latin stem: -ism makes the system, -istic makes the adjective that describes it.","cn":"这个词在拉丁词干上叠了两层后缀：-ism 造出体系，-istic 造出描述该体系的形容词。"},"latinIntro":{"en":"Mutuus is Latin, while -ismus and -isticus arrived through Greek; English added the final -al and -ly layers.","cn":"mutuus 是拉丁语，而 -ismus 与 -isticus 经希腊语传入；英语又加上了 -al 与 -ly 两层。"},"items":[{"word":"mutualistic","structure":"mutualism + -istic (adjective of practice)","meaning":"marked by mutual benefit","meaningCN":"以互利为特征的","example":"The two ants and the plant are mutualistic.","exampleCN":"这两种蚂蚁与植物是互利共生的。"},{"word":"mutualism","structure":"mutual + -ism (system)","meaning":"the system of reciprocal benefit","meaningCN":"互惠受益的体系","example":"Obligate mutualism binds the pair for life.","exampleCN":"专性互利共生把这一对终身绑定。"},{"word":"mutualist","structure":"mutual + -ist (participant)","meaning":"one party in the system","meaningCN":"体系中的一方","example":"Each mutualist depends on the other's service.","exampleCN":"每个互利共生方都依赖对方的服务。"},{"word":"mutually","structure":"mutual + -ly (adverb)","meaning":"reciprocally","meaningCN":"相互地","example":"The two services are mutually reinforcing.","exampleCN":"这两项服务相互强化。"},{"word":"mutuality","structure":"mutual + -ity (quality)","meaning":"reciprocal quality","meaningCN":"相互性","example":"Mutuality of benefit is the test of the partnership.","exampleCN":"收益的相互性是这段伙伴关系的检验标准。"},{"word":"commensal","structure":"com- (together) + mensa (table) + -al (adjective)","meaning":"feeding at another's table without harm","meaningCN":"在同桌取食而不造成伤害的","example":"A commensal barnacle rides on the whale.","exampleCN":"偏利共生的藤壶搭在鲸身上。"},{"word":"symbiotic","structure":"sym- (together) + bios (life) + -otic (adjective)","meaning":"of any close living-together","meaningCN":"任何紧密共处的","example":"Symbiotic partners may or may not both gain.","exampleCN":"共生伙伴未必双方都获益。"},{"word":"parasitic","structure":"para- (beside) + sitos (food) + -ic","meaning":"feeding at another's expense","meaningCN":"以牺牲他人为代价取食的","example":"A parasitic wasp lays eggs inside its host.","exampleCN":"寄生蜂把卵产在宿主体内。"},{"word":"capitalistic","structure":"capital + -istic (parallel formation)","meaning":"showing the same -ism to -istic pattern","meaningCN":"展示同样的 -ism 到 -istic 构词模式","example":"The suffix behaves the same in capitalistic.","exampleCN":"这个后缀在 capitalistic 中表现相同。"}],"latinEntries":[{"word":"mutuus","structure":"mutuus, mutua, mutuum (adj., first/second declension)","meaning":"reciprocal, exchanged","meaningCN":"相互的、交换的"},{"word":"-isticus","structure":"-isticus (adjective suffix; from Greek -istikos)","meaning":"pertaining to a practice or doctrine","meaningCN":"与某种实践或学说有关的"},{"word":"mensa","structure":"mensa, mensae (n., first declension)","meaning":"table; the source of commensal","meaningCN":"桌子；commensal 一词的来源"}]}},{"word":"commensalism","ipa_uk":"/kəˈmensəlɪzəm/","ipa_us":"/kəˈmensəlɪzəm/","definition_zh":"偏利共生；一方受益而另一方不受影响的共生关系","definition_en":"a symbiotic association in which one partner benefits while the other is essentially unaffected, neither helped nor harmed","core_image":"一只藤壶吸附在鲸鱼背上随它远行，鲸鱼照常游动，藤壶却获得了水流与食物","scene":"The barnacles on the whale gain transport and feeding currents, a clear case of commensalism.","sceneCN":"这里 commensalism 指「偏利共生」（第 1 个义项：一方受益、另一方不受影响）；鲸背上的藤壶获得了移动与取食水流，是偏利共生的清楚例子。图中可辨识物件：鲸鱼、藤壶、水流、浮游生物。","pos":[{"tag":"n.","zh":"偏利共生；一方受益而另一方不受影响的共生关系（不可数指关系类型，可数指一例）"}],"collocations":[{"phrase":"obligate commensalism","zh":"专性偏利共生；受益方离开宿主难以生存"},{"phrase":"facultative commensalism","zh":"兼性偏利共生；受益方并非必须依赖宿主"},{"phrase":"a case of commensalism","zh":"一例偏利共生"},{"phrase":"commensalism between species","zh":"物种之间的偏利共生"},{"phrase":"epiphyte commensalism","zh":"附生植物的偏利共生"},{"phrase":"commensal relationship","zh":"偏利共生关系（常用形容词形式）"}],"forms":[{"label":"复数","form":"commensalisms（指多例或多种偏利共生）"},{"label":"形容词","form":"commensal（偏利共生的；共栖的）"},{"label":"名词（参与者）","form":"commensal（偏利共生生物；共栖者）"},{"label":"副词形式","form":"commensally（以偏利共生的方式；少见）"}],"derivatives":[{"word":"commensal","pos":"adj./n.","zh":"偏利共生的；偏利共生生物；共栖者"},{"word":"mutualism","pos":"n.","zh":"互利共生；双方都受益"},{"word":"parasitism","pos":"n.","zh":"寄生；一方受益、一方受害"},{"word":"symbiosis","pos":"n.","zh":"共生；紧密共处关系"},{"word":"mensa","pos":"n.","zh":"拉丁语「桌子」，仅见于词源说明"},{"word":"commensurable","pos":"adj.","zh":"可通约的；可比较的（形近但词源不同，见 similar）"}],"senses":[{"no":"01","title":"One gains, one is unaffected","titleCN":"一方受益、另一方不受影响","definition":"in ecology, a lasting association in which one species benefits and the other neither benefits nor is harmed","definitionCN":"生态学中指一方获益、另一方既不受益也不受害的持久共处关系","example":"The orchid growing on a tree branch gains height and light without harming the tree.","exampleCN":"长在树枝上的兰花获得了高度与光照，却没有伤害树木。","why":"The term fills the plus-zero cell of the symbiosis table; without it, every one-sided relationship would be lumped with parasitism.","whyCN":"这个词填补共生表格里的「加零」格；没有它，所有单向关系都会被归入寄生。"},{"no":"02","title":"Epiphytes on trees","titleCN":"附生植物：借高处取光而不吸血","definition":"a plant that grows on another plant for support and light while drawing no nutrients from its host's living tissue","definitionCN":"指附着在另一植物上以获得支撑与光照、却不从宿主活体组织吸取养分的植物","example":"Many tropical orchids and ferns are epiphytes that illustrate commensalism.","exampleCN":"许多热带兰花与蕨类是附生植物，是偏利共生的例证。","why":"The epiphyte takes space, not food, so the host pays nothing measurable and the relationship stays plus-zero.","whyCN":"附生植物取走空间而非食物，宿主没有可计量的损失，关系因而停在加零。"},{"no":"03","title":"Hitchhikers in the sea","titleCN":"海上搭车：藤壶借宿主移动","definition":"a marine commensalism in which a sessile organism attaches to a mobile animal and gains transport and feeding currents","definitionCN":"指固着生物附着在移动动物身上、获得移动与取食水流的海洋偏利共生","example":"Barnacles on a whale's skin are a classic marine commensalism.","exampleCN":"鲸皮上的藤壶是经典的海洋偏利共生。","why":"Transport is the whole benefit; the whale's skin is not measurably harmed by a light load of hitchhikers.","whyCN":"移动本身就是全部收益；鲸皮也不会因少量搭车者而受到可测量的损害。"},{"no":"04","title":"Commensal microbiota","titleCN":"共栖菌群：寄居体表与肠道而不致病","definition":"in microbiology, microbes that live on or in a host without causing disease, often feeding on host-derived nutrients","definitionCN":"微生物学中指寄居在宿主体表或体内、不引起疾病、常以宿主来源养分为食的微生物","example":"Skin commensals feed on shed cells and sebum without provoking infection.","exampleCN":"皮肤共栖菌以脱落细胞与皮脂为食，却不引发感染。","why":"Medical usage often blurs the line with mutualism, because some commensals also make vitamins; strictly, the word claims no benefit to the host.","whyCN":"医学用法常与互利共生混淆，因为部分共栖菌还会合成维生素；严格说，这个词并不主张宿主获益。"},{"no":"05","title":"The zero on the ledger","titleCN":"账本上的零：与寄生和互利对照","definition":"the classification role of the term when relationship types are scored by benefit and harm","definitionCN":"指在按受益与受害给关系评分时，该词所起的分类作用","example":"Textbooks place commensalism between mutualism and parasitism in the scoring table.","exampleCN":"教科书在评分表里把偏利共生排在互利共生与寄生之间。","why":"A three-cell table needs a name for the middle case, and the middle case is exactly one plus and one zero.","whyCN":"三分表格需要一个名字来指中间情形，而中间情形正是一个加号、一个零。"},{"no":"06","title":"Commensal species of human habitats","titleCN":"人类居所的伴生种：借屋而居","definition":"in ecology and conservation, animals that live in human-built environments and feed on human leftovers without depending on us for survival","definitionCN":"生态学与保护生物学中指栖居在人类建造环境中、以人类残余物为食、却不依赖人类才能存活的动物","example":"House sparrows and Norway rats are often described as commensal species.","exampleCN":"家麻雀与褐家鼠常被描述为伴生种。","why":"The word extends from organisms on a host to organisms on a household: both take shelter and scraps while the provider is unaffected.","whyCN":"这个词从寄主身上的生物扩展到人类家庭中的生物：两者都借住、借食，而提供者不受影响。"},{"no":"07","title":"Free riding in institutions","titleCN":"机构中的搭便车：一方借力，一方无感","definition":"a figurative use for a small organisation that draws benefit from a larger one's infrastructure without contributing to its costs","definitionCN":"比喻用法，指小机构借用大机构的基础设施获益，却不分担其成本","example":"Critics called the tiny agency a commensal dependent on the ministry's laboratories.","exampleCN":"批评者把这家小机构称作依附于部委实验室的偏利共生者。","why":"The metaphor is deliberately unflattering: it says the relationship is one-sided but not yet harmful enough to be called parasitic.","whyCN":"这个比喻有意带着贬义：它说这层关系是单向的，但还没恶劣到可以叫寄生。"},{"no":"08","title":"The table image","titleCN":"同桌意象：词源自带画面","definition":"the etymological image of eating at another's table, used to explain the concept in teaching","definitionCN":"指「在别人桌上吃饭」这一词源意象，教学中常用它解释该概念","example":"Teachers explain commensalism by picturing a guest eating at a table without paying for the meal.","exampleCN":"教师用「客人在桌边吃饭却不付饭钱」的画面解释偏利共生。","why":"Mensa means table, so the Latin image already encodes the asymmetry: one diner eats, the other merely owns the table.","whyCN":"mensa 意为桌子，拉丁意象本身已编码了不对称：一位食客吃饭，另一位只是拥有桌子。"}],"etymology":{"intro":{"en":"Commensalism is Latin com- 'together' plus mensa 'table' plus -ism, literally 'eating at the same table', coined as a biological term in the nineteenth century.","cn":"commensalism 由拉丁语 com-「共同」、mensa「桌子」与 -ism 构成，字面即「同桌而食」，是 19 世纪造出的生物学名词。"},"items":[{"era":"LATIN MENSA","en":"Mensa meant a table, and the phrase at the same table supplies the image of one party feeding beside another.","cn":"mensa 意为桌子，「在同一张桌旁」提供了意象：一方在另一方身边取食。"},{"era":"COM- TOGETHER","en":"The prefix com- marks sharing or jointness, the same prefix seen in commensal, community and companion.","cn":"前缀 com- 表示共享或共同，同样的前缀也见于 commensal、community 与 companion。"},{"era":"COINAGE IN ZOOLOGY","en":"The Belgian zoologist Pierre-Joseph van Beneden introduced commensalism around the 1870s to describe animals that share another's food supply. The exact first date and text are uncertain.","cn":"比利时动物学家皮埃尔-约瑟夫·范贝内登在 1870 年代前后提出 commensalism，描述分享他人食物来源的动物；确切首见年代与文本存疑。"},{"era":"OLDER MEANING","en":"In older English, commensal could simply mean 'eating together at the same table', a social rather than biological sense with no benefit asymmetry.","cn":"在较早的英语里，commensal 也可仅指「同桌共食」，这是社会义而非生物学义，并不含受益的不对称。"},{"era":"THREE-WAY SCHEME","en":"Twentieth-century ecology standardised the triad mutualism, commensalism and parasitism, fixing commensalism as the plus-zero case.","cn":"20 世纪生态学把互利共生、偏利共生与寄生确立为三分法，把偏利共生固定为加零情形。"},{"era":"TERM DRIFT","en":"Microbiologists now often call any harmless resident microbe commensal even when it benefits the host, so the modern use is looser than the ecological definition.","cn":"如今微生物学家常把所有无害常驻菌称作 commensal，即便它对宿主有益；现代用法因此比生态学定义宽松。"}]},"similar":{"note":{"en":"The look-alike group contains near-identical spellings with unrelated meanings; the near-meaning group is the symbiosis triad again, seen from the zero-benefit side.","cn":"形近组是拼写相近而意义无关的词；近义组仍是共生三分法，但站在「零收益」一侧来看。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"commensal","ipa":"/kəˈmensəl/","tag":"the adjective or the participant","definition":"The adjective form and the count noun for a participant. It describes or names one organism; commensalism names the relationship type.","definitionCN":"形容词形式，也作可数名词指参与者。它描述或命名某个生物；commensalism 则命名关系类型。"},{"word":"commensurable","ipa":"/kəmˈmenʃərəbl/","tag":"a false friend","definition":"Means measurable by the same standard. It comes from Latin mensura 'measure', not mensa 'table', so it has nothing to do with symbiosis.","definitionCN":"意为可用同一标准衡量的。它出自拉丁语 mensura「测量」而非 mensa「桌子」，与共生毫无关系。"},{"word":"commensurate","ipa":"/kəmˈmensərət/","tag":"another false friend","definition":"Means proportionate or corresponding in size. It shares the mensura root and is used of salaries, rewards and penalties.","definitionCN":"意为相称的、在规模上对应的，与 mensura 同根，多用于薪水、报酬与处罚。"}]},{"heading":"NEAR MEANING","entries":[{"word":"mutualism","ipa":"/ˈmjuːtʃuəlɪzəm/","tag":"plus-plus","definition":"Both partners benefit. If the resident microbe supplies vitamins, the correct label is mutualism, not commensalism.","definitionCN":"双方都受益。若常驻微生物供应维生素，正确标签是互利共生，而不是偏利共生。"},{"word":"parasitism","ipa":"/ˈpærəsɪtɪzəm/","tag":"plus-minus","definition":"One partner benefits while the other is harmed. A tapeworm that drains nutrients is parasitic, not commensal.","definitionCN":"一方受益而另一方受害。吸取养分的绦虫是寄生的，不是偏利共生。"},{"word":"phoresy","ipa":"/ˈfɔːrəsi/","tag":"transport-only commensalism","definition":"A specialised form of commensalism in which one organism uses another purely for transport, as mites do on beetles.","definitionCN":"偏利共生的一种专门形式：一方纯粹借另一方搭载移动，如螨虫搭甲虫。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"com- 'together' + mensa 'table': eating at the same table, but only one diner gets fed.","cn":"com-「共同」+ mensa「桌子」：同桌而食，却只有一位食客吃饱。"},{"en":"The family runs commensal, commensalism, commensally and the unrelated commensurable.","cn":"同族词包括 commensal、commensalism、commensally，以及与词源无关的 commensurable。"},{"en":"Remember mensa, not mensura: table, not measurement.","cn":"记住是 mensa 而非 mensura：桌子，不是测量。"},{"en":"Place it in the triad: mutualism plus-plus, commensalism plus-zero, parasitism plus-minus.","cn":"放进三分法：互利是加加，偏利是加零，寄生是加减。"},{"en":"Van Beneden introduced the term in the 1870s, and microbiology later loosened it.","cn":"范贝内登在 1870 年代提出该词，后来微生物学把用法放宽了。"}],"abstract":[{"en":"Picture a barnacle riding a whale, paying no fare and causing no drag the whale can feel.","cn":"想象一只藤壶搭在鲸背上，不付路费，也不造成鲸能感觉到的阻力。"},{"en":"Picture an orchid rooted on a branch, taking light and rain but never a drop of sap.","cn":"想象一株兰花扎根在树枝上，取走光与雨，却从不吸一滴树液。"},{"en":"Picture a small office using a ministry's lab benches after hours, costing the ministry nothing visible.","cn":"想象一家小办公室下班后借用部委的实验台，部委看不出任何损失。"}]},"examples":[{"en":"The epiphytic fern is a textbook example of commensalism.","cn":"这株附生蕨类是教科书式的偏利共生例子。"},{"en":"Researchers tested whether the gut microbes were commensal or truly mutualistic.","cn":"研究者检验这些肠道菌究竟属偏利共生还是真正的互利共生。"},{"en":"The term commensalism was coined before microbiology could measure the host's costs.","cn":"偏利共生一词的提出，早于微生物学能够测量宿主代价的时代。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"com（共同）+ mensa（桌子）→ 同桌吃饭，只有一方吃饱 → commensalism 偏利共生","word":"commensalism"},"root":"拉丁 com-「共同」+ mensa「桌子」+ -ism；字面「同桌而食」，19 世纪动物学用它指一方受益、另一方无损的共生。","sensesIntro":{"en":"Eight senses circle one asymmetry: the ledger has a plus on one side and a zero on the other, never a minus.","cn":"八个义项围绕同一种不对称：账本一边是加号，另一边是零，绝不会是减号。"},"semanticMap":{"core":{"en":"CORE IMAGE: a barnacle on a whale's back, taking a ride that costs the whale nothing.","cn":"核心意象：藤壶附着鲸背，搭一段不花鲸任何代价的顺风车。"},"chain":["PLUS AND ZERO","EPIPHYTIC SUPPORT","MARINE TRANSPORT","RESIDENT MICROBES","SCORING TABLE","HUMAN HABITAT"],"branches":[{"senses":"01","en":"DEFINITION: one partner gains and the other is unaffected.","cn":"定义：一方获益，另一方不受影响。"},{"senses":"02 · 03","en":"SUPPORT AND TRANSPORT: space, light and rides are the currencies of the zero side.","cn":"支撑与移动：空间、光照与搭载是零那一侧的货币。"},{"senses":"04 · 06","en":"RESIDENCE: microbes on skin and animals in houses both live off leftovers.","cn":"寄居：皮肤上的微生物与屋中的动物都靠残余物生活。"},{"senses":"05","en":"CLASSIFICATION: the word exists to fill the middle cell of the triad.","cn":"分类：这个词的存在就是为了填补三分法的中间格。"},{"senses":"07 · 08","en":"IMAGE AND METAPHOR: the table picture explains the concept and lends itself to institutional satire.","cn":"意象与比喻：同桌画面既解释概念，也便于用来讽刺机构关系。"}]},"affixes":{"intro":{"en":"Commensalism is a Latin compound with a Greek-style noun suffix, so every part of the word can be pointed to.","cn":"commensalism 是拉丁复合词加希腊式名词后缀，词里每一部分都能指认出来。"},"latinIntro":{"en":"Com- is the assimilated form of con- 'together', mensa is a first-declension noun, and -ismus came through Greek.","cn":"com- 是 con-「共同」的同化形式，mensa 是第一变格名词，-ismus 则经希腊语传入。"},"items":[{"word":"commensalism","structure":"com- (together) + mensa (table) + -ism (system)","meaning":"the plus-zero relationship type","meaningCN":"加零型关系","example":"Commensalism describes a guest that costs the host nothing.","exampleCN":"偏利共生描述不给宿主造成损失的客人。"},{"word":"commensal","structure":"com- + mensa + -al (adjective)","meaning":"sharing a table; living off another without harm","meaningCN":"同桌的；寄居他人处而无害的","example":"Commensal bacteria colonise the skin surface.","exampleCN":"共栖细菌定植在皮肤表面。"},{"word":"commensally","structure":"commensal + -ly (adverb)","meaning":"in a plus-zero manner","meaningCN":"以偏利共生的方式","example":"The mites travel commensally on the beetle.","exampleCN":"这些螨虫偏利地搭乘甲虫移动。"},{"word":"mutualism","structure":"mutual + -ism (system)","meaning":"the plus-plus relationship type","meaningCN":"加加型关系","example":"Mutualism rewards both partners.","exampleCN":"互利共生让双方都获益。"},{"word":"parasitism","structure":"para- (beside) + sitos (food) + -ism","meaning":"the plus-minus relationship type","meaningCN":"加减型关系","example":"Parasitism costs the host nutrients.","exampleCN":"寄生让宿主损失养分。"},{"word":"symbiosis","structure":"sym- (together) + bios (life) + -osis (process)","meaning":"the umbrella relationship type","meaningCN":"总括性的共生关系","example":"Symbiosis covers all three scores.","exampleCN":"共生涵盖全部三种评分。"},{"word":"mensa","structure":"mensa, mensae (Latin n., first declension)","meaning":"table","meaningCN":"桌子","example":"The Latin root mensa survives inside commensal.","exampleCN":"拉丁词根 mensa 保存在 commensal 之中。"},{"word":"commensurable","structure":"com- + mensura (measure) + -able","meaning":"measurable by a common standard","meaningCN":"可按共同标准衡量的","example":"The two risks are not commensurable.","exampleCN":"这两种风险不可通约比较。"},{"word":"commensurate","structure":"com- + mensura (measure) + -ate","meaning":"proportionate, corresponding","meaningCN":"相称的、对应的","example":"The salary is commensurate with experience.","exampleCN":"薪水与经验相称。"}],"latinEntries":[{"word":"com-","structure":"com- (assimilated form of con-, prefix)","meaning":"together, with","meaningCN":"共同、一起"},{"word":"mensa","structure":"mensa, mensae (n., first declension)","meaning":"table, dining table","meaningCN":"桌子、餐桌"},{"word":"-ismus","structure":"-ismus (suffix; from Greek -ismos)","meaning":"doctrine, practice, condition","meaningCN":"学说、实践、状态"}]}},{"word":"competition","ipa_uk":"/ˌkɒmpəˈtɪʃən/","ipa_us":"/ˌkɑːmpəˈtɪʃən/","definition_zh":"竞争；比赛；竞争对手；生态竞争","definition_en":"the activity of two or more parties striving for the same resource, market, prize or position, and the contest or rivalry that results","core_image":"两条跑道上的短跑选手并肩冲向同一条终点线，观众席只关心谁先触线","scene":"The two firms are locked in competition for the same coastal market.","sceneCN":"这里 competition 指「市场竞争」（第 1 个义项：多方争夺同一市场）；两家公司为同一片沿海市场陷入竞争。图中可辨识物件：两条跑道、终点线、秒表、观众席。","pos":[{"tag":"n.","zh":"竞争；比赛；竞争对手（指活动或状态时不可数，指一场比赛或一例竞争时可数）"}],"collocations":[{"phrase":"intense competition","zh":"激烈竞争"},{"phrase":"competition for resources","zh":"对资源的争夺"},{"phrase":"enter a competition","zh":"参加比赛"},{"phrase":"face competition from","zh":"面临来自……的竞争"},{"phrase":"competitive exclusion","zh":"竞争排斥（生态学术语，常用形容词形式）"},{"phrase":"interspecific competition","zh":"种间竞争"},{"phrase":"a competition between firms","zh":"企业之间的竞争"}],"forms":[{"label":"复数","form":"competitions（多场比赛或多例竞争）"},{"label":"动词","form":"compete（竞争；参加比赛）"},{"label":"形容词","form":"competitive（有竞争力的；竞争性的）"},{"label":"参与者","form":"competitor（竞争者；参赛者）"},{"label":"抽象名词","form":"competitiveness（竞争力）"}],"derivatives":[{"word":"compete","pos":"v.","zh":"竞争；参赛；争夺"},{"word":"competitive","pos":"adj.","zh":"有竞争力的；竞争激烈的"},{"word":"competitor","pos":"n.","zh":"竞争者；参赛者；对手"},{"word":"competitiveness","pos":"n.","zh":"竞争力"},{"word":"competent","pos":"adj.","zh":"有能力的；胜任的（同源但意义已分化，见 similar）"},{"word":"competition policy","pos":"n.","zh":"竞争政策；反垄断政策"}],"senses":[{"no":"01","title":"Rivalry for a market","titleCN":"市场竞争：多家企业争夺同一批顾客","definition":"in economics, the rivalry among sellers who try to win the same buyers by price, quality or service","definitionCN":"经济学中指卖方通过价格、质量或服务争夺同一批买家的较量","example":"Price competition in the airline industry has cut fares on short routes.","exampleCN":"航空业的票价竞争压低了短途航线的价格。","why":"The economic sense treats the market as a fixed prize, so every gain by one seller is a loss for another.","whyCN":"经济义把市场看作一块固定的奖品，因此一家卖家的所得就是另一家的所失。"},{"no":"02","title":"An organised contest","titleCN":"比赛：有规则、有评判的竞技活动","definition":"a structured event in which entrants are judged against rules and a winner is named","definitionCN":"指按规则评判参赛者并评出胜者的有组织活动","example":"She entered the national photography competition and won second prize.","exampleCN":"她参加了全国摄影比赛并获二等奖。","why":"This is the countable everyday sense: competition as an event, not as an abstract state of rivalry.","whyCN":"这是可数的日常义：competition 指一场活动，而不是抽象的竞争状态。"},{"no":"03","title":"Ecological competition","titleCN":"生态竞争：物种争夺有限资源","definition":"in ecology, the interaction in which organisms of the same or different species use a shared resource that is in limited supply","definitionCN":"生态学中指同种或异种生物使用同一种供应有限的资源的相互作用","example":"Interspecific competition for nesting sites pushed the smaller birds to the cliff edges.","exampleCN":"对巢址的种间竞争把较小的鸟挤到了崖边。","why":"Ecology borrowed the market model and applied it to food, space and light, where the prize is survival rather than money.","whyCN":"生态学借用了市场模型，把奖品从金钱换成食物、空间与光，最终奖品是生存。"},{"no":"04","title":"Striving for a position","titleCN":"争夺位置：升学、求职中的竞争","definition":"the general effort of many people to obtain a limited place, job or honour","definitionCN":"指众多人为获得有限的名额、职位或荣誉而付出的努力","example":"Competition for places at the school is severe.","exampleCN":"这所学校名额的竞争非常激烈。","why":"The word covers any scarcity race, not only commercial ones, so admission and hiring are competition too.","whyCN":"这个词覆盖任何稀缺名额的争夺，不限于商业，因此入学与招聘也叫竞争。"},{"no":"05","title":"Competitive exclusion","titleCN":"竞争排斥：两个物种不能长期占据同一生态位","definition":"the ecological principle that two species competing for exactly the same resource cannot coexist indefinitely, so one displaces the other","definitionCN":"生态学原理：两个物种若争夺完全相同的资源，就不能无限期共存，一方会排挤另一方","example":"Competition drove the introduced species to replace the native mussel in the river.","exampleCN":"竞争使入侵物种在河中将本地贻贝取代。","why":"The principle turns competition into a long-run prediction: shared limits force divergence or disappearance.","whyCN":"这一原理把竞争变成长期预测：共享的限制迫使物种分化或消失。"},{"no":"06","title":"Rivalry as a spur","titleCN":"竞争激励：对手推动表现提升","definition":"the motivating effect of a rival, which can raise effort, innovation or performance","definitionCN":"指对手带来的激励效应，可提升努力程度、创新或表现","example":"The coach believes competition within the squad keeps every player sharp.","exampleCN":"教练相信队内竞争能让每名球员保持敏锐。","why":"Here the word names a force rather than an event: rivalry is valued for what it produces in the competitors.","whyCN":"这里这个词指的是一种力量而非事件：竞争因它在竞争者身上产生的结果而受到重视。"},{"no":"07","title":"Selection through competition","titleCN":"演化竞争：个体为配偶与生存而竞争","definition":"in evolutionary biology, the struggle among individuals whose outcome determines which traits are passed on","definitionCN":"演化生物学中指个体之间的较量，其结果决定哪些性状被传递下去","example":"Male competition for mates produced the elaborate antlers of the species.","exampleCN":"雄性为争夺配偶的竞争造就了该物种华丽的鹿角。","why":"Natural selection is literally a competition with winners and losers, so the economic word fits the biological mechanism.","whyCN":"自然选择本身就是有输有赢的竞争，因此这个经济词汇也适用于生物机制。"},{"no":"08","title":"Protected market rivalry","titleCN":"受保护的竞争：反垄断语境下的竞争秩序","definition":"in law and policy, the rivalry that regulators protect by prohibiting cartels, abuse of dominance and anti-competitive mergers","definitionCN":"法律与政策中指监管者通过禁止卡特尔、滥用支配地位与反竞争并购来保护的竞争秩序","example":"The regulator blocked the merger to preserve competition in the retail fuel market.","exampleCN":"监管者阻止了这起并购，以维持零售燃油市场的竞争。","why":"Modern policy treats competition itself as a public good that must be defended, not merely a result that happens.","whyCN":"现代政策把竞争本身当作必须维护的公共品，而不只是自然发生的结果。"}],"etymology":{"intro":{"en":"Competition comes from Latin competere 'to strive together, seek together', built on com- 'together' and petere 'to seek'. Its road from 'seek together' to 'rival' is a story of narrowing.","cn":"competition 出自拉丁语 competere「共同追求、共同争取」，由 com-「共同」与 petere「寻求」构成；从「共同追求」到「相互竞争」的转变是一段词义收窄史。"},"items":[{"era":"LATIN PETERE","en":"Petere meant to seek, aim at or attack, and it supplies the motion at the heart of the word: both parties are heading for the same object.","cn":"petere 意为寻求、瞄准或攻击，它提供这个词的核心动作：双方都朝同一个目标前进。"},{"era":"LATIN COMPETERE","en":"Competere combined com- with petere. In classical Latin it could mean 'to meet together, coincide, be fitting or due' as well as 'to strive with another'. The rivalry sense was one strand among several.","cn":"competere 把 com- 与 petere 组合起来。古典拉丁语中它既可表示「相遇、相符、应归某人」，也可表示「与他人争夺」；竞争义只是其中一条线索。"},{"era":"LATE LATIN COMPETITIO","en":"Late Latin competitio named a striving after something shared. The modern English noun descends from this form rather than from the verb directly.","cn":"晚期拉丁语 competitio 指对共有之物的争夺；现代英语名词承自这一形式，而非直接来自动词。"},{"era":"ENGLISH ENTRY","en":"English competition appears in the early seventeenth century, first in the sense of a joint claim or rivalry, and the sporting contest sense is later. The exact first citation is uncertain.","cn":"英语 competition 在 17 世纪早期出现，最初指共同索取或相互争夺，体育比赛义更晚；确切首见书证存疑。"},{"era":"ECONOMICS AND BIOLOGY","en":"Political economy made competition a central mechanism in the eighteenth and nineteenth centuries, and ecology then applied it to organisms competing for limited resources.","cn":"政治经济学在 18、19 世纪把竞争确立为核心机制，生态学随后把它用于争夺有限资源的生物。"},{"era":"THE COMPETENT BRANCH","en":"The same Latin verb also produced competent and competence, originally 'meeting the requirements'. These relatives no longer carry any sense of rivalry.","cn":"同一个拉丁动词还产生了 competent 与 competence，原义为「符合要求」；这些同族词如今已不含任何竞争意味。"}]},"similar":{"note":{"en":"The look-alike group shares the compet- stem but has split into fitness and rivalry; the near-meaning group names different kinds of contest.","cn":"形近组共享 compet- 词干，但已分化为「胜任」与「竞争」两支；近义组列出不同类型的较量。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"competence","ipa":"/ˈkɒmpətəns/","tag":"fitness, not rivalry","definition":"The ability to do a task well. It comes from the same Latin verb but developed from the 'meeting requirements' sense, so it has nothing to do with beating a rival.","definitionCN":"指胜任某项任务的能力。它同出一个拉丁动词，却从「符合要求」义发展而来，与击败对手毫无关系。"},{"word":"competitor","ipa":"/kəmˈpetɪtə/","tag":"the person or firm","definition":"A count noun for one who competes. It names a participant, while competition names the activity or the event.","definitionCN":"可数名词，指参与竞争的人或企业。它命名参与者，而 competition 命名活动或赛事。"},{"word":"competitive","ipa":"/kəmˈpetɪtɪv/","tag":"the adjective","definition":"Describes a market, price or person that is marked by rivalry or able to survive it. The noun names the rivalry itself.","definitionCN":"描述带有竞争性的市场、价格或人，或能在竞争中存活者。名词则指竞争本身。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rivalry","ipa":"/ˈraɪvəlri/","tag":"long-term personal edge","definition":"A lasting state of competition between two parties, often with emotional intensity. Competition can be a single event; rivalry implies history.","definitionCN":"指两方长期竞争的状态，常带情绪强度。competition 可以是一场比赛；rivalry 则暗示有历史积怨。"},{"word":"contest","ipa":"/ˈkɒntest/","tag":"the event itself","definition":"A specific competition with rules and a result. It is close to the sporting sense of competition but rarely used for market rivalry.","definitionCN":"指有规则、有结果的具体比赛。它接近 competition 的体育义，但很少用于市场竞争。"},{"word":"contention","ipa":"/kənˈtenʃən/","tag":"dispute as well as contest","definition":"Rivalry or disagreement, often verbal. It can mean a fight for a prize, but it also covers argument, which competition does not.","definitionCN":"指争夺或分歧，常指言语上的。它可表示为奖项而争，也涵盖争论，而 competition 不含争论义。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"com- 'together' + petere 'seek': several parties seeking the same thing.","cn":"com-「共同」+ petere「寻求」：多方共同追求同一样东西。"},{"en":"The family runs compete, competitor, competitive, competitiveness and competition.","cn":"同族词包括 compete、competitor、competitive、competitiveness、competition。"},{"en":"Fixed phrases mark the field: intense competition, competition for resources, enter a competition.","cn":"固定搭配标出领域：激烈竞争、资源争夺、参加比赛。"},{"en":"Competent is a cousin, not a synonym: it means fit for the task, not eager to win.","cn":"competent 是远亲而非同义词：意为胜任任务，而非急于取胜。"},{"en":"Ecology pairs it with exclusion: competition can push one species out of a niche.","cn":"生态学把它与排斥配对：竞争能把一个物种挤出生态位。"}],"abstract":[{"en":"Picture two runners on parallel lanes, both staring at the same white line.","cn":"想象两条平行跑道上的两名选手，都盯着同一条白线。"},{"en":"Picture two shops on one street cutting prices until only one can still pay rent.","cn":"想象同一条街上的两家店铺不断降价，直到只剩一家还付得起房租。"},{"en":"Picture two birds fighting over one hollow in a dead tree while a third waits below.","cn":"想象两只鸟争夺枯树上的同一个树洞，第三只在一旁等待。"}]},"examples":[{"en":"Competition between the two airlines lowered prices but also cut services.","cn":"两家航空公司之间的竞争压低了价格，却也削减了服务。"},{"en":"The biologist measured competition between the native and introduced snails.","cn":"生物学家测量了本地螺与入侵螺之间的竞争。"},{"en":"She won the regional competition with a portrait of her grandmother.","cn":"她凭一幅祖母肖像赢得了地区比赛。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"com（共同）+ pet（追求）→ 大家一起追同一个目标 → competition 竞争","word":"competition"},"root":"拉丁 com-「共同」+ petere「寻求、争取」→ competere「共同追求」→ 晚期拉丁 competitio；英语 17 世纪借入，后成为经济与生态学的核心概念。","sensesIntro":{"en":"Eight senses share one structure: two or more parties, one limited prize. The prize may be a market, a medal, a niche, a place or a mate.","cn":"八个义项共享同一结构：两方或多方，一份有限的奖品。奖品可以是市场、奖牌、生态位、名额或配偶。"},"semanticMap":{"core":{"en":"CORE IMAGE: two runners on parallel lanes aimed at the same finish line.","cn":"核心意象：两条平行跑道上的两名选手冲向同一条终点线。"},"chain":["SHARED GOAL","RIVALRY","MARKET RACE","ORGANISED CONTEST","RESOURCE SCARCITY","SELECTION PRESSURE"],"branches":[{"senses":"08","en":"MARKET RULES: regulators defend the race itself.","cn":"市场规则：监管者保护这场竞赛本身。"},{"senses":"02 · 04","en":"SCARCITY: contests and admissions are the same race for a limited slot.","cn":"稀缺：比赛与入学都是为有限名额进行的同一场竞赛。"},{"senses":"05 · 07","en":"ECOLOGY AND EVOLUTION: food, space and mates are prizes whose losers may disappear.","cn":"生态与演化：食物、空间与配偶都是奖品，输家可能消失。"},{"senses":"06","en":"MOTIVATION: rivalry is also valued for the effort it pulls out of people.","cn":"动机：竞争也因它能激发人的努力而受到重视。"},{"senses":"01 · 03","en":"THE WORD ITSELF: both market and ecology inherit the Latin image of seeking together.","cn":"词本身：市场与生态都继承了拉丁语「共同寻求」的意象。"}]},"affixes":{"intro":{"en":"Competition is a Latin verb turned noun, so its parts are the prefix com-, the root pet- and the noun suffix -ition.","cn":"competition 是拉丁动词变来的名词，构词部分是前缀 com-、词根 pet- 与名词后缀 -ition。"},"latinIntro":{"en":"Com- marks joint action, petere supplies seeking, and -itio is the Latin noun-of-action ending that English turned into -ition.","cn":"com- 表示共同行动，petere 提供「寻求」义，-itio 是拉丁动名词词尾，英语转写为 -ition。"},"items":[{"word":"competition","structure":"com- (together) + petere (seek) + -ition (noun of action)","meaning":"the act of seeking something jointly or against others","meaningCN":"共同或对抗性地追求某物的行为","example":"Competition for the contract lasted six months.","exampleCN":"对这份合同的争夺持续了六个月。"},{"word":"compete","structure":"com- + petere (verb)","meaning":"to strive for the same object","meaningCN":"为同一目标而争取","example":"Three teams will compete for the trophy.","exampleCN":"三支队伍将争夺这座奖杯。"},{"word":"competitive","structure":"compete + -ive (adjective)","meaning":"marked by or able to survive rivalry","meaningCN":"具有竞争性的或能在竞争中存活的","example":"The firm offers competitive prices.","exampleCN":"这家公司提供有竞争力的价格。"},{"word":"competitor","structure":"compete + -or (agent noun)","meaning":"one who competes","meaningCN":"参与竞争者","example":"Each competitor must declare its costs.","exampleCN":"每个竞争者都必须申报成本。"},{"word":"competitiveness","structure":"competitive + -ness (quality)","meaning":"the quality of being able to compete","meaningCN":"能够竞争的性质","example":"The report ranks national competitiveness.","exampleCN":"该报告对国家竞争力进行排名。"},{"word":"competent","structure":"com- + petere + -ent (adjective)","meaning":"fit for a task, originally 'meeting requirements'","meaningCN":"胜任任务的，原义为「符合要求」","example":"She is a competent editor.","exampleCN":"她是一位称职的编辑。"},{"word":"competence","structure":"competent + -ence (noun of state)","meaning":"the state of being fit for a task","meaningCN":"胜任任务的状态","example":"The job requires technical competence.","exampleCN":"这份工作需要技术胜任力。"},{"word":"petition","structure":"petere + -ition (noun of action)","meaning":"a formal request, literally a seeking","meaningCN":"正式请求，字面即「寻求」","example":"Residents filed a petition against the road.","exampleCN":"居民提交了一份反对修路的请愿书。"},{"word":"appetite","structure":"ad- (toward) + petere + -ite","meaning":"a seeking toward food; desire","meaningCN":"对食物的追求；欲望","example":"Exercise sharpened his appetite.","exampleCN":"运动让他食欲大增。"}],"latinEntries":[{"word":"com-","structure":"com- (assimilated form of con-, prefix)","meaning":"together, with","meaningCN":"共同、一起"},{"word":"petere","structure":"petere, peto, petivi, petitum (v., third conjugation)","meaning":"to seek, aim at, attack","meaningCN":"寻求、瞄准、攻击"},{"word":"-itio","structure":"-itio, -itionis (noun-of-action suffix)","meaning":"the act or process of doing","meaningCN":"行为或过程"}]}},{"word":"competitive","ipa_uk":"/kəmˈpetɪtɪv/","ipa_us":"/kəmˈpetɪtɪv/","definition_zh":"有竞争力的；竞争性的；好胜的；竞争激烈的","definition_en":"able to compete successfully, marked by rivalry, or describing a person who is eager to win","core_image":"两家相邻店铺把同一款商品的价格牌翻来翻去，顾客在门口来回比较","scene":"The company keeps its prices competitive by renegotiating supply contracts every year.","sceneCN":"这里 competitive 指「有竞争力的」（第 1 个义项：价格足以与对手抗衡）；公司每年重谈供应合同，以保持价格竞争力。图中可辨识物件：价格牌、两家店铺、顾客、合同。","pos":[{"tag":"adj.","zh":"有竞争力的；竞争性的；好胜的（比较级 more competitive，最高级 most competitive）"}],"collocations":[{"phrase":"competitive advantage","zh":"竞争优势"},{"phrase":"competitive market","zh":"竞争性市场"},{"phrase":"competitive price","zh":"有竞争力的价格"},{"phrase":"competitive edge","zh":"竞争优势；胜人一筹之处"},{"phrase":"highly competitive","zh":"竞争非常激烈的；极具竞争力的"},{"phrase":"competitive exam","zh":"选拔性考试；竞争性考试"},{"phrase":"competitive salary","zh":"有竞争力的薪酬"}],"forms":[{"label":"比较级","form":"more competitive"},{"label":"最高级","form":"most competitive"},{"label":"副词形式","form":"competitively（以有竞争力的方式；竞争地）"},{"label":"名词形式","form":"competitiveness（竞争力）"},{"label":"动词形式","form":"compete（竞争）"}],"derivatives":[{"word":"compete","pos":"v.","zh":"竞争；参赛"},{"word":"competition","pos":"n.","zh":"竞争；比赛"},{"word":"competitor","pos":"n.","zh":"竞争者；对手"},{"word":"competitively","pos":"adv.","zh":"有竞争力地；以竞争方式"},{"word":"competitiveness","pos":"n.","zh":"竞争力"},{"word":"noncompetitive","pos":"adj.","zh":"非竞争性的；不参与竞争的"}],"senses":[{"no":"01","title":"Able to match rivals","titleCN":"有竞争力：价格或条件足以与对手抗衡","definition":"describing a price, product or firm that can match or beat what rivals offer","definitionCN":"描述价格、产品或企业足以匹敌或胜过对手所提供的条件","example":"The airline offers competitive fares on long-haul routes.","exampleCN":"这家航空公司在长途航线上提供有竞争力的票价。","why":"The adjective shifts the focus from the race to the capacity to survive it: what matters is being able to stay in the market.","whyCN":"这个形容词把焦点从比赛转到生存能力：关键是能否留在市场里。"},{"no":"02","title":"Rivalry-shaped market","titleCN":"竞争性市场：由多方较量构成的市场","definition":"describing a market or sector in which many sellers actively contend for buyers","definitionCN":"描述许多卖家积极争夺买家的市场或行业","example":"Telecoms is a fiercely competitive sector with thin margins.","exampleCN":"电信是一个竞争激烈、利润微薄的行业。","why":"Here the adjective describes the structure of a market rather than any single firm's strength.","whyCN":"这里这个形容词描述市场结构，而不是某一家企业的强弱。"},{"no":"03","title":"Eager to win","titleCN":"好胜：个人把胜负看得很重","definition":"describing a person who is strongly motivated to outperform others, sometimes to the point of tension","definitionCN":"描述极力想要胜过他人的人，有时紧张到产生压力","example":"He is too competitive to enjoy a friendly game.","exampleCN":"他太好胜，连友谊赛都无法轻松享受。","why":"The same word moves from markets to personalities, where it can be praise or criticism depending on degree.","whyCN":"同一个词从市场移到性格，依据程度不同可以是赞扬也可以是批评。"},{"no":"04","title":"Ecological competitive ability","titleCN":"生态竞争力：在资源争夺中占优的能力","definition":"in ecology, describing a species' capacity to acquire shared resources and displace rivals","definitionCN":"生态学中描述一个物种获取共享资源并排挤对手的能力","example":"The invasive grass is more competitive than the native bunchgrass in dry soil.","exampleCN":"在干燥土壤中，这种入侵草比本地丛生草更具竞争力。","why":"Competitive ability is measured in survivors, not revenue, but the underlying logic of scarce resources is identical.","whyCN":"生态竞争力以存活者而非营收来衡量，但资源稀缺这一底层逻辑完全相同。"},{"no":"05","title":"Selection by contest","titleCN":"选拔性：以竞争方式筛选","definition":"describing an exam, admission process or grant scheme that selects a limited number from many applicants","definitionCN":"描述从众多申请者中选出有限名额的考试、录取或资助机制","example":"Entry to the programme is competitive, with only one place for every twenty applicants.","exampleCN":"该项目的录取具有竞争性，每二十名申请者只有一个名额。","why":"The adjective marks scarcity plus ranking: the process is not merely difficult but deliberately comparative.","whyCN":"这个形容词标出「稀缺加排名」：过程不只是难，而是有意把人放在一起比较。"},{"no":"06","title":"Sporting rivalry","titleCN":"竞技体育：以胜负为目的的比赛性质","definition":"describing sport or play organised around winning rather than recreation","definitionCN":"描述以取胜而非娱乐为目的组织起来的运动或游戏","example":"Competitive swimming demands years of structured training.","exampleCN":"竞技游泳需要多年系统训练。","why":"The adjective separates the same physical activity into two institutions: competitive sport and casual exercise.","whyCN":"这个形容词把同一种身体活动分成两种制度：竞技体育与休闲锻炼。"},{"no":"07","title":"Strategic advantage","titleCN":"战略优势：相对对手的持久长处","definition":"in business strategy, describing a resource, position or capability that lets a firm outperform rivals over time","definitionCN":"商业战略中指让企业长期胜过对手的资源、地位或能力","example":"Its port access gives the firm a competitive advantage in shipping.","exampleCN":"港口准入让这家公司在航运上拥有竞争优势。","why":"The phrase competitive advantage turns the adjective into a noun modifier for the thing that wins the race.","whyCN":"competitive advantage 这一短语把形容词变成名词修饰语，指赢得竞赛的那个东西。"},{"no":"08","title":"Pay that matches the market","titleCN":"薪酬有竞争力：足以留住人","definition":"describing a salary or benefits package that is at or above the level rivals pay for similar work","definitionCN":"描述与对手为同类工作支付的薪酬持平或更高的薪水与福利","example":"The advert promises a competitive salary plus relocation support.","exampleCN":"招聘广告承诺有竞争力的薪酬外加搬迁补助。","why":"Recruitment turns the race into a bidding contest, so the adjective now modifies pay rather than products.","whyCN":"招聘把竞赛变成出价较量，于是这个形容词修饰的对象从产品变成薪酬。"}],"etymology":{"intro":{"en":"Competitive adds the Latin adjective suffix -ivus to the verb compete, which descends from competere 'to strive together'.","cn":"competitive 在动词 compete 上加拉丁形容词后缀 -ivus，而 compete 出自 competere「共同争取」。"},"items":[{"era":"LATIN COMPETERE","en":"Competere joined com- 'together' with petere 'seek'. Its classical meanings included 'meet, coincide, be due' as well as 'contend with'.","cn":"competere 把 com-「共同」与 petere「寻求」结合；古典义既包括「相遇、相符、应归」，也包括「与他人争夺」。"},{"era":"ENGLISH COMPETE","en":"The verb entered English in the sixteenth century, and the rivalry sense became dominant as commercial and sporting competition spread.","cn":"动词在 16 世纪进入英语；随着商业与体育竞赛普及，竞争义逐渐占据主导。"},{"era":"LATIN -IVUS","en":"The suffix -ivus formed adjectives meaning 'having the nature of' or 'tending to', and English renders it as -ive.","cn":"后缀 -ivus 构成意为「具有……性质」或「倾向于……」的形容词，英语转写为 -ive。"},{"era":"ECONOMIC SPREAD","en":"In the nineteenth century competitive became a standard descriptor of markets and prices, and the phrase competitive advantage followed in the twentieth.","cn":"19 世纪 competitive 成为市场与价格的标准描述词，20 世纪又出现了 competitive advantage 这一说法。"},{"era":"UNCERTAIN DETAILS","en":"The exact date of the first English use of the adjective is uncertain; it is generally placed in the seventeenth century, alongside the noun.","cn":"这个形容词在英语中首见的准确年代存疑，一般认为与名词同期，在 17 世纪。"}]},"similar":{"note":{"en":"The look-alike group differs by suffix and part of speech; the near-meaning group separates types of advantage and rivalry.","cn":"形近组只差后缀与词性；近义组则区分不同类型的优势与对抗。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"competition","ipa":"/ˌkɒmpəˈtɪʃən/","tag":"the noun","definition":"The rivalry or the contest itself. A firm can face competition, but its prices are competitive.","definitionCN":"指竞争或比赛本身。企业可以面临 competition，但它的价格是 competitive。"},{"word":"competent","ipa":"/ˈkɒmpətənt/","tag":"skilled, not rivalrous","definition":"Means capable and qualified. It comes from the same Latin verb but follows the 'fit for the task' branch, not the rivalry branch.","definitionCN":"意为有能力、合格的。它同出一个拉丁动词，但走的是「胜任任务」这一支，而非竞争支。"},{"word":"competitor","ipa":"/kəmˈpetɪtə/","tag":"the rival","definition":"A noun for the party you are racing against. It cannot modify a price or a market.","definitionCN":"名词，指与你竞赛的一方。它不能修饰价格或市场。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rivalrous","ipa":"/ˈraɪvəlrəs/","tag":"defined by consumption","definition":"In economics, describes a good that one person's use reduces for others. It is a technical term about goods, not about firms' behaviour.","definitionCN":"经济学中描述一个人使用就会减少他人可用量的物品。它是关于物品的术语，不描述企业行为。"},{"word":"cut-throat","ipa":"/ˈkʌtθrəʊt/","tag":"ruthless intensity","definition":"Describes competition that is ruthless and damaging. Competitive is neutral; cut-throat adds moral condemnation.","definitionCN":"形容竞争残酷而有害。competitive 是中性词，cut-throat 则加上道德谴责。"},{"word":"advantageous","ipa":"/ˌædvənˈteɪdʒəs/","tag":"favourable, not rivalry","definition":"Means giving a benefit or edge. It describes the position, not the contest, and does not require an opponent.","definitionCN":"意为带来好处或优势的。它描述位置而非竞赛，也不需要有对手。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"compete + -ive: having the quality needed to stay in the race.","cn":"compete + -ive：具备留在竞赛中所需要的性质。"},{"en":"Typical phrases: competitive advantage, competitive market, competitive price, competitive edge.","cn":"典型搭配：竞争优势、竞争性市场、有竞争力的价格、竞争优势。"},{"en":"The family runs compete, competition, competitor, competitively and competitiveness.","cn":"同族词包括 compete、competition、competitor、competitively、competitiveness。"},{"en":"Competent is the cousin from the 'fit for the task' branch, not a synonym.","cn":"competent 是「胜任任务」那一支的远亲，不是同义词。"},{"en":"Use more competitive and most competitive; the adjective takes periphrastic comparison.","cn":"比较级用 more competitive，最高级用 most competitive，属迂回比较。"}],"abstract":[{"en":"Picture two shopkeepers flipping their price tags back and forth while a customer waits.","cn":"想象两位店主来回翻动价格牌，顾客在一旁等待。"},{"en":"Picture a runner who is not the fastest but never drops out, so she is still there at the end.","cn":"想象一名并非最快却从不退赛的跑者，终点时她仍在场上。"},{"en":"Picture a grass species that takes the scarce water first, leaving the native grass dry.","cn":"想象一种草先抢走稀缺的水，让本地草干枯。"}]},"examples":[{"en":"The firm's port access is a durable competitive advantage.","cn":"这家公司的港口准入是一项持久的竞争优势。"},{"en":"Admission to the medical school is highly competitive.","cn":"这所医学院的录取竞争非常激烈。"},{"en":"The invasive weed is more competitive than the native grass in dry years.","cn":"在干旱年份，这种入侵杂草比本地草更具竞争力。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"compete（竞争）+ ive（……的）→ 能竞争、有竞争力的 → competitive","word":"competitive"},"root":"拉丁 competere「共同争取」→ 英语 compete + 拉丁形容词后缀 -ivus（英语 -ive）。","sensesIntro":{"en":"Eight senses share one adjective: whatever can hold its place in a race, whether a price, a market, a person, a species or a salary.","cn":"八个义项共享同一个形容词：凡能在竞赛中守住位置的东西，无论价格、市场、人、物种还是薪酬。"},"semanticMap":{"core":{"en":"CORE IMAGE: two shops flipping price tags while a customer compares.","cn":"核心意象：两家店铺来回翻价格牌，顾客在一旁比较。"},"chain":["ABLE TO MATCH","RIVALRY-STRUCTURED","EAGER TO WIN","SELECTION BY RANK","STRATEGIC EDGE","MARKET-LEVEL PAY"],"branches":[{"senses":"01 · 02","en":"MARKET FITNESS: being able to match rivals is the base sense, and a competitive market is one where many try.","cn":"市场适应力：能与对手匹敌是基本义，竞争性市场则是多方尝试的市场。"},{"senses":"03","en":"PERSONALITY: the adjective moves from prices to people, where eagerness to win can become a flaw.","cn":"性格：形容词从价格移到人，好胜在这里可能变成缺点。"},{"senses":"04 · 05","en":"SELECTION: ecology and admissions both rank candidates under scarcity.","cn":"选拔：生态学与录取都在稀缺下给候选者排名。"},{"senses":"06","en":"SPORT: the same adjective separates play from organised contest.","cn":"体育：同一个形容词把玩耍与有组织的竞赛分开。"},{"senses":"07 · 08","en":"ADVANTAGE AND PAY: strategy and recruitment turn the adjective into a claim about lasting edge and market-level rewards.","cn":"优势与薪酬：战略与招聘把这个形容词变成关于持久长处与市场水平报酬的说法。"}]},"affixes":{"intro":{"en":"Competitive is a Latin verb plus the adjective suffix -ive, with a large English family built on the same stem.","cn":"competitive 是拉丁动词加形容词后缀 -ive，同一词干还长出一大批英语同族词。"},"latinIntro":{"en":"The root is petere 'seek', the prefix com- 'together', and the suffix -ivus marks a tendency or capacity.","cn":"词根是 petere「寻求」，前缀 com-「共同」，后缀 -ivus 表示倾向或能力。"},"items":[{"word":"competitive","structure":"compete + -ive (having the nature of)","meaning":"able or tending to compete","meaningCN":"能够或倾向于竞争的","example":"The sector remains competitive.","exampleCN":"该行业仍具竞争力。"},{"word":"compete","structure":"com- (together) + petere (seek)","meaning":"to strive for a shared goal","meaningCN":"为共同目标而争取","example":"Small firms compete on service.","exampleCN":"小企业靠服务竞争。"},{"word":"competition","structure":"competere + -ition (action noun)","meaning":"the rivalry or contest","meaningCN":"竞争或比赛","example":"Competition kept prices low.","exampleCN":"竞争使价格保持低位。"},{"word":"competitor","structure":"compete + -or (agent)","meaning":"a rival participant","meaningCN":"竞争参与者","example":"Each competitor filed a bid.","exampleCN":"每个竞争者都提交了报价。"},{"word":"competitively","structure":"competitive + -ly (adverb)","meaning":"in a competitive way","meaningCN":"以竞争的方式","example":"The service is priced competitively.","exampleCN":"这项服务的定价很有竞争力。"},{"word":"competitiveness","structure":"competitive + -ness (abstract quality)","meaning":"capacity to compete","meaningCN":"竞争能力","example":"Competitiveness depends on productivity.","exampleCN":"竞争力取决于生产率。"},{"word":"noncompetitive","structure":"non- (not) + competitive","meaning":"arranged without rivalry","meaningCN":"不按竞争方式安排的","example":"The children played a noncompetitive game.","exampleCN":"孩子们玩了一个非竞争性游戏。"},{"word":"petition","structure":"petere + -ition","meaning":"a formal seeking or request","meaningCN":"正式的寻求或请求","example":"The petition gathered ten thousand signatures.","exampleCN":"请愿书征集到一万个签名。"},{"word":"appetite","structure":"ad- (toward) + petere + -ite","meaning":"a seeking toward food or pleasure","meaningCN":"对食物或快感的追求","example":"The smell renewed his appetite.","exampleCN":"这香味重新勾起了他的食欲。"}],"latinEntries":[{"word":"petere","structure":"petere, peto, petivi, petitum (v., third conjugation)","meaning":"to seek, aim at","meaningCN":"寻求、瞄准"},{"word":"com-","structure":"com- (assimilated form of con-)","meaning":"together","meaningCN":"共同"},{"word":"-ivus","structure":"-ivus, -iva, -ivum (adjective suffix)","meaning":"having the nature of, tending to","meaningCN":"具有……性质的、倾向于……的"}]}},{"word":"predation","ipa_uk":"/prɪˈdeɪʃən/","ipa_us":"/prɪˈdeɪʃən/","definition_zh":"捕食；掠夺；掠食行为","definition_en":"the act of one organism killing and eating another, and by extension any aggressive exploitation of one party by another","core_image":"一只猫头鹰在夜色中俯冲，利爪扣住田鼠，草丛里只剩一撮毛","scene":"Seed predation by beetles removes a large share of the acorn crop each autumn.","sceneCN":"这里 predation 指「捕食」（第 1 个义项：一种生物杀死并吃掉另一种生物）；甲虫对种子的捕食每年秋天带走大量橡子。图中可辨识物件：猫头鹰、田鼠、橡子、甲虫。","pos":[{"tag":"n.","zh":"捕食；掠夺；掠食行为（指过程时不可数，指一例捕食事件时可数）"}],"collocations":[{"phrase":"predation pressure","zh":"捕食压力"},{"phrase":"seed predation","zh":"种子捕食"},{"phrase":"predation risk","zh":"被捕食风险"},{"phrase":"predation rate","zh":"捕食率"},{"phrase":"predator-prey dynamics","zh":"捕食者与猎物的动态关系"},{"phrase":"predation event","zh":"一次捕食事件"}],"forms":[{"label":"复数","form":"predations（多起捕食事件；罕用）"},{"label":"施动者名词","form":"predator（捕食者）"},{"label":"形容词","form":"predatory（捕食的；掠夺性的）"},{"label":"动词","form":"prey on（捕食；剥削）"},{"label":"受动者名词","form":"prey（猎物）"}],"derivatives":[{"word":"predator","pos":"n.","zh":"捕食者；掠夺者"},{"word":"predatory","pos":"adj.","zh":"捕食性的；掠夺性的"},{"word":"prey","pos":"n./v.","zh":"猎物；捕食"},{"word":"depredation","pos":"n.","zh":"劫掠；破坏（同源，前缀不同）"},{"word":"praedial","pos":"adj.","zh":"土地的；庄园的（同出拉丁 praedium，形近易混）"},{"word":"predation pressure","pos":"n.","zh":"捕食压力（生态学固定说法）"}],"senses":[{"no":"01","title":"Killing and eating","titleCN":"捕食：一种生物杀死并取食另一种","definition":"in ecology, the interaction in which one organism captures, kills and consumes another","definitionCN":"生态学中指一种生物捕获、杀死并吃掉另一种生物的相互作用","example":"Predation by hawks keeps the mouse population in check.","exampleCN":"鹰的捕食控制住了鼠类数量。","why":"The ecological sense is strictly about a lethal meal, which separates it from parasitism, where the host usually lives on.","whyCN":"生态义严格指致命的取食，这与寄生不同：寄生的宿主通常还活着。"},{"no":"02","title":"The population cycle","titleCN":"数量周期：捕食者与猎物相互拖拽","definition":"the effect of predation on prey numbers and, in turn, on predator numbers over time","definitionCN":"指捕食对猎物种群数量的影响，以及由此反过来影响捕食者数量的长期过程","example":"Predation links the hare and lynx in a ten-year cycle.","exampleCN":"捕食把野兔与猞猁绑在一个十年周期里。","why":"Here the noun names a dynamic rather than a single act: each side's numbers are the other side's food supply and constraint.","whyCN":"这里名词指的是一种动态而非单次行为：双方的数量既是对方的食物，也是对方的限制。"},{"no":"03","title":"Conservation pressure","titleCN":"保护压力：捕食对濒危种群的影响","definition":"in conservation, the mortality that predation imposes on a vulnerable population, often measured as a rate","definitionCN":"保护生物学中指捕食给脆弱种群造成的死亡，常以比率衡量","example":"Predation on nesting chicks rose after the rat invasion.","exampleCN":"鼠类入侵后，对巢中雏鸟的捕食上升。","why":"Conservation turns the interaction into a management variable: too much predation can drive a small population to zero.","whyCN":"保护生物学把这种互动变成管理变量：捕食过多会把小种群推向零。"},{"no":"04","title":"Plundering, literary sense","titleCN":"劫掠：书面语中的抢夺义","definition":"an archaic or literary sense of plundering and raiding, applied to armies or bands rather than animals","definitionCN":"古旧或书面义，指掠夺与劫掠，用于军队或匪帮而非动物","example":"The chronicle records the predations of the border raiders.","exampleCN":"编年史记载了边地劫掠者的掠夺。","why":"This is the oldest sense: Latin praeda meant booty, so predation once described taking goods by force.","whyCN":"这是最古老的义项：拉丁语 praeda 意为战利品，因此 predation 原指以武力夺取财物。"},{"no":"05","title":"Predatory pricing","titleCN":"掠夺性定价：以低价挤垮对手","definition":"in competition law, a firm's practice of pricing below cost to drive rivals out and then raising prices","definitionCN":"竞争法中指企业以低于成本的价格挤走对手、随后再抬价的作法","example":"Regulators investigated predation in the parcel delivery market.","exampleCN":"监管机构调查了快递市场的掠夺性定价行为。","why":"Antitrust borrowed the animal word because the low price is a lure, and the harm falls on competitors rather than customers.","whyCN":"反垄断借用了动物词汇，因为低价是诱饵，伤害落在竞争者而不是顾客身上。"},{"no":"06","title":"Microbial predation","titleCN":"微生物捕食：细菌也会猎杀细菌","definition":"the killing of bacteria by other bacteria or by protists, an interaction studied in microbial ecology","definitionCN":"指细菌被其他细菌或原生生物杀死，是微生物生态学研究的相互作用","example":"Bacterial predation shapes which strains survive in a biofilm.","exampleCN":"细菌捕食决定了哪些菌株能在生物膜中存活。","why":"The word scales down without changing: a predator still captures and consumes, even when both parties are single cells.","whyCN":"这个词缩小尺度却不改变含义：即便双方都是单细胞，捕食者仍然捕获并消耗猎物。"},{"no":"07","title":"Seed and egg predation","titleCN":"种子与卵的捕食：取食繁殖体","definition":"the consumption of seeds, eggs or larvae, which affects plant recruitment and animal reproduction","definitionCN":"指取食种子、卵或幼体，从而影响植物更新与动物繁殖","example":"Seed predation by ants limits how many seedlings appear in spring.","exampleCN":"蚂蚁对种子的捕食限制了春天出苗的数量。","why":"The prey need not be an adult animal, so the term extends to any reproductive body that is eaten before it can grow.","whyCN":"猎物不一定是成年动物，因此这个词也扩展到任何在成长前就被吃掉的繁殖体。"},{"no":"08","title":"Exploitative conduct","titleCN":"掠夺性行为：人对人的剥削","definition":"a figurative use for aggressive, one-sided exploitation of a person or group by a stronger party","definitionCN":"比喻用法，指强势方对个人或群体进行激进、单向的剥削","example":"The report described the loan scheme as predation on poor households.","exampleCN":"报告把这项贷款计划描述为对贫困家庭的掠夺。","why":"The metaphor keeps the asymmetry of the hunt: one party gains, the other is consumed, and consent is often unequal.","whyCN":"这个比喻保留了捕猎的不对称：一方获益，另一方被吞食，而同意往往并不对等。"}],"etymology":{"intro":{"en":"Predation comes from Latin praedatio 'a plundering', built on praeda 'booty, prey'. Ecology narrowed the word from raiding to eating.","cn":"predation 出自拉丁语 praedatio「劫掠」，其词根 praeda 意为「战利品、猎物」；生态学把这个词从抢劫收窄为取食。"},"items":[{"era":"LATIN PRAEDA","en":"Praeda meant booty taken in war or hunting, and it is the source of prey as well as of predator and predation.","cn":"praeda 指战争或狩猎中夺取的战利品，它既是 prey 的来源，也是 predator 与 predation 的来源。"},{"era":"LATIN PRAEDARI","en":"The verb praedari meant to plunder or take booty, and praedatio named the act. Neither word originally had anything to do with animals eating.","cn":"动词 praedari 意为劫掠、夺取战利品，praedatio 指这一行为；两词原本都与动物取食无关。"},{"era":"THE MISSING D","en":"English prey came through Old French preie, which dropped the d. Predator and predation were later borrowed straight from Latin, so they keep the d that prey lost.","cn":"英语 prey 经古法语 preie 传入，法语丢掉了 d；predator 与 predation 后来直接从拉丁语借入，因此保留了 prey 丢掉的 d。"},{"era":"ECOLOGY NARROWS IT","en":"In the twentieth century ecology restricted predation to the killing and eating of one organism by another. The exact first technical use is uncertain.","cn":"20 世纪生态学把 predation 限定为一种生物杀死并取食另一种生物；确切的最早技术用法存疑。"},{"era":"LAW BORROWS IT","en":"Competition law later formed predatory pricing, extending the hunting image to firms that cut prices to eliminate rivals.","cn":"竞争法后来造出 predatory pricing，把捕猎意象扩展到以低价消灭对手的企业。"}]},"similar":{"note":{"en":"The look-alike group shares the praed- stem but differs in prefix or meaning; the near-meaning group separates predation from other harmful interactions.","cn":"形近组共享 praed- 词干，但前缀或含义不同；近义组把捕食与其他有害互动区分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"predator","ipa":"/ˈpriːdeɪtə/","tag":"the actor","definition":"The organism that kills and eats. It is a count noun for a party, while predation names the act or process.","definitionCN":"指杀死并取食的生物。它是表示一方的可数名词，而 predation 指行为或过程。"},{"word":"depredation","ipa":"/ˌdeprəˈdeɪʃən/","tag":"raiding, with de-","definition":"Means plundering or ravaging, often of crops or property. The prefix de- intensifies the raiding sense; it is not the ecological term.","definitionCN":"意为劫掠或蹂躏，常指庄稼或财产。前缀 de- 强化了劫掠义；它不是生态学术语。"},{"word":"praedial","ipa":"/ˈpreɪdiəl/","tag":"land, not hunting","definition":"Means relating to land or farming, from Latin praedium 'estate'. It looks close to predation but belongs to a different branch.","definitionCN":"意为与土地或农耕有关的，出自拉丁语 praedium「地产」。它看起来接近 predation，却属另一支。"}]},{"heading":"NEAR MEANING","entries":[{"word":"parasitism","ipa":"/ˈpærəsɪtɪzəm/","tag":"host usually survives","definition":"One organism feeds on another without killing it outright. Predation is typically lethal and quick; parasitism is prolonged and non-lethal.","definitionCN":"一种生物以另一种为食但不直接杀死它。捕食通常致命而迅速；寄生则持久而不致命。"},{"word":"herbivory","ipa":"/həˈbɪvəri/","tag":"eating plants","definition":"The consumption of plants by animals. It is a form of predation in the broad sense but is named separately because the prey does not run.","definitionCN":"指动物取食植物。广义上它也是捕食，但因猎物不会逃跑而另立名称。"},{"word":"exploitation","ipa":"/ˌeksplɔɪˈteɪʃən/","tag":"the general economic sense","definition":"The use of another party for gain, often unfairly. It overlaps with figurative predation but carries no image of eating.","definitionCN":"指利用他人获利，常不公平。它与比喻义的 predation 重叠，但不含吞食意象。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"praeda 'booty' is the shared root of prey, predator, predation and predatory.","cn":"praeda「战利品」是 prey、predator、predation、predatory 的共同词根。"},{"en":"The d is the tell: prey lost it in French, while predator and predation kept it from Latin.","cn":"字母 d 是线索：prey 在法语里丢了它，predator 与 predation 则从拉丁语保留了它。"},{"en":"Fixed phrases mark the field: predation pressure, predation risk, seed predation, predation rate.","cn":"固定搭配标出领域：捕食压力、被捕食风险、种子捕食、捕食率。"},{"en":"Contrast the outcomes: predation kills, parasitism usually does not.","cn":"对照结果：捕食致死，寄生通常不致死。"},{"en":"Law uses the same image in predatory pricing: cut prices, kill rivals, raise prices.","cn":"法律在掠夺性定价中沿用同一意象：压价、挤死对手、再抬价。"}],"abstract":[{"en":"Picture an owl dropping onto a field mouse, the grass closing over both.","cn":"想象猫头鹰扑向田鼠，草丛随即合拢。"},{"en":"Picture ants carrying away an acorn before it can sprout.","cn":"想象蚂蚁在橡子发芽前把它搬走。"},{"en":"Picture a large chain selling below cost until the corner shop closes, then raising its prices.","cn":"想象大型连锁店低价倾销直到街角小店关门，然后再抬价。"}]},"examples":[{"en":"Predation by introduced trout reduced the native frog population.","cn":"引入的鳟鱼捕食使本地蛙类种群减少。"},{"en":"The study measured seed predation across three forest types.","cn":"这项研究测量了三种森林类型中的种子捕食。"},{"en":"The tribunal examined whether the price cuts amounted to predation.","cn":"法庭审查这些降价是否构成掠夺性行为。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"predator（捕食者）+ ion（行为）→ 捕食者做的事 → predation 捕食","word":"predation"},"root":"拉丁 praeda「战利品、猎物」→ praedari「劫掠」→ praedatio「劫掠」；英语借入后，生态学把它收窄为「捕食」。","sensesIntro":{"en":"Eight senses keep one shape: a stronger party takes from a weaker one. Ecology limits the taking to food; law and metaphor widen it to rivals and people.","cn":"八个义项保持同一形状：强者从弱者那里取走东西。生态学把取走限定为食物，法律与比喻则扩展到对手与人。"},"semanticMap":{"core":{"en":"CORE IMAGE: an owl taking a field mouse in the dark.","cn":"核心意象：夜色中猫头鹰抓走田鼠。"},"chain":["TAKING BY FORCE","LETHAL FEEDING","POPULATION EFFECT","CONSERVATION PRESSURE","MARKET AGGRESSION","EXPLOITATION"],"branches":[{"senses":"01 · 06 · 07","en":"ECOLOGY: predation is capture plus consumption, at any scale and for any reproductive body.","cn":"生态学：捕食即捕获加消耗，不论尺度、不论繁殖体。"},{"senses":"02 · 03","en":"DYNAMICS: the act becomes a rate, and the rate becomes a management problem.","cn":"动态：单次行为变成比率，比率又变成管理问题。"},{"senses":"04","en":"THE OLD SENSE: raiding and plunder survive in literary and historical writing.","cn":"旧义：劫掠与抢夺仍存于文学与历史书写中。"},{"senses":"05","en":"COMPETITION LAW: below-cost pricing is a hunt with rivals as prey.","cn":"竞争法：低于成本定价是一场以对手为猎物的捕猎。"},{"senses":"08","en":"METAPHOR: exploitation repeats the asymmetry without the teeth.","cn":"比喻：剥削重复了这种不对称，只是没有牙齿。"}]},"affixes":{"intro":{"en":"Predation is a Latin noun of action on the root praed-, with a family split between the d-less prey and the d-full predator.","cn":"predation 是拉丁语 praed- 词根上的行为名词，词族分化为不带 d 的 prey 与带 d 的 predator。"},"latinIntro":{"en":"Praeda supplies the root, praedari the verb, and -atio the action suffix that English turns into -ation.","cn":"praeda 提供词根，praedari 是动词，-atio 是行为后缀，英语转写为 -ation。"},"items":[{"word":"predation","structure":"praedari (plunder) + -ation (action noun)","meaning":"the act of seizing and consuming","meaningCN":"夺取并消耗的行为","example":"Predation structures the whole food web.","exampleCN":"捕食塑造整个食物网。"},{"word":"predator","structure":"praedari + -ator (agent noun)","meaning":"one that seizes and eats","meaningCN":"夺取并取食者","example":"The wolf is an apex predator.","exampleCN":"狼是顶级捕食者。"},{"word":"predatory","structure":"predator + -y (adjective)","meaning":"hunting; exploitatively aggressive","meaningCN":"捕食的；掠夺性的","example":"Predatory lending targets desperate borrowers.","exampleCN":"掠夺性放贷瞄准走投无路的借款人。"},{"word":"prey","structure":"Old French preie, from Latin praeda","meaning":"the animal taken; to hunt","meaningCN":"被捕获的动物；捕食","example":"Owls prey on mice after dusk.","exampleCN":"猫头鹰入夜后捕食老鼠。"},{"word":"depredation","structure":"de- (thoroughly) + praedari + -ation","meaning":"ravaging, plundering","meaningCN":"蹂躏、劫掠","example":"Deer depredation damaged the young orchard.","exampleCN":"鹿群的啃食破坏了幼龄果园。"},{"word":"praedial","structure":"praedium (estate) + -al","meaning":"relating to land","meaningCN":"与土地有关的","example":"Praedial servitudes bind neighbouring estates.","exampleCN":"土地役权约束相邻地产。"},{"word":"predation pressure","structure":"predation + pressure (fixed term)","meaning":"the force predation exerts on a population","meaningCN":"捕食对种群施加的压力","example":"Predation pressure rose near the nesting cliffs.","exampleCN":"巢崖附近的捕食压力上升。"},{"word":"predator-prey","structure":"predator + prey (compound)","meaning":"the paired relationship of hunter and hunted","meaningCN":"捕食者与猎物的成对关系","example":"Predator-prey cycles appear in the fur records.","exampleCN":"捕食者与猎物的周期出现在毛皮记录中。"},{"word":"herbivory","structure":"herba (plant) + vorare (devour) + -y","meaning":"plant eating as a form of predation","meaningCN":"作为捕食形式之一的植食","example":"Herbivory is predation without pursuit.","exampleCN":"植食是不需要追逐的捕食。"}],"latinEntries":[{"word":"praeda","structure":"praeda, praedae (n., first declension)","meaning":"booty, prey","meaningCN":"战利品、猎物"},{"word":"praedari","structure":"praedari, praedor, praedatus sum (v., first conjugation, deponent)","meaning":"to plunder, to take booty","meaningCN":"劫掠、夺取战利品"},{"word":"-atio","structure":"-atio, -ationis (noun-of-action suffix)","meaning":"the act or process of doing","meaningCN":"行为或过程"}]}},{"word":"predator","ipa_uk":"/ˈpriːdeɪtə/","ipa_us":"/ˈpriːdeɪtər/","definition_zh":"捕食者；掠食者；掠夺者","definition_en":"an organism that hunts and kills others for food, or a person, firm or state that exploits weaker parties","core_image":"一头狮子伏在草坡后，目光锁定饮水处的羚羊群","scene":"The lion is the only apex predator left in this valley.","sceneCN":"这里 predator 指「捕食者」（第 1 个义项：捕杀其他动物为食的生物）；狮子是这片谷地仅存的顶级捕食者。图中可辨识物件：狮子、草坡、羚羊群、水坑。","pos":[{"tag":"n.","zh":"捕食者；掠食者；掠夺者（可数，指动物或个人、机构）"}],"collocations":[{"phrase":"apex predator","zh":"顶级捕食者；食物链顶端物种"},{"phrase":"natural predator","zh":"天敌；自然捕食者"},{"phrase":"predator control","zh":"捕食者控制；为保护其他物种而猎杀捕食者"},{"phrase":"predator-prey relationship","zh":"捕食者与猎物的关系"},{"phrase":"predator satiation","zh":"捕食者饱和；靠同步大量繁殖降低被捕食比例"},{"phrase":"corporate predator","zh":"企业掠食者；敌意收购者"},{"phrase":"microbial predator","zh":"微生物捕食者"}],"forms":[{"label":"复数","form":"predators"},{"label":"形容词","form":"predatory（捕食的；掠夺性的）"},{"label":"抽象名词","form":"predation（捕食）"},{"label":"名词（受动者）","form":"prey（猎物）"},{"label":"派生形容词","form":"predator-free（无捕食者的；多见于新西兰保护语境）"}],"derivatives":[{"word":"predation","pos":"n.","zh":"捕食；掠夺"},{"word":"predatory","pos":"adj.","zh":"捕食的；掠夺性的"},{"word":"prey","pos":"n./v.","zh":"猎物；捕食"},{"word":"predacious","pos":"adj.","zh":"捕食性的；掠食的（异体 predaceous）"},{"word":"depredation","pos":"n.","zh":"劫掠；破坏"},{"word":"predatoriness","pos":"n.","zh":"掠夺性；捕食本性（罕用）"}],"senses":[{"no":"01","title":"An animal that hunts","titleCN":"捕食动物：以捕杀为生的生物","definition":"an animal that captures and kills other animals for food","definitionCN":"指通过捕获并杀死其他动物来获得食物的动物","example":"Wolves are social predators that hunt in coordinated packs.","exampleCN":"狼是群居捕食者，以协同的群体方式狩猎。","why":"The core sense names a role in the food web, defined by behaviour rather than by species or diet alone.","whyCN":"核心义项命名食物网中的一种角色，由行为而非仅仅由物种或食性界定。"},{"no":"02","title":"Apex predator","titleCN":"顶级捕食者：成年个体几乎没有天敌","definition":"a predator at the top of its food chain, with no regular natural predator of its own","definitionCN":"指处于食物链顶端、自身没有常规天敌的捕食者","example":"Removing the apex predator allowed deer to overgraze the forest floor.","exampleCN":"移除顶级捕食者后，鹿群把林下植被啃食过度。","why":"The term marks a position rather than a behaviour: the top predator regulates everything below it.","whyCN":"这个说法标出的是位置而非行为：顶级捕食者调节其下所有层级。"},{"no":"03","title":"A person who exploits","titleCN":"掠夺者：以弱者为目标的个人","definition":"a person who systematically exploits vulnerable people for money, power or sexual gratification","definitionCN":"指为金钱、权力或性满足而系统性剥削弱势者的个人","example":"The court described the recruiter as a predator who targeted teenagers.","exampleCN":"法庭把那名招募者描述为专门针对青少年的掠夺者。","why":"The metaphor keeps the hunt: the vulnerable are stalked, isolated and consumed, and the harm is one-sided.","whyCN":"这个比喻保留了捕猎：弱势者被跟踪、被孤立、被吞食，伤害是单向的。"},{"no":"04","title":"Corporate predator","titleCN":"企业掠食者：以收购吞并对手的公司","definition":"a company that grows by aggressively buying or dismantling weaker firms","definitionCN":"指通过激进收购或拆解较弱企业而壮大的公司","example":"The family-owned mill was bought by a corporate predator and closed within a year.","exampleCN":"这家家族磨坊被一家企业掠食者买下，一年内即关闭。","why":"Finance borrowed the animal word for the firm that treats other firms as prey rather than partners.","whyCN":"金融借用了动物词汇，指把其他公司当猎物而非伙伴的企业。"},{"no":"05","title":"Microbial predator","titleCN":"微生物捕食者：猎杀细菌的单细胞生物","definition":"a bacterium or protist that kills and consumes other microbes","definitionCN":"指杀死并消耗其他微生物的细菌或原生生物","example":"The soil bacterium is a microbial predator that drills into other cells.","exampleCN":"这种土壤细菌是微生物捕食者，能钻入其他细胞。","why":"Scale shrinks but the role survives: a predator still captures and consumes, even without a mouth.","whyCN":"尺度缩小了，角色却保留：即使没有嘴，捕食者仍然捕获并消耗。"},{"no":"06","title":"Half of a predator-prey pair","titleCN":"捕食对的一半：与猎物相互定义","definition":"the hunting side of a paired relationship whose two populations rise and fall together","definitionCN":"指成对关系中的狩猎一方，两个种群数量随之共同涨落","example":"The predator and its prey oscillate on offset cycles.","exampleCN":"捕食者与猎物在错开的周期上振荡。","why":"Neither side can be defined alone: a predator is whatever eats the prey, and the prey is whatever the predator eats.","whyCN":"任何一方都无法单独定义：捕食者就是吃猎物的一方，猎物就是被捕食者吃的一方。"},{"no":"07","title":"Predator control","titleCN":"捕食者控制：为保护目标物种而猎杀","definition":"in wildlife management, the deliberate reduction of predator numbers to protect livestock or endangered prey","definitionCN":"野生动物管理中指为保护牲畜或濒危猎物而有意减少捕食者数量","example":"Predator control around the nesting grounds is debated every spring.","exampleCN":"每年春天，巢区周围的捕食者控制都会引发争论。","why":"Management turns the predator into a variable to be adjusted, which is why the word appears in policy rather than only in biology.","whyCN":"管理把捕食者变成可调节的变量，因此这个词不仅出现在生物学，也出现在政策里。"},{"no":"08","title":"Predator satiation","titleCN":"捕食者饱和：以数量洪流换存活率","definition":"an evolutionary strategy in which prey reproduce in overwhelming numbers so that predators cannot eat them all","definitionCN":"指猎物以压倒性数量同步繁殖、使捕食者吃不完的演化策略","example":"Bamboo masting relies on predator satiation to let some seeds survive.","exampleCN":"竹子的集体结实依靠捕食者饱和，让部分种子得以存活。","why":"The term names the predator as a limiting filter: the strategy works only if the predator's appetite is finite.","whyCN":"这个说法把捕食者当作限制性过滤器：策略生效的前提是捕食者的胃口有限。"}],"etymology":{"intro":{"en":"Predator is an English agent noun on Latin praedator 'plunderer', from praeda 'booty'. It began as a word for a raider before ecology made it a word for a hunter.","cn":"predator 是英语在拉丁语 praedator「劫掠者」上构成的施动名词，praedator 又出自 praeda「战利品」。它最初指劫掠者，后来被生态学变成捕猎者。"},"items":[{"era":"LATIN PRAEDA","en":"Praeda meant booty or prey, and the same root produced prey in French and predation in English.","cn":"praeda 意为战利品或猎物，同一词根在法语中产生 prey，在英语中产生 predation。"},{"era":"LATIN PRAEDATOR","en":"Praedator named a plunderer or raider. Its suffix -tor marks the person who performs the act.","cn":"praedator 指劫掠者、抢夺者，后缀 -tor 标出执行该行为的人。"},{"era":"ENGLISH BORROWING","en":"English predator appears in the nineteenth century, first in the raiding sense. The exact first citation is uncertain, and it is generally placed around the 1860s to 1870s.","cn":"英语 predator 在 19 世纪出现，最初取劫掠义；确切首见书证存疑，一般认为在 1860 至 1870 年代。"},{"era":"ECOLOGICAL ROLE","en":"Twentieth-century ecology made predator the standard word for a hunting animal, and the older human sense became figurative.","cn":"20 世纪生态学把 predator 定为狩猎动物的标准词，较早的人事义则退为比喻用法。"},{"era":"WIDER METAPHOR","en":"The word now covers corporate and criminal senses: a predator is anyone who treats others as expendable prey.","cn":"这个词如今覆盖企业与犯罪语境：凡把他人当作可消耗猎物的人，都可被称作 predator。"}]},"similar":{"note":{"en":"The look-alike group separates the actor, the act and the prey; the near-meaning group separates a behavioural role from a dietary class.","cn":"形近组区分施动者、行为与猎物；近义组区分行为角色与食性类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"predation","ipa":"/prɪˈdeɪʃən/","tag":"the act","definition":"The process or event of killing and eating. A predator performs predation; predation is not the animal itself.","definitionCN":"指杀死并取食的过程或事件。捕食者实施捕食；捕食不是动物本身。"},{"word":"predatory","ipa":"/prɪˈdeɪtəri/","tag":"the adjective","definition":"Describes the hunting or exploitative quality. It modifies behaviour, prices or firms, not the animal as a noun.","definitionCN":"描述捕猎或掠夺的性质，修饰行为、价格或企业，而不是作为名词指动物。"},{"word":"predacious","ipa":"/prɪˈdeɪʃəs/","tag":"an older synonym for the adjective","definition":"A variant adjective meaning hunting or predatory, usually of insects and other invertebrates. It is not the noun for the animal.","definitionCN":"形容词异体，意为捕食的，多用于昆虫及其他无脊椎动物。它不是指动物的名词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"carnivore","ipa":"/ˈkɑːnɪvɔː/","tag":"dietary class","definition":"An animal whose diet is mainly flesh. A carnivore need not hunt, since it may be a scavenger, and a predator need not be a mammal.","definitionCN":"指以肉食为主的动物。食肉动物未必捕猎，因为它可能是食腐者；捕食者也未必是哺乳动物。"},{"word":"hunter","ipa":"/ˈhʌntə/","tag":"the act of pursuit","definition":"One that pursues game. It stresses the chase and is used of humans as well as animals, while predator stresses the ecological role.","definitionCN":"指追逐猎物者，强调追捕过程，可用于人也可用于动物；predator 则强调生态角色。"},{"word":"parasite","ipa":"/ˈpærəsaɪt/","tag":"feeds without killing","definition":"An organism that feeds on a host without usually killing it. It exploits, but it does not hunt and consume in the predatory sense.","definitionCN":"指寄生于宿主、通常不杀死宿主的生物。它也剥削，但不进行捕食意义上的猎杀与吞食。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"praeda 'booty' plus -tor 'one who': the one who takes.","cn":"praeda「战利品」加 -tor「做某事的人」：取走东西的那一方。"},{"en":"The family runs predation, predatory, predacious, prey and depredation.","cn":"同族词包括 predation、predatory、predacious、prey、depredation。"},{"en":"Fixed phrases mark the field: apex predator, natural predator, predator control, predator satiation.","cn":"固定搭配标出领域：顶级捕食者、天敌、捕食者控制、捕食者饱和。"},{"en":"A predator hunts; a carnivore eats meat. A scavenger may be a carnivore but not a predator.","cn":"捕食者狩猎；食肉动物吃肉。食腐者可以是食肉动物，却不是捕食者。"},{"en":"In business the word becomes corporate predator: a buyer that treats firms as prey.","cn":"在商业中这个词变成企业掠食者：把公司当猎物的买家。"}],"abstract":[{"en":"Picture a lion low in the grass, eyes fixed on the herd at the water.","cn":"想象狮子压低身子伏在草里，眼睛盯住水边的兽群。"},{"en":"Picture a bacterium drilling into another cell and draining it.","cn":"想象一个细菌钻进另一个细胞并把它吸干。"},{"en":"Picture a fund buying a struggling factory, selling its machines and closing its gates.","cn":"想象一家基金买下经营困难的工厂，卖掉机器，关上大门。"}]},"examples":[{"en":"The removal of the apex predator changed the whole riverbank.","cn":"顶级捕食者的消失改变了整片河岸。"},{"en":"The bacterium is a predator of other microbes in the soil.","cn":"这种细菌是土壤中其他微生物的捕食者。"},{"en":"Regulators accused the fund of acting as a corporate predator.","cn":"监管者指责该基金扮演企业掠食者的角色。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"preda（猎物）+ tor（者）→ 取走猎物的一方 → predator 捕食者","word":"predator"},"root":"拉丁 praeda「战利品、猎物」→ praedator「劫掠者」→ 英语 predator；20 世纪起成为生态学中「捕食者」的标准词。","sensesIntro":{"en":"Eight senses share one role: the stronger party that takes. The prey may be a mouse, a microbe, a rival firm or a vulnerable person.","cn":"八个义项共享同一角色：取走东西的强势一方。猎物可以是老鼠、微生物、对手企业或弱势个人。"},"semanticMap":{"core":{"en":"CORE IMAGE: a lion in the grass watching the herd at the water.","cn":"核心意象：草丛中的狮子盯着水边的兽群。"},"chain":["PLUNDERER","HUNTING ANIMAL","TOP OF THE CHAIN","PAIRED WITH PREY","MANAGED OR FEARED","EXPLOITER"],"branches":[{"senses":"05","en":"THE ANIMAL ROLE: capture and consumption define the predator at every scale.","cn":"动物角色：捕获与消耗在一切尺度上界定捕食者。"},{"senses":"02","en":"POSITION: the apex predator is defined by having no predator above it.","cn":"位置：顶级捕食者由「上方没有捕食者」来界定。"},{"senses":"06 · 07 · 08","en":"PAIRING AND MANAGEMENT: the predator is half of a cycle, a target of culling and a limit that prey can satiate.","cn":"配对与管理：捕食者既是周期的一半，也是被猎杀的对象，还是猎物可以将其填饱的限制。"},{"senses":"04","en":"CORPORATE METAPHOR: firms that treat others as prey inherit the old raider sense.","cn":"企业隐喻：把他人当作猎物的公司，继承了古老的掠夺者含义。"},{"senses":"01 · 03","en":"THE WORD ITSELF: Latin praedator was a plunderer before it was a hunter.","cn":"词本身：拉丁语 praedator 先指劫掠者，后指猎手。"}]},"affixes":{"intro":{"en":"Predator is a Latin agent noun, so its ending -tor tells you it names the one who performs the act.","cn":"predator 是拉丁施动名词，结尾 -tor 告诉你它指执行该行为的一方。"},"latinIntro":{"en":"Praeda is the root, praedari the verb, and -tor the agent suffix that English keeps in predator and competitor.","cn":"praeda 是词根，praedari 是动词，-tor 是施动后缀，英语在 predator 与 competitor 中保留了它。"},"items":[{"word":"predator","structure":"praedari + -tor (agent noun)","meaning":"one who seizes and consumes","meaningCN":"夺取并消耗者","example":"The hawk is a daytime predator.","exampleCN":"鹰是白昼活动的捕食者。"},{"word":"predation","structure":"praedari + -ation (action noun)","meaning":"the act of hunting and eating","meaningCN":"猎杀与取食的行为","example":"Predation limits the rodent population.","exampleCN":"捕食限制了啮齿动物数量。"},{"word":"predatory","structure":"predator + -y (adjective)","meaning":"hunting or exploitatively aggressive","meaningCN":"捕食的或掠夺性的","example":"The firm used predatory pricing.","exampleCN":"这家公司采用了掠夺性定价。"},{"word":"predacious","structure":"praedari + -acious (inclined to)","meaning":"given to hunting","meaningCN":"惯于捕食的","example":"Predacious beetles control aphids.","exampleCN":"捕食性甲虫能控制蚜虫。"},{"word":"prey","structure":"Old French preie, from Latin praeda","meaning":"the animal taken","meaningCN":"被捕获的动物","example":"The prey froze when the shadow passed.","exampleCN":"影子掠过时，猎物僵住了。"},{"word":"depredation","structure":"de- (thoroughly) + praedari + -ation","meaning":"ravaging, plundering","meaningCN":"蹂躏、劫掠","example":"The flock's depredation ruined the crop.","exampleCN":"鸟群的掠夺毁掉了庄稼。"},{"word":"predator-free","structure":"predator + free (without)","meaning":"lacking predators","meaningCN":"没有捕食者的","example":"The island was predator-free before the rats arrived.","exampleCN":"老鼠到来前，这座岛没有捕食者。"},{"word":"predator-prey","structure":"predator + prey (compound)","meaning":"the hunter-hunted pair","meaningCN":"捕食者与猎物这一对","example":"The model tracks predator-prey cycles.","exampleCN":"该模型追踪捕食者与猎物周期。"},{"word":"predatoriness","structure":"predatory + -ness (quality)","meaning":"the quality of being predatory","meaningCN":"掠夺性或捕食本性","example":"The report noted the fund's predatoriness.","exampleCN":"报告指出了该基金的掠夺性。"}],"latinEntries":[{"word":"praeda","structure":"praeda, praedae (n., first declension)","meaning":"booty, prey","meaningCN":"战利品、猎物"},{"word":"praedator","structure":"praedator, praedatoris (n., third declension)","meaning":"plunderer, raider","meaningCN":"劫掠者、抢夺者"},{"word":"-tor","structure":"-tor, -toris (agent-noun suffix)","meaning":"one who does","meaningCN":"做某事的人或物"}]}},{"word":"predatory","ipa_uk":"/prɪˈdeɪtəri/","ipa_us":"/ˈpredətɔːri/","definition_zh":"捕食性的；掠夺性的；剥削性的","definition_en":"describing an animal or behaviour that hunts and kills, or an act that exploits a weaker party for gain","core_image":"一只鹰在上升气流中盘旋，影子掠过地面，田鼠立刻钻进洞里","scene":"Predatory birds circle above the marsh, forcing the rodents to stay under cover.","sceneCN":"这里 predatory 指「捕食性的」（第 1 个义项：以猎杀其他动物为生）；捕食性鸟类在沼泽上空盘旋，迫使啮齿动物躲在掩护下。图中可辨识物件：鹰、上升气流、田鼠洞、沼泽。","pos":[{"tag":"adj.","zh":"捕食性的；掠夺性的；剥削性的（比较级 more predatory，最高级 most predatory）"}],"collocations":[{"phrase":"predatory pricing","zh":"掠夺性定价；以低于成本的价格挤走对手"},{"phrase":"predatory lending","zh":"掠夺性放贷；以不公平条件放款"},{"phrase":"predatory behavior","zh":"掠夺性行为；捕食行为"},{"phrase":"predatory journal","zh":"掠夺性期刊；只收版面费不审稿的期刊"},{"phrase":"predatory bird","zh":"捕食性鸟类；猛禽"},{"phrase":"predatory acquisition","zh":"掠夺性收购"},{"phrase":"predatory instinct","zh":"捕食本能"}],"forms":[{"label":"比较级","form":"more predatory"},{"label":"最高级","form":"most predatory"},{"label":"副词形式","form":"predatorily（以掠夺方式；以捕食方式）"},{"label":"名词形式","form":"predator（捕食者）"},{"label":"异体形容词","form":"predacious（捕食性的，多用于昆虫）"}],"derivatives":[{"word":"predator","pos":"n.","zh":"捕食者；掠夺者"},{"word":"predation","pos":"n.","zh":"捕食；掠夺"},{"word":"prey","pos":"n./v.","zh":"猎物；捕食"},{"word":"predacious","pos":"adj.","zh":"捕食性的（异体 predaceous）"},{"word":"predatorily","pos":"adv.","zh":"以掠夺方式；以捕食方式"},{"word":"predatoriness","pos":"n.","zh":"掠夺性；捕食本性"}],"senses":[{"no":"01","title":"Hunting for food","titleCN":"捕食性：以猎杀其他动物为生","definition":"describing an animal or species that hunts and kills other animals for food","definitionCN":"描述以猎杀其他动物获取食物的动物或物种","example":"Predatory fish control the smaller species in the reef lagoon.","exampleCN":"捕食性鱼类控制着礁湖中的小型物种。","why":"This is the literal base: the adjective marks a hunting way of life rather than a particular species.","whyCN":"这是字面本义：这个形容词标出的是一种狩猎式的生活方式，而不是某个特定物种。"},{"no":"02","title":"Predatory pricing","titleCN":"掠夺性定价：低价挤垮对手再抬价","definition":"in competition law, pricing below cost in order to eliminate rivals and then raise prices","definitionCN":"竞争法中指以低于成本的价格消灭对手、随后再抬价的作法","example":"The airline was fined for predatory pricing on one regional route.","exampleCN":"这家航空公司因在一条区域航线上掠夺性定价而被罚款。","why":"The adjective marks intent: the low price is not generosity but a trap for competitors.","whyCN":"这个形容词标出意图：低价不是慷慨，而是给竞争者设的陷阱。"},{"no":"03","title":"Predatory lending","titleCN":"掠夺性放贷：以不公平条件套住借款人","definition":"describing loans with unfair terms, hidden fees or interest designed to trap vulnerable borrowers","definitionCN":"描述条款不公、费用隐蔽或利息设计成套住弱势借款人的贷款","example":"The regulator banned several predatory lending practices in the payday market.","exampleCN":"监管者禁止了发薪日贷款市场中的若干掠夺性放贷做法。","why":"The prey here is a borrower, and the trap replaces the teeth: the harm comes from contract terms, not force.","whyCN":"这里的猎物是借款人，合同条款代替了牙齿：伤害来自条文，而非暴力。"},{"no":"04","title":"Exploitative behaviour","titleCN":"掠夺性行为：对弱势者的系统性剥削","definition":"describing conduct that targets vulnerable people and treats them as objects to be used","definitionCN":"描述以弱势者为目标、把他们当作可使用之物的行为","example":"The inquiry found a pattern of predatory behavior toward young recruits.","exampleCN":"调查发现了一种针对年轻新人的掠夺性行为模式。","why":"The adjective carries moral weight in this sense: it says the stronger party selected weakness on purpose.","whyCN":"这个形容词在此义带有道德重量：它表明强势方是有意挑选弱者的。"},{"no":"05","title":"Predatory journal","titleCN":"掠夺性期刊：收费而不审稿的出版陷阱","definition":"describing a publisher that charges authors fees while providing no real peer review or editorial service","definitionCN":"描述只向作者收费、却不提供真正同行评审或编辑服务的出版方","example":"The librarian warned students away from predatory journals.","exampleCN":"图书馆员提醒学生远离掠夺性期刊。","why":"Academic publishing borrowed the word because the target is a researcher's need for publication, not their wallet alone.","whyCN":"学术出版借用这个词，因为目标不只是钱包，还有研究者对发表的迫切需求。"},{"no":"06","title":"Predatory acquisition","titleCN":"掠夺性收购：买下并拆解目标公司","definition":"describing a takeover whose aim is to strip assets or eliminate a competitor rather than to run the business","definitionCN":"描述以剥离资产或消灭竞争者而非经营企业为目的的收购","example":"Workers called the takeover predatory because the buyer had already closed two rivals.","exampleCN":"工人称这次收购是掠夺性的，因为买家此前已关掉两家对手。","why":"The financial sense keeps the hunting frame: the acquired firm is consumed, not merged with.","whyCN":"金融义保留了捕猎框架：被收购的公司是被吞食，而不是被合并。"},{"no":"07","title":"Predatory instincts","titleCN":"捕食本能：行为层面的猎杀冲动","definition":"describing innate behavioural drives in an animal that lead it to stalk, chase and kill","definitionCN":"描述动物身上导致其跟踪、追逐与杀死的先天行为驱力","example":"The kitten's predatory instinct appeared before it could hunt successfully.","exampleCN":"幼猫的捕食本能在它真正会狩猎之前就已显现。","why":"Here the adjective describes an internal drive rather than an ecological role, moving from the food web to behaviour.","whyCN":"这里这个形容词描述内在驱力而非生态角色，从食物网移到行为学。"},{"no":"08","title":"Predatory in nature writing","titleCN":"自然写作中的掠食意象：美学化的猛禽","definition":"used in nature writing and poetry to describe the beauty and threat of a hunter, often with admiration","definitionCN":"在自然写作与诗歌中描述猎手的美感与威胁，常带赞赏","example":"The poem fixes on the predatory stillness of the hawk before it drops.","exampleCN":"这首诗聚焦于鹰俯冲前那种捕食者的静止。","why":"The same adjective can be admiring rather than condemnatory when the context is wild nature instead of markets.","whyCN":"当语境是荒野而非市场时，同一个形容词可以是赞赏而非谴责。"}],"etymology":{"intro":{"en":"Predatory comes from Latin praedatorius 'of plunder', an adjective on praedator. English first used it of raiding and later of hunting.","cn":"predatory 出自拉丁语 praedatorius「劫掠的」，是 praedator 的形容词。英语先用它指劫掠，后用于捕猎。"},"items":[{"era":"LATIN PRAEDATORIUS","en":"The adjective praedatorius described what belongs to plunder or a plunderer. Its stem is praeda 'booty'.","cn":"形容词 praedatorius 描述属于劫掠或劫掠者的事物，其词干是 praeda「战利品」。"},{"era":"ENGLISH ENTRY","en":"Predatory entered English in the seventeenth century in the sense of plundering. The exact first citation is uncertain.","cn":"predatory 在 17 世纪进入英语，取劫掠义；确切首见书证存疑。"},{"era":"HUNTING SENSE","en":"As natural history grew in the eighteenth and nineteenth centuries, the adjective shifted toward animals that live by hunting.","cn":"随着 18、19 世纪博物学发展，这个形容词转向指以狩猎为生的动物。"},{"era":"LEGAL AND FINANCIAL SENSE","en":"Twentieth-century law produced predatory pricing and predatory lending, where the adjective marks deliberate harm to weaker parties.","cn":"20 世纪法律造出掠夺性定价与掠夺性放贷，此时形容词标出对弱势方的有意伤害。"},{"era":"ACADEMIC SENSE","en":"The phrase predatory journal spread in the twenty-first century with open-access publishing, and its boundaries are still debated.","cn":"掠夺性期刊这一说法随开放获取出版在 21 世纪扩散，其边界至今仍有争论。"}]},"similar":{"note":{"en":"The look-alike group separates the adjective from its noun relatives; the near-meaning group separates predatory from merely aggressive or parasitic.","cn":"形近组把这个形容词与名词同族词分开；近义组区分掠夺性与单纯强势或寄生。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"predator","ipa":"/ˈpriːdeɪtə/","tag":"the actor","definition":"The animal or party that hunts. It is a count noun, so it cannot stand where an adjective is needed.","definitionCN":"指狩猎的动物或一方。它是可数名词，不能放在需要形容词的位置。"},{"word":"predation","ipa":"/prɪˈdeɪʃən/","tag":"the act","definition":"The process of killing and eating. Predatory describes the quality; predation names the process.","definitionCN":"指杀死并取食的过程。predatory 描述性质，predation 命名过程。"},{"word":"predacious","ipa":"/prɪˈdeɪʃəs/","tag":"an older variant","definition":"A rarer adjective with the same hunting sense, now mostly used of insects. It is not interchangeable with the noun predator.","definitionCN":"较罕见的同义形容词，如今多用于昆虫。它不能与名词 predator 互换。"}]},{"heading":"NEAR MEANING","entries":[{"word":"rapacious","ipa":"/rəˈpeɪʃəs/","tag":"greed, not ecology","definition":"Means grasping and greedy, usually of people or institutions. It condemns appetite for gain and is never used for a hawk.","definitionCN":"意为贪婪攫取的，通常用于人或机构。它谴责对利益的贪欲，从不用于鹰。"},{"word":"exploitative","ipa":"/ɪkˈsplɔɪtətɪv/","tag":"the neutral social term","definition":"Describes unfair use of others. It is the plain-language equivalent of figurative predatory, without the animal image.","definitionCN":"描述不公平地利用他人。它是比喻义 predatory 的平实说法，不含动物意象。"},{"word":"parasitic","ipa":"/ˌpærəˈsɪtɪk/","tag":"feeding without killing","definition":"Describes feeding on a host that usually survives. Predatory behaviour kills or destroys, while parasitic behaviour drains.","definitionCN":"描述以通常仍存活的宿主为食。掠夺性行为会杀死或摧毁，寄生性行为则慢慢吸取。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"predator + -y: having the nature of a predator.","cn":"predator + -y：具有捕食者性质的。"},{"en":"Typical phrases: predatory pricing, predatory lending, predatory behavior, predatory journal.","cn":"典型搭配：掠夺性定价、掠夺性放贷、掠夺性行为、掠夺性期刊。"},{"en":"The family runs predator, predation, predacious, predatorily and predatoriness.","cn":"同族词包括 predator、predation、predacious、predatorily、predatoriness。"},{"en":"Rapacious is greedy; predatory is hunting. Only the first names an appetite.","cn":"rapacious 指贪婪；predatory 指捕猎。只有前者命名一种欲望。"},{"en":"The same adjective can condemn a lender or admire a hawk, depending on context.","cn":"同一个形容词可以谴责放贷者，也可以赞赏鹰，取决于语境。"}],"abstract":[{"en":"Picture a hawk circling without moving its wings, a shadow sliding over the marsh.","cn":"想象鹰不扇翅地盘旋，影子滑过沼泽。"},{"en":"Picture a payday office on a poor street, its sign promising cash and its contract hiding fees.","cn":"想象贫困街区的一家发薪日贷款门店，招牌承诺现金，合同却藏着费用。"},{"en":"Picture a journal that accepts a paper in two days and sends an invoice the next.","cn":"想象一本期刊两天内接收论文，第二天就寄来账单。"}]},"examples":[{"en":"Predatory birds keep the marsh rodents under dense cover.","cn":"捕食性鸟类让沼泽里的啮齿动物躲在密丛下。"},{"en":"The court found the below-cost pricing predatory.","cn":"法院认定这种低于成本的定价属掠夺性定价。"},{"en":"Students were warned about predatory journals that mimic legitimate titles.","cn":"学生们被提醒警惕那些模仿正规刊名的掠夺性期刊。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"predator（捕食者）+ y（……的）→ 像捕食者一样的 → predatory 掠夺性的","word":"predatory"},"root":"拉丁 praeda「战利品」→ praedator「劫掠者」→ praedatorius「劫掠的」→ 英语 predatory；后由「劫掠」转为「捕食」与「掠夺性」。","sensesIntro":{"en":"Eight senses all modify something with a hunting quality: a bird, a price, a loan, a journal or an instinct.","cn":"八个义项都用这个形容词修饰某种带有捕猎性质的东西：鸟、价格、贷款、期刊或本能。"},"semanticMap":{"core":{"en":"CORE IMAGE: a hawk circling over the marsh while a shadow slides across the grass.","cn":"核心意象：鹰在沼泽上空盘旋，影子滑过草地。"},"chain":["HUNTING","PLUNDERING","BELOW-COST PRICING","UNFAIR LENDING","INSTITUTIONAL TRAP","INNATE DRIVE"],"branches":[{"senses":"07","en":"THE INSTINCT: a hunting drive written into behaviour.","cn":"捕食本能：写进行为层面的猎杀驱力。"},{"senses":"02 · 03","en":"MARKETS: price and credit become traps set for rivals and borrowers.","cn":"市场：价格与信贷变成给对手和借款人设下的陷阱。"},{"senses":"04","en":"CONDUCT: the adjective condemns deliberate targeting of vulnerability.","cn":"行为：这个形容词谴责有意挑选弱点下手。"},{"senses":"05 · 06","en":"INSTITUTIONS: journals and acquirers consume the party they pretend to serve.","cn":"机构：期刊与收购方吞食它们声称服务的对象。"},{"senses":"01 · 08","en":"DOUBLE TONE: literal hunting and poetry's admiring eye share one adjective.","cn":"双重语气：字面的猎食与诗歌里欣赏的目光共用同一个形容词。"}]},"affixes":{"intro":{"en":"Predatory is a Latin adjective ending in -ory, built on the agent noun for a plunderer.","cn":"predatory 是以 -ory 结尾的拉丁形容词，建立在表示劫掠者的施动名词之上。"},"latinIntro":{"en":"Praeda is the root, -ator the agent, and -orius the adjective suffix meaning 'belonging to'.","cn":"praeda 是词根，-ator 是施动成分，-orius 是意为「属于……」的形容词后缀。"},"items":[{"word":"predatory","structure":"praedator + -y/-ory (adjective of belonging)","meaning":"of or like a plunderer or hunter","meaningCN":"属于劫掠者或猎手的，或像其一样的","example":"The firm's predatory tactics drew scrutiny.","exampleCN":"该公司的掠夺性策略引来审查。"},{"word":"predator","structure":"praedari + -tor (agent)","meaning":"the one that hunts","meaningCN":"狩猎的一方","example":"The predator waited at the water hole.","exampleCN":"捕食者在水坑边等待。"},{"word":"predation","structure":"praedari + -ation (action)","meaning":"the hunting act","meaningCN":"捕猎行为","example":"Predation fell after the pack moved north.","exampleCN":"狼群北迁后捕食减少。"},{"word":"predacious","structure":"praedari + -acious (inclined)","meaning":"given to hunting","meaningCN":"惯于捕食的","example":"Predacious mites eat pest eggs.","exampleCN":"捕食性螨虫吃害虫卵。"},{"word":"prey","structure":"Old French preie, from Latin praeda","meaning":"what is hunted","meaningCN":"被猎取之物","example":"The prey ran for the treeline.","exampleCN":"猎物朝林线奔去。"},{"word":"depredation","structure":"de- (thoroughly) + praedari + -ation","meaning":"ravaging","meaningCN":"蹂躏、劫掠","example":"Depredation by gulls emptied the nests.","exampleCN":"海鸥的劫掠清空了鸟巢。"},{"word":"predatorily","structure":"predatory + -ly (adverb)","meaning":"in an exploitative manner","meaningCN":"以掠夺方式","example":"The lender acted predatorily toward desperate borrowers.","exampleCN":"放贷者对走投无路的借款人采取掠夺性做法。"},{"word":"predatoriness","structure":"predatory + -ness (quality)","meaning":"the quality of being predatory","meaningCN":"掠夺性这一性质","example":"Critics noted the predatoriness of the business model.","exampleCN":"批评者指出了该商业模式的掠夺性。"},{"word":"rapacious","structure":"rapere (seize) + -acious (inclined)","meaning":"greedy, grasping","meaningCN":"贪婪的、攫取的","example":"Rapacious landlords raised rents twice a year.","exampleCN":"贪婪的房东一年涨两次租。"}],"latinEntries":[{"word":"praeda","structure":"praeda, praedae (n., first declension)","meaning":"booty, prey","meaningCN":"战利品、猎物"},{"word":"praedatorius","structure":"praedatorius, praedatoria, praedatorium (adj.)","meaning":"of plunder, plundering","meaningCN":"劫掠的、属于劫掠的"},{"word":"-orius","structure":"-orius, -oria, -orium (adjective suffix)","meaning":"belonging to, serving for","meaningCN":"属于……的、用于……的"}]}},{"word":"prey","ipa_uk":"/preɪ/","ipa_us":"/preɪ/","definition_zh":"猎物；受害者；（prey on）捕食、剥削","definition_en":"an animal that is hunted and eaten, a person or thing that is exploited, or the act of hunting and feeding on something","core_image":"一只羚羊在水坑边抬头警觉，草丛后的狮子压低身体","scene":"The herd bunched together at the water hole, easy prey for a patient hunter.","sceneCN":"这里 prey 指「猎物」（第 1 个义项：被掠食者捕杀的对象）；兽群在水坑边挤成一团，成了耐心猎手的现成猎物。图中可辨识物件：羚羊、水坑、狮子、草丛。","pos":[{"tag":"n.","zh":"猎物；受害者；牺牲品（不可数，指猎物群体；a prey 少见）"},{"tag":"v.","zh":"捕食；掠夺（通常用于 prey on / prey upon，不单独使用）"}],"collocations":[{"phrase":"fall prey to","zh":"成为……的牺牲品；落入……的圈套"},{"phrase":"easy prey","zh":"容易得手的猎物；易受骗者"},{"phrase":"bird of prey","zh":"猛禽；食肉鸟"},{"phrase":"prey on","zh":"捕食；剥削；折磨"},{"phrase":"prey base","zh":"猎物基础；捕食者可利用的猎物总量"},{"phrase":"prey species","zh":"猎物物种"},{"phrase":"predator and prey","zh":"捕食者与猎物"}],"forms":[{"label":"复数","form":"prey（通常不变；preys 极少用于动物义）"},{"label":"动词形式","form":"prey / preys / preying / preyed（多用于 prey on）"},{"label":"现在分词","form":"preying（如 preying on）"},{"label":"过去式与过去分词","form":"preyed（如 preyed on）"},{"label":"相关名词","form":"predator（捕食者）；predation（捕食）"}],"derivatives":[{"word":"predator","pos":"n.","zh":"捕食者；掠夺者"},{"word":"predation","pos":"n.","zh":"捕食；掠夺"},{"word":"predatory","pos":"adj.","zh":"捕食的；掠夺性的"},{"word":"prey base","pos":"n.","zh":"猎物基础；猎物总量"},{"word":"pray","pos":"v.","zh":"祈祷（同音异源词，见 similar）"},{"word":"depredation","pos":"n.","zh":"劫掠；破坏"}],"senses":[{"no":"01","title":"The hunted animal","titleCN":"猎物：被其他动物捕杀取食的动物","definition":"an animal that is hunted and killed by a predator for food","definitionCN":"指被捕食者猎杀取食的动物","example":"The hare is the main prey of the mountain fox.","exampleCN":"野兔是山地狐狸的主要猎物。","why":"The noun names the losing side of the hunt, defined relative to a predator rather than by species.","whyCN":"这个名词命名捕猎中失败的一方，它相对捕食者而定义，而不是按物种定义。"},{"no":"02","title":"A person who is targeted","titleCN":"受害者：被强者盯上的个人","definition":"a person who is exploited, deceived or harmed by a stronger party","definitionCN":"指被强势方剥削、欺骗或伤害的人","example":"Elderly savers were the prey of the fake investment scheme.","exampleCN":"老年储蓄者是这起虚假投资计划的受害者。","why":"The metaphor casts exploitation as predation: the victim is selected, isolated and consumed.","whyCN":"这个比喻把剥削视为捕猎：受害者被挑选、被孤立、被消耗。"},{"no":"03","title":"Bird of prey","titleCN":"猛禽：以捕猎为生的鸟类","definition":"a fixed phrase for a hunting bird such as a hawk, eagle or owl","definitionCN":"指鹰、雕、鸮等以捕猎为生的鸟类的固定说法","example":"A bird of prey circled the cliff and then dropped toward the valley.","exampleCN":"一只猛禽绕崖盘旋，随后朝谷底俯冲。","why":"The phrase freezes prey into a classifier: the bird is named by what it does to others, not by its own taxonomy.","whyCN":"这个短语把 prey 固化为分类词：这类鸟按它对别人做什么来命名，而不是按自身分类。"},{"no":"04","title":"Prey on: to hunt","titleCN":"prey on：捕食","definition":"as a verb with on or upon, to hunt and feed on another animal","definitionCN":"作动词并与 on 或 upon 连用，指猎取并取食另一种动物","example":"Owls prey on mice and voles after dark.","exampleCN":"猫头鹰天黑后捕食家鼠与田鼠。","why":"The verb keeps the old noun inside it: to prey is to act as the party that takes prey.","whyCN":"动词内部保留了旧名词：to prey 就是扮演取走猎物的那一方。"},{"no":"05","title":"Prey on: to exploit","titleCN":"prey on：剥削、折磨","definition":"as a verb with on, to exploit or persistently harm vulnerable people or their fears","definitionCN":"作动词并与 on 连用，指剥削或持续伤害弱势者及其恐惧","example":"Loan sharks prey on families who cannot get a bank loan.","exampleCN":"高利贷者剥削那些无法从银行获得贷款的家庭。","why":"The verb extends from eating to exploiting because both involve a stronger party living off a weaker one.","whyCN":"动词从取食扩展到剥削，因为两者都是强者靠弱者过活。"},{"no":"06","title":"Fall prey to","titleCN":"fall prey to：成为牺牲品","definition":"an idiom meaning to be caught, harmed or deceived by something","definitionCN":"习语，意为被某物抓住、伤害或欺骗","example":"Small shops fell prey to the new online discounters.","exampleCN":"小店铺成了新式网络折扣商的牺牲品。","why":"The idiom turns the noun into an event: the victim does not merely become prey but falls into it, as into a trap.","whyCN":"这个习语把名词变成事件：受害者不只是成为猎物，而是像落进陷阱一样陷进去。"},{"no":"07","title":"Prey base","titleCN":"猎物基础：可供捕食的猎物总量","definition":"in ecology, the total supply of prey available to support a predator population","definitionCN":"生态学中指可供养捕食者种群的猎物总供应量","example":"The decline in the prey base thinned the eagle population.","exampleCN":"猎物基础的减少使雕的种群变稀。","why":"Management treats prey as a resource stock, so the noun becomes a measurable base rather than a single animal.","whyCN":"管理把猎物视为资源存量，于是这个名词变成可测量的基础，而不是单只动物。"},{"no":"08","title":"Booty, archaic sense","titleCN":"战利品：古老的劫掠义","definition":"an archaic or literary sense of plunder taken in war or raid","definitionCN":"古旧或书面义，指战争或劫掠中夺得的财物","example":"The old poem calls the captured cattle the prey of the raiders.","exampleCN":"那首古诗把被夺走的牛群称作劫掠者的战利品。","why":"This is the original Latin sense of praeda, from which the animal sense later narrowed in English.","whyCN":"这是拉丁语 praeda 的原义，动物义是英语后来从中收窄出来的。"}],"etymology":{"intro":{"en":"Prey comes from Old French preie, from Latin praeda 'booty'. French dropped the d, so prey, predator and predation are doublets of one Latin root.","cn":"prey 出自古法语 preie，再往上为拉丁语 praeda「战利品」。法语丢掉了 d，因此 prey、predator 与 predation 是同一拉丁词根的双重借词。"},"items":[{"era":"LATIN PRAEDA","en":"Praeda meant booty taken in war or hunting, and it could already mean the animal seized by a hunter.","cn":"praeda 指战争或狩猎中夺得的战利品，也已可指猎手捕获的动物。"},{"era":"OLD FRENCH PREIE","en":"Old French preie carried the word north and lost the d between vowels, giving the shape English borrowed.","cn":"古法语 preie 把这个词带到北方，并在元音之间丢掉 d，形成英语借入时的形状。"},{"era":"ENGLISH PREY","en":"English prey appears in the thirteenth century. The exact first citation is uncertain, and the spelling settled later.","cn":"英语 prey 在 13 世纪出现；确切首见书证存疑，拼写也是后来才固定。"},{"era":"THE DOUBLE BORROWING","en":"Predator and predation were borrowed later directly from Latin, so they keep the d that French had dropped. The three words are doublets, not separate roots.","cn":"predator 与 predation 后来直接从拉丁语借入，因此保留了法语丢掉的 d。这三个词是同一词根的双重借词，并非不同词根。"},{"era":"VERBAL USE","en":"The verb prey on developed from the noun in English, first in the hunting sense and later in the sense of exploiting people.","cn":"动词短语 prey on 在英语中由名词发展而来，先取狩猎义，后扩展为剥削人。"}]},"similar":{"note":{"en":"The look-alike group contains a true homophone and two same-root relatives; the near-meaning group separates hunted animals, victims and game.","cn":"形近组含一个真正的同音词和两个同根词；近义组区分被猎动物、受害者与猎物。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"pray","ipa":"/preɪ/","tag":"homophone, unrelated","definition":"Means to address a deity or to ask earnestly. It sounds identical to prey but comes from Latin precari 'to entreat', a different root.","definitionCN":"意为向神祈祷或恳求。它与 prey 发音相同，却出自拉丁语 precari「恳求」，是不同词根。"},{"word":"predator","ipa":"/ˈpriːdeɪtə/","tag":"the hunter","definition":"The party that hunts. It is the same Latin root with the d restored, and it is the opposite role to prey.","definitionCN":"指狩猎的一方。它是同一拉丁词根、恢复了 d 的形式，角色与 prey 相反。"},{"word":"predation","ipa":"/prɪˈdeɪʃən/","tag":"the act","definition":"The act of killing and eating. Prey is what is taken; predation is the taking.","definitionCN":"指杀死并取食的行为。prey 是被取走之物，predation 是取走的行为。"}]},{"heading":"NEAR MEANING","entries":[{"word":"quarry","ipa":"/ˈkwæri/","tag":"hunted animal, literary","definition":"An animal being hunted, often in hunting and literary contexts. It stresses pursuit and is rarely used for plants or microbes.","definitionCN":"指被追猎的动物，多见于狩猎与文学语境，强调追捕，很少用于植物或微生物。"},{"word":"victim","ipa":"/ˈvɪktɪm/","tag":"human harm","definition":"A person or animal harmed by an event or crime. The figurative sense of prey overlaps with it, but victim carries no hunting image.","definitionCN":"指因事件或犯罪受害的人或动物。prey 的比喻义与之重叠，但 victim 不含捕猎意象。"},{"word":"game","ipa":"/ɡeɪm/","tag":"hunted for sport","definition":"Wild animals hunted for food or sport. Game is a category under hunting law; prey is the ecological role.","definitionCN":"指为食用或运动而猎捕的野生动物。game 是狩猎法中的类别；prey 是生态角色。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"Prey lost the d that predator kept, so the two forms look different but share praeda.","cn":"prey 丢了 d，predator 保留了 d，两个形式不同却共享 praeda。"},{"en":"Fixed phrases: fall prey to, easy prey, bird of prey, prey on.","cn":"固定搭配：成为牺牲品、容易得手的猎物、猛禽、捕食。"},{"en":"Pray is a homophone but not a relative: entreaty, not booty.","cn":"pray 是同音词却不是同族词：意为恳求，而非战利品。"},{"en":"The ecological pair is predator and prey, and the act between them is predation.","cn":"生态学的一对是捕食者与猎物，两者之间的行为叫捕食。"},{"en":"The verb needs on: birds prey on mice, lenders prey on the desperate.","cn":"动词必须带 on：鸟捕食老鼠，放贷者剥削走投无路者。"}],"abstract":[{"en":"Picture an antelope lifting its head at the water hole while the grass behind it moves.","cn":"想象羚羊在水坑边抬头，身后的草丛却在动。"},{"en":"Picture a pensioner signing a form that promises a guaranteed return.","cn":"想象一位退休老人签下一份承诺保底收益的表格。"},{"en":"Picture an old poem in which cattle are dragged away as booty.","cn":"想象一首古诗里，牛群被当作战利品拖走。"}]},"examples":[{"en":"The deer froze, then bolted, but the prey was already chosen.","cn":"鹿先僵住，随后狂奔，但猎物早已被选定。"},{"en":"Small firms often fall prey to larger rivals' pricing tactics.","cn":"小企业常常成为大对手定价策略的牺牲品。"},{"en":"The prey base in the valley has shrunk since the wetlands were drained.","cn":"湿地被排干后，谷地的猎物基础缩小了。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"prey 与 pray 同音：猎物在逃命时也在「祈祷」→ prey 猎物","word":"prey"},"root":"拉丁 praeda「战利品、猎物」→ 古法语 preie（丢掉 d）→ 英语 prey；predator、predation 为同一词根的另一路借词。","sensesIntro":{"en":"Eight senses start from one Latin word for booty and split into the hunted animal, the exploited person, the hunting verb and the ecological stock.","cn":"八个义项都从拉丁语「战利品」出发，分化为被猎动物、被剥削者、捕食动词与生态存量。"},"semanticMap":{"core":{"en":"CORE IMAGE: an antelope alert at the water hole, with movement in the grass behind it.","cn":"核心意象：水坑边警觉的羚羊，身后草丛有动静。"},"chain":["BOOTY","HUNTED ANIMAL","TARGETED PERSON","HUNTING VERB","TRAP IDIOM","ECOLOGICAL STOCK"],"branches":[{"senses":"03 · 08","en":"RAPTORS AND BOOTY: the bird of prey and the old plunder sense are two layers of the same Latin word.","cn":"猛禽与战利品：猛禽义与古老的劫掠义是同一个拉丁词的两层。"},{"senses":"05 · 06","en":"EXPLOITATION: the verb harms the weak, and the idiom turns it into an event.","cn":"剥削：动词施加伤害，习语则把它变成一次遭遇。"},{"senses":"04","en":"THE VERB: prey on turns the noun into an action that requires a target.","cn":"动词：prey on 把名词变成必须有目标的行为。"},{"senses":"07","en":"MANAGEMENT: prey becomes a measurable stock that supports predators.","cn":"管理：猎物变成可计量、供养捕食者的存量。"},{"senses":"01 · 02","en":"THE METAPHOR: hunting supplies the vocabulary for every one-sided harm.","cn":"比喻：捕猎为一切单向伤害提供了词汇。"}]},"affixes":{"intro":{"en":"Prey is a short word with a long history: the Latin root is hidden by a French sound change.","cn":"prey 是个短词却有长历史：拉丁词根被一次法语语音变化遮住了。"},"latinIntro":{"en":"Praeda is the root; French dropped the d; the same root returns with the d intact in predator, predation and predatory.","cn":"praeda 是词根；法语丢掉了 d；同一词根在 predator、predation、predatory 中带着 d 完整返回。"},"items":[{"word":"prey","structure":"Old French preie, from Latin praeda (d lost)","meaning":"the hunted animal; to hunt","meaningCN":"被猎动物；捕食","example":"The fox returned to its prey at dawn.","exampleCN":"狐狸黎明时回到猎物旁。"},{"word":"predator","structure":"praedari + -tor (agent)","meaning":"the hunter","meaningCN":"猎手","example":"The predator was a young female.","exampleCN":"这只捕食者是一只年轻雌兽。"},{"word":"predation","structure":"praedari + -ation (action)","meaning":"the hunting act","meaningCN":"捕猎行为","example":"Predation keeps the herd moving.","exampleCN":"捕食迫使兽群不断移动。"},{"word":"predatory","structure":"praedator + -y (adjective)","meaning":"hunting or exploitative","meaningCN":"捕食的或掠夺性的","example":"Predatory lenders target the poor.","exampleCN":"掠夺性放贷者瞄准穷人。"},{"word":"prey base","structure":"prey + base (stock)","meaning":"the available stock of prey","meaningCN":"可利用的猎物存量","example":"A thin prey base limits the wolf pack.","exampleCN":"稀薄的猎物基础限制了狼群。"},{"word":"bird of prey","structure":"bird + of + prey (fixed phrase)","meaning":"a hunting bird","meaningCN":"猛禽","example":"The bird of prey nested on the cliff.","exampleCN":"那只猛禽在崖上筑巢。"},{"word":"pray","structure":"Latin precari (entreat) + English -ay spelling","meaning":"to entreat a deity; a homophone, not a relative","meaningCN":"向神恳求；同音词，非同族词","example":"They pray at the shrine each spring.","exampleCN":"他们每年春天在神龛祈祷。"},{"word":"depredation","structure":"de- (thoroughly) + praedari + -ation","meaning":"ravaging, plundering","meaningCN":"蹂躏、劫掠","example":"Depredation by locusts stripped the fields.","exampleCN":"蝗虫的劫掠扫光了田地。"},{"word":"predator-prey","structure":"predator + prey (compound)","meaning":"the paired roles of hunter and hunted","meaningCN":"猎手与被猎者的成对角色","example":"The model solves for predator-prey balance.","exampleCN":"模型求解捕食者与猎物的平衡。"}],"latinEntries":[{"word":"praeda","structure":"praeda, praedae (n., first declension)","meaning":"booty, prey","meaningCN":"战利品、猎物"},{"word":"praedari","structure":"praedari, praedor, praedatus sum (v., first conjugation, deponent)","meaning":"to plunder, to hunt","meaningCN":"劫掠、猎取"},{"word":"precari","structure":"precari, precor, precatus sum (v., first conjugation, deponent)","meaning":"to entreat, pray; the source of pray, not prey","meaningCN":"恳求、祈祷；是 pray 而非 prey 的来源"}]}},{"word":"herbivore","ipa_uk":"/ˈhɜːbɪvɔː/","ipa_us":"/ˈhɜːrbɪvɔːr/","definition_zh":"食草动物；植食动物","definition_en":"an animal that feeds chiefly on plants, including grasses, leaves, fruits, seeds and sometimes algae","core_image":"一头牛低头啃食草甸，嘴角挂着草屑，身后的草地被啃出一道道弧线","scene":"The deer is a browser herbivore that strips leaves from shrubs rather than grazing the open meadow.","sceneCN":"这里 herbivore 指「植食动物」（第 1 个义项：以植物为主要食物）；这种鹿是啃食灌木枝叶的植食动物，而不是在开阔草地上放牧。图中可辨识物件：牛、草甸、灌木枝叶、被啃出的弧线。","pos":[{"tag":"n.","zh":"食草动物；植食动物（可数，复数 herbivores）"}],"collocations":[{"phrase":"large herbivore","zh":"大型植食动物"},{"phrase":"grazing herbivore","zh":"放牧型植食动物；吃草类"},{"phrase":"browsing herbivore","zh":"啃食型植食动物；吃枝叶类"},{"phrase":"herbivore population","zh":"植食动物种群"},{"phrase":"obligate herbivore","zh":"专性植食动物；必须吃植物才能存活"},{"phrase":"herbivore-induced defense","zh":"植食诱导防御；植物因被啃食而产生的化学防御"},{"phrase":"a herbivore's gut","zh":"植食动物的消化道"}],"forms":[{"label":"复数","form":"herbivores"},{"label":"形容词","form":"herbivorous（植食性的）"},{"label":"名词（植食行为）","form":"herbivory（植食；取食植物）"},{"label":"名词（食性类别）","form":"herbivory（作为生态过程）；herbivority 罕用"}],"derivatives":[{"word":"herbivorous","pos":"adj.","zh":"植食性的；吃草的"},{"word":"herbivory","pos":"n.","zh":"植食；取食植物的行为"},{"word":"herb","pos":"n.","zh":"草本植物；香草"},{"word":"herbaceous","pos":"adj.","zh":"草本的；草本植物性的"},{"word":"herbicide","pos":"n.","zh":"除草剂"},{"word":"carnivore","pos":"n.","zh":"食肉动物（对照词）"}],"senses":[{"no":"01","title":"An animal that eats plants","titleCN":"植食动物：以植物为主要食物","definition":"an animal whose diet consists mainly of plant material such as grass, leaves, fruit or seeds","definitionCN":"指以草、叶、果实或种子等植物材料为主要食物的动物","example":"The savanna supports herds of large herbivores during the wet season.","exampleCN":"雨季时，稀树草原养活了成群的巨型植食动物。","why":"The word names a dietary class by its food source, so the definition is about what enters the mouth, not about teeth or hooves.","whyCN":"这个词按食物来源命名食性类别，定义关注的是吃进嘴里的东西，而不是牙齿或蹄子。"},{"no":"02","title":"Grazers and browsers","titleCN":"放牧型与啃食型：两种取食方式","definition":"a herbivore classified by feeding style, either cropping grass low to the ground or stripping leaves and twigs from shrubs and trees","definitionCN":"指按取食方式分类的植食动物：或贴地啃食草类，或摘取灌木与树木的枝叶","example":"Grazing herbivores keep the grassland short, while browsing herbivores reach into the canopy.","exampleCN":"放牧型植食动物把草地压短，啃食型则伸进树冠取食。","why":"Ecology splits the class by height of feeding, because grass and browse regrow differently under the same animal pressure.","whyCN":"生态学按取食高度细分这一类，因为草与枝叶在同样取食压力下再生方式不同。"},{"no":"03","title":"Gut and fermentation","titleCN":"消化道与发酵：靠微生物分解纤维素","definition":"a herbivore defined by its digestive arrangement, such as a rumen or a hindgut, where microbes break down cellulose","definitionCN":"指按消化结构界定的植食动物，如具有瘤胃或后肠，由微生物分解纤维素","example":"As a ruminant herbivore, the cow relies on rumen microbes to digest grass.","exampleCN":"作为反刍型植食动物，牛依靠瘤胃微生物消化草料。","why":"Plants are tough, so herbivores are defined as much by the microbial partnership in their gut as by their food.","whyCN":"植物很坚韧，因此植食动物既由食物界定，也同样由肠道中的微生物伙伴界定。"},{"no":"04","title":"Obligate versus facultative","titleCN":"专性与兼性：能否靠植物独活","definition":"a herbivore that must eat plants to survive, as opposed to one that eats plants only when other food is scarce","definitionCN":"指必须吃植物才能存活的植食动物，与仅在其他食物稀缺时才吃植物的兼性者相对","example":"The koala is an obligate herbivore restricted to a few eucalypt species.","exampleCN":"考拉是专性植食动物，只吃少数几种桉树。","why":"The distinction separates a fixed diet from an opportunistic one, which matters when habitats change.","whyCN":"这一区分把固定食性与机会性食性分开，在生境变化时尤为重要。"},{"no":"05","title":"Herbivore as ecosystem engineer","titleCN":"生态系统工程师：植食动物塑造植被","definition":"a herbivore whose feeding and trampling reshape plant communities and therefore the habitats of other species","definitionCN":"指其取食与踩踏重塑植物群落、进而改变其他物种生境的植食动物","example":"The elephant is a herbivore that engineers the savanna by pushing over trees.","exampleCN":"大象是一种植食动物，它推倒树木，从而改造稀树草原。","why":"The label stops describing a diet and starts describing a force: what the animal eats determines what everyone else can eat.","whyCN":"这个标签不再只描述食性，而开始描述一种力量：它吃什么决定了别人能吃什么。"},{"no":"06","title":"Plant defence against herbivores","titleCN":"植物的防御：针对植食动物的化学与物理屏障","definition":"the role of a herbivore as the pressure that selects for thorns, toxins and tough tissues in plants","definitionCN":"指植食动物作为选择压力，促使植物演化出刺、毒素与坚韧组织的角色","example":"Thorns and bitter alkaloids are defences aimed at herbivores.","exampleCN":"刺与苦味生物碱是针对植食动物的防御。","why":"The word appears on the attacking side of a coevolutionary arms race, which is why plant defences are named after it.","whyCN":"这个词出现在共同演化军备竞赛的进攻一方，因此植物的防御以它为名。"},{"no":"07","title":"Marine herbivores","titleCN":"海洋植食者：海草与藻类的取食者","definition":"an aquatic animal that feeds on seagrass, algae or other marine plants","definitionCN":"指以海草、藻类或其他海洋植物为食的水生动物","example":"Sea turtles and some reef fish are marine herbivores that keep algae short.","exampleCN":"海龟与部分礁鱼是海洋植食者，它们把藻类压短。","why":"The class crosses the shoreline: wherever there is plant tissue, there is a herbivore adapted to eat it.","whyCN":"这一类跨越海岸线：凡有植物组织的地方，就有适应取食它的植食动物。"},{"no":"08","title":"Herbivore in casual speech","titleCN":"口语用法：素食者或食性比喻","definition":"an informal or humorous use for a person who eats a plant-based diet, or for a mild, non-aggressive party","definitionCN":"口语或戏谑用法，指以植物性饮食为主的人，或指温和不具攻击性的一方","example":"He calls himself a herbivore, though he still eats eggs.","exampleCN":"他自称植食者，不过仍然吃蛋。","why":"The zoological word has drifted into diet talk, where it is friendlier and less doctrinal than vegetarian.","whyCN":"这个动物学词汇漂移到饮食话题，在那里比「素食者」这一说法更轻松、更少教条色彩。"}],"etymology":{"intro":{"en":"Herbivore is a modern scientific compound from Latin herba 'grass, herb' and vorare 'to devour', literally 'plant devourer'.","cn":"herbivore 是近代科学复合词，由拉丁语 herba「草、草本」与 vorare「吞食」构成，字面即「吞食植物者」。"},"items":[{"era":"LATIN HERBA","en":"Herba meant grass, green plants or an herb, and it also underlies herb, herbage and herbaceous in English.","cn":"herba 指草、绿色植物或香草，也是英语 herb、herbage、herbaceous 的来源。"},{"era":"LATIN VORARE","en":"Vorare meant to devour or swallow whole. It is the second half of carnivore, omnivore, insectivore and voracious.","cn":"vorare 意为吞食、整口吞下，它是 carnivore、omnivore、insectivore 与 voracious 的后半部分。"},{"era":"SCIENTIFIC COMPOUND","en":"The compound was formed in modern scientific Latin, and French zoologist Georges Cuvier is usually credited with popularising the dietary classification in the early nineteenth century. The exact coining is uncertain.","cn":"这个复合词在近代科学拉丁语中形成；一般认为法国动物学家居维叶在 19 世纪早期推广了这套食性分类，但确切的造词者存疑。"},{"era":"THREE-WAY SPLIT","en":"Zoology standardised the triad herbivore, carnivore and omnivore, turning a descriptive compound into a classification system.","cn":"动物学把 herbivore、carnivore、omnivore 确立为三分法，把一个描述性复合词变成分类体系。"},{"era":"MODERN EXTENSIONS","en":"The pattern later produced insectivore, frugivore, folivore and nectarivore, each naming a specific plant or animal food.","cn":"这一模式后来派生出 insectivore、frugivore、folivore、nectarivore，各自命名特定的植物或动物食物。"}]},"similar":{"note":{"en":"The look-alike group shares the -vore ending and must be told apart by the first element; the near-meaning group separates diet class from feeding style.","cn":"形近组共享 -vore 结尾，须靠前半部分区分；近义组区分食性类别与取食方式。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carnivore","ipa":"/ˈkɑːnɪvɔː/","tag":"flesh eater","definition":"An animal that eats mainly animal flesh. The first element is Latin caro 'flesh', so the two words differ at the stem, not the ending.","definitionCN":"指以动物肉为主食的动物。前半是拉丁语 caro「肉」，因此两词区别在词干而非词尾。"},{"word":"omnivore","ipa":"/ˈɒmnɪvɔː/","tag":"eats both","definition":"An animal that eats both plant and animal food. The first element omni- 'all' marks the broader diet.","definitionCN":"指既吃植物也吃动物的动物。前半 omni-「全部」标出更宽的食性。"},{"word":"herbivorous","ipa":"/hɜːˈbɪvərəs/","tag":"the adjective","definition":"The adjective form meaning plant-eating. Herbivore is the noun for the animal, so the two cannot swap places.","definitionCN":"形容词形式，意为植食的。herbivore 是动物的名词，两者不能互换位置。"}]},{"heading":"NEAR MEANING","entries":[{"word":"grazer","ipa":"/ˈɡreɪzə/","tag":"grass-level feeder","definition":"A herbivore that crops grass and low vegetation. It is a subset of herbivore, defined by feeding height rather than diet alone.","definitionCN":"指啃食草类与低矮植被的植食动物。它是植食动物的子集，按取食高度而非仅按食性界定。"},{"word":"browser","ipa":"/ˈbraʊzə/","tag":"shrub-level feeder","definition":"A herbivore that strips leaves and twigs from shrubs and trees. Do not confuse it with the web browser.","definitionCN":"指摘食灌木与树木枝叶的植食动物。注意不要与网络浏览器混淆。"},{"word":"folivore","ipa":"/ˈfəʊlɪvɔː/","tag":"leaf specialist","definition":"A herbivore specialising in leaves. It is narrower than herbivore, which also covers grass, fruit and seed eaters.","definitionCN":"指专食树叶的植食动物，比 herbivore 更窄，后者还包括吃草、果实与种子者。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"herba 'grass' + vorare 'devour': the plant devourer.","cn":"herba「草」+ vorare「吞食」：吞食植物者。"},{"en":"Read -vore as 'eater' and the first half names the food: herbi-, carni-, omni-, insecti-.","cn":"把 -vore 读作「吃……者」，前半部分就是食物：herbi-、carni-、omni-、insecti-。"},{"en":"The family runs herb, herbaceous, herbage, herbicide, herbivorous and herbivory.","cn":"同族词包括 herb、herbaceous、herbage、herbicide、herbivorous、herbivory。"},{"en":"Fixed phrases: grazing herbivore, browsing herbivore, obligate herbivore, herbivore population.","cn":"固定搭配：放牧型植食动物、啃食型植食动物、专性植食动物、植食动物种群。"},{"en":"Cuvier is usually credited with the dietary triad in the early 1800s, though the coining is uncertain.","cn":"一般认为居维叶在 1800 年代初提出这套食性三分法，但造词者存疑。"}],"abstract":[{"en":"Picture a cow tearing grass with a sideways sweep of its head.","cn":"想象一头牛把头一甩，撕下一把草。"},{"en":"Picture a deer standing on hind legs to reach leaves above the browse line.","cn":"想象一只鹿立起后腿，够取啃食线以上的树叶。"},{"en":"Picture an elephant pushing a tree over so the whole herd can feed.","cn":"想象大象推倒一棵树，让整群都能取食。"}]},"examples":[{"en":"Large herbivores keep the savanna open by eating young trees.","cn":"大型植食动物吃掉落树幼苗，使稀树草原保持开阔。"},{"en":"The koala is an obligate herbivore with a narrow diet.","cn":"考拉是食性很窄的专性植食动物。"},{"en":"Plant toxins evolved as defences against herbivores.","cn":"植物毒素是作为抵御植食动物的防御演化出来的。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"herb（草本）+ vore（吃……者）→ 吃草的东西 → herbivore 食草动物","word":"herbivore"},"root":"拉丁 herba「草、草本」+ vorare「吞食」→ 近代科学拉丁语 herbivorus／herbivore「吞食植物者」。","sensesIntro":{"en":"Eight senses begin with the plain diet label and then add feeding height, gut design, obligation, ecosystem effects, plant defence, marine life and casual speech.","cn":"八个义项从最朴素的食性标签开始，再依次加入取食高度、消化道设计、专性程度、生态效应、植物防御、海洋生活与口语用法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a cow sweeping grass into its mouth, leaving curved bite marks.","cn":"核心意象：牛把草扫进嘴里，留下弧形咬痕。"},"chain":["PLANT DIET","GRAZE OR BROWSE","MICROBIAL DIGESTION","OBLIGATE OR FACULTATIVE","ECOSYSTEM ENGINEER","COEVOLVED DEFENCE"],"branches":[{"senses":"01","en":"DIET: the base sense names an animal by what it eats.","cn":"食性：基本义按吃什么来命名动物。"},{"senses":"02","en":"STYLE: grazer and browser split the class by feeding height.","cn":"方式：放牧型与啃食型按取食高度细分这一类。"},{"senses":"03 · 04","en":"PHYSIOLOGY AND NECESSITY: gut microbes and obligation decide whether plants can be the only food.","cn":"生理与必要性：肠道微生物与专性程度决定植物能否成为唯一食物。"},{"senses":"05 · 06","en":"FORCE: the herbivore shapes plant communities, and plants evolve defences against it.","cn":"力量：植食动物塑造植物群落，植物则演化出针对它的防御。"},{"senses":"07 · 08","en":"RANGE: the label crosses into the sea and into casual talk about diets.","cn":"范围：这个标签跨入海洋，也跨入口语中的饮食话题。"}]},"affixes":{"intro":{"en":"Herbivore is a two-part scientific compound, and the same -vore ending builds a whole family of diet words.","cn":"herbivore 是两部分构成的科学复合词，同一个 -vore 结尾还能造出一整族食性词汇。"},"latinIntro":{"en":"Herba supplies the food, vorare supplies the eating, and the compound was fixed in modern scientific Latin before entering English.","cn":"herba 提供食物，vorare 提供吃，这个复合词在近代科学拉丁语中定型后才进入英语。"},"items":[{"word":"herbivore","structure":"herba (grass) + vorare (devour) + -e (noun)","meaning":"plant-eating animal","meaningCN":"以植物为食的动物","example":"The meadow supports several herbivores.","exampleCN":"这片草甸养活着好几种植食动物。"},{"word":"herbivorous","structure":"herbivore + -ous (adjective)","meaning":"plant-eating","meaningCN":"植食的","example":"Herbivorous insects stripped the leaves.","exampleCN":"植食性昆虫把叶子吃光了。"},{"word":"herbivory","structure":"herbivore + -y (abstract noun)","meaning":"the act or process of plant eating","meaningCN":"植食行为或过程","example":"Herbivory removes a third of the leaf mass.","exampleCN":"植食带走了三分之一的叶量。"},{"word":"herb","structure":"Latin herba (grass, herb)","meaning":"a plant used for food, medicine or flavour","meaningCN":"用于食物、药物或调味的植物","example":"The garden grows culinary herbs.","exampleCN":"园子里种着烹饪用的香草。"},{"word":"herbaceous","structure":"herb + -aceous (resembling)","meaning":"soft-stemmed, not woody","meaningCN":"草本的、非木质的","example":"The border is planted with herbaceous perennials.","exampleCN":"花境里种的是草本多年生植物。"},{"word":"herbicide","structure":"herba + -cide (killing)","meaning":"a chemical that kills plants","meaningCN":"杀死植物的化学药剂","example":"The field was cleared with herbicide.","exampleCN":"这块田用除草剂清除了杂草。"},{"word":"carnivore","structure":"caro (flesh) + vorare (devour)","meaning":"flesh-eating animal","meaningCN":"以肉为食的动物","example":"The carnivore hunts at dusk.","exampleCN":"这只食肉动物黄昏时狩猎。"},{"word":"omnivore","structure":"omni- (all) + vorare (devour)","meaning":"animal eating both plants and flesh","meaningCN":"既吃植物也吃肉的动物","example":"The omnivore switches between berries and insects.","exampleCN":"这种杂食动物在浆果与昆虫之间切换。"},{"word":"voracious","structure":"vorare + -acious (inclined to)","meaning":"devouring greedily","meaningCN":"贪食的、大口吞食的","example":"The caterpillars are voracious feeders.","exampleCN":"这些毛虫是贪食的取食者。"}],"latinEntries":[{"word":"herba","structure":"herba, herbae (n., first declension)","meaning":"grass, green plant, herb","meaningCN":"草、绿色植物、香草"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour, swallow","meaningCN":"吞食、吞咽"},{"word":"herbivorus","structure":"herbivorus (adj., modern scientific Latin)","meaning":"plant-eating","meaningCN":"植食的"}]}},{"word":"herbivorous","ipa_uk":"/hɜːˈbɪvərəs/","ipa_us":"/hɜːrˈbɪvərəs/","definition_zh":"植食性的；以植物为食的","definition_en":"describing an animal whose diet consists mainly of plants, or a structure adapted to eating plant material","core_image":"一排宽大的臼齿在咀嚼干草，齿面被磨成水平的磨盘","scene":"The herbivorous dinosaurs had broad grinding teeth suited to ferns and cycads.","sceneCN":"这里 herbivorous 指「植食性的」（第 1 个义项：以植物为主要食物）；这些植食性恐龙有宽阔的研磨齿，适合吃蕨类与苏铁。图中可辨识物件：臼齿、干草、蕨叶、苏铁。","pos":[{"tag":"adj.","zh":"植食性的；以植物为食的（比较级 more herbivorous，最高级 most herbivorous）"}],"collocations":[{"phrase":"herbivorous animal","zh":"植食动物"},{"phrase":"herbivorous dinosaur","zh":"植食性恐龙"},{"phrase":"herbivorous insect","zh":"植食性昆虫"},{"phrase":"herbivorous fish","zh":"植食性鱼类"},{"phrase":"strictly herbivorous","zh":"严格植食的；完全不吃动物性食物"},{"phrase":"herbivorous diet","zh":"植食性食谱"},{"phrase":"herbivorous habit","zh":"植食习性"}],"forms":[{"label":"比较级","form":"more herbivorous"},{"label":"最高级","form":"most herbivorous"},{"label":"副词形式","form":"herbivorously（以植食方式；罕用）"},{"label":"名词形式","form":"herbivore（植食动物）；herbivory（植食）"},{"label":"作定语","form":"herbivorous + 名词（如 herbivorous mammal、herbivorous larva）"}],"derivatives":[{"word":"herbivore","pos":"n.","zh":"植食动物"},{"word":"herbivory","pos":"n.","zh":"植食；取食植物的行为"},{"word":"herb","pos":"n.","zh":"草本植物；香草"},{"word":"herbaceous","pos":"adj.","zh":"草本的"},{"word":"herbicide","pos":"n.","zh":"除草剂"},{"word":"carnivorous","pos":"adj.","zh":"食肉的（对照词）"}],"senses":[{"no":"01","title":"Plant-eating by diet","titleCN":"植食性：食谱以植物为主","definition":"describing an animal whose food is mainly plant material","definitionCN":"描述以植物材料为主要食物的动物","example":"Most large mammals on the plain are herbivorous.","exampleCN":"平原上的大型哺乳动物大多是植食性的。","why":"The adjective attaches the diet class to a particular animal, so it answers what kind of eater this species is.","whyCN":"这个形容词把食性类别挂到具体动物上，用来回答这个物种属于哪类取食者。"},{"no":"02","title":"Teeth built for plants","titleCN":"齿型适应：宽平的研磨面","definition":"describing dental or jaw anatomy adapted to grinding tough plant fibres rather than shearing flesh","definitionCN":"描述适应研磨坚韧植物纤维而非切割肉类的牙齿或颌部结构","example":"The herbivorous jaw is deep and the molars are flat.","exampleCN":"植食性的颌部厚实，臼齿扁平。","why":"Anatomy carries the diet: flat grinding surfaces are the physical signature of a plant eater.","whyCN":"解剖结构携带着食性信息：平坦的研磨面就是植食者的物理签名。"},{"no":"03","title":"Gut adapted to fibre","titleCN":"消化道适应：长肠与发酵腔","definition":"describing a digestive tract that is long or chambered enough for microbes to break down cellulose","definitionCN":"描述足够长或具有发酵腔、可供微生物分解纤维素的消化道","example":"Herbivorous mammals have a caecum or rumen for fermentation.","exampleCN":"植食性哺乳动物有盲肠或瘤胃用于发酵。","why":"Cellulose resists ordinary digestion, so the adjective also marks an animal that houses microbes.","whyCN":"纤维素难以普通消化，因此这个形容词也标出体内养着微生物的动物。"},{"no":"04","title":"Herbivorous insects","titleCN":"植食性昆虫：把植物当全部食物","definition":"describing insects that feed on leaves, sap, wood, seeds or nectar","definitionCN":"描述取食叶片、汁液、木材、种子或花蜜的昆虫","example":"Herbivorous beetles account for much of the damage in the plantation.","exampleCN":"植食性甲虫造成了种植园里的大部分损害。","why":"Most animal species are insects, and most of them are plant eaters, so this is the largest herbivorous group on land.","whyCN":"动物物种以昆虫为主，而昆虫大多吃植物，因此这是陆地上最大的植食类群。"},{"no":"05","title":"Strictly herbivorous","titleCN":"严格植食：完全不吃动物性食物","definition":"describing a diet with no animal material at all, as opposed to occasional omnivory","definitionCN":"描述完全不含动物性食物的食性，与偶尔杂食相对","example":"The species is strictly herbivorous and will not take carrion.","exampleCN":"该物种严格植食，不会取食腐肉。","why":"The adverb matters because many herbivores occasionally eat insects, which blurs the boundary with omnivory.","whyCN":"这个副词很重要，因为许多植食动物偶尔吃昆虫，从而模糊了与杂食的边界。"},{"no":"06","title":"Herbivorous dinosaurs","titleCN":"植食恐龙：古生物中的取食类群","definition":"describing extinct reptiles identified as plant eaters from teeth, gut contents or coprolites","definitionCN":"描述依据牙齿、胃内容物或粪化石判定为植食的已灭绝爬行动物","example":"Herbivorous dinosaurs ranged from low browsers to high-reaching sauropods.","exampleCN":"植食恐龙从低处啃食者一直分布到高处的蜥脚类。","why":"Palaeontology uses the adjective for fossil taxa whose diet must be inferred rather than observed.","whyCN":"古生物学把这个形容词用于食性只能推断、无法直接观察的化石类群。"},{"no":"07","title":"Marine plant eaters","titleCN":"海洋植食：吃海草与藻类","definition":"describing aquatic animals that graze seagrass, macroalgae or epilithic algae","definitionCN":"描述啃食海草、大型藻类或附着藻类的水生动物","example":"Herbivorous fish keep the reef free of smothering algae.","exampleCN":"植食性鱼类让礁体免于被藻类覆盖。","why":"Reef health depends on these grazers, so the adjective becomes a management label.","whyCN":"礁体健康依赖这些啃食者，因此这个形容词也成了管理标签。"},{"no":"08","title":"Figurative and dietary use","titleCN":"比喻与饮食用法：温和或素食","definition":"used informally of a person's plant-based diet, or humorously of a mild, non-aggressive temperament","definitionCN":"口语中指个人的植物性饮食，或戏谑地指温和、不具攻击性的性情","example":"He describes himself as herbivorous but still eats fish.","exampleCN":"他自称植食，不过仍吃鱼。","why":"The adjective softens a dietary choice into a temperament metaphor, which is why it appears in casual writing.","whyCN":"这个形容词把饮食选择软化成一种性情比喻，因此常见于随笔。"}],"etymology":{"intro":{"en":"Herbivorous is the Latin adjective herbivorus, built from herba 'grass' and vorare 'devour', and it predates the English noun herbivore.","cn":"herbivorous 是拉丁形容词 herbivorus，由 herba「草」与 vorare「吞食」构成，其出现早于英语名词 herbivore。"},"items":[{"era":"LATIN HERBA","en":"Herba covered grass and green plants generally, not only culinary herbs.","cn":"herba 泛指草与绿色植物，不只是烹饪用的香草。"},{"era":"LATIN VORARE","en":"Vorare meant to swallow or devour, and the adjective -vorus 'eating' was used in compounds such as carnivorus.","cn":"vorare 意为吞咽、吞食，形容词成分 -vorus「吃……的」用于 carnivorus 这类复合词。"},{"era":"SCIENTIFIC LATIN","en":"Herbivorus belongs to modern scientific Latin, where diet adjectives were formed freely from Latin roots. Its exact first use is uncertain.","cn":"herbivorus 属近代科学拉丁语，这类食性形容词可由拉丁词根自由构成；确切首用存疑。"},{"era":"ENGLISH ADOPTION","en":"English adopted herbivorous in the nineteenth century alongside the noun. The exact first citation is uncertain.","cn":"英语在 19 世纪与名词同时期采用 herbivorous；确切首见书证存疑。"},{"era":"PARALLEL FORMS","en":"The same pattern produced carnivorous, omnivorous, insectivorous and frugivorous, so the ending -ivorous became a productive classifier.","cn":"同一模式造出 carnivorous、omnivorous、insectivorous、frugivorous，词尾 -ivorous 因而成为能产的分类成分。"}]},"similar":{"note":{"en":"The look-alike group shares the -vorous ending; the near-meaning group separates plant eating from related but narrower labels.","cn":"形近组共享 -vorous 结尾；近义组把植食与更窄的相关标签区分开。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"herbivore","ipa":"/ˈhɜːbɪvɔː/","tag":"the noun","definition":"The animal itself. It cannot modify another noun, so a plant-eating dinosaur is a herbivorous dinosaur, not a herbivore dinosaur.","definitionCN":"指动物本身。它不能修饰其他名词，因此应说 herbivorous dinosaur，而不是 herbivore dinosaur。"},{"word":"carnivorous","ipa":"/kɑːˈnɪvərəs/","tag":"flesh-eating","definition":"Describes a flesh diet. The stem caro- 'flesh' is the only difference, and the two adjectives mark opposite diets.","definitionCN":"描述食肉。词干 caro-「肉」是唯一差别，两个形容词标示相反的食性。"},{"word":"omnivorous","ipa":"/ɒmˈnɪvərəs/","tag":"eating both","definition":"Describes a mixed diet of plants and animals. The stem omni- 'all' widens the diet beyond herbivorous.","definitionCN":"描述植物与动物混合的食性。词干 omni-「全部」把食性拓宽到植食之外。"}]},{"heading":"NEAR MEANING","entries":[{"word":"folivorous","ipa":"/fəʊˈlɪvərəs/","tag":"leaves only","definition":"Describes a diet of leaves specifically. It is narrower than herbivorous, which also covers grass, fruit and seeds.","definitionCN":"描述专食树叶的食性。它比 herbivorous 更窄，后者还包括草、果实与种子。"},{"word":"graminivorous","ipa":"/ˌɡræmɪˈnɪvərəs/","tag":"grass only","definition":"Describes a diet of grasses and cereals. It is a rare technical term, narrower than herbivorous.","definitionCN":"描述以禾草与谷物为食。它是罕见的技术词，比 herbivorous 更窄。"},{"word":"plant-eating","ipa":"/ˈplænt iːtɪŋ/","tag":"the plain paraphrase","definition":"A transparent compound meaning the same as herbivorous but without the scientific register.","definitionCN":"透明的复合词，含义与 herbivorous 相同，但不带科学语域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"herba 'grass' + -vorous 'eating': eating grass and plants.","cn":"herba「草」+ -vorous「吃……的」：吃草与植物。"},{"en":"Swap the stem to change the diet: herbi-, carni-, omni-, insecti-, frugi-.","cn":"换词干就换食性：herbi-、carni-、omni-、insecti-、frugi-。"},{"en":"Typical phrases: herbivorous animal, herbivorous dinosaur, herbivorous insect, strictly herbivorous.","cn":"典型搭配：植食动物、植食性恐龙、植食性昆虫、严格植食。"},{"en":"Flat molars and a fermentation chamber are the anatomical tells of this adjective.","cn":"扁平臼齿与发酵腔是这个形容词的解剖学线索。"},{"en":"The noun is herbivore and the process is herbivory; keep the three forms apart.","cn":"名词是 herbivore，过程是 herbivory；三种形式要分清。"}],"abstract":[{"en":"Picture molars grinding dry grass into a flat paste.","cn":"想象臼齿把干草磨成扁平的糊。"},{"en":"Picture a caterpillar stripping a leaf down to its veins.","cn":"想象毛虫把一片叶子啃到只剩叶脉。"},{"en":"Picture a fish scraping algae off coral so the coral can still see light.","cn":"想象一条鱼把藻类从珊瑚上刮掉，让珊瑚仍能见到光。"}]},"examples":[{"en":"The fossil's flat molars mark it as herbivorous.","cn":"这块化石的扁平臼齿表明它是植食性的。"},{"en":"Herbivorous insects remove a large share of the canopy each summer.","cn":"每年夏天，植食性昆虫带走大量树冠叶片。"},{"en":"The lake's herbivorous fish keep the water clear of algae.","cn":"湖中的植食性鱼类让水体免于藻类覆盖。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"herbivore（食草动物）+ ous（……的）→ 食草的 → herbivorous 植食性的","word":"herbivorous"},"root":"拉丁 herba「草」+ vorare「吞食」→ 科学拉丁语 herbivorus「吃植物的」→ 英语 herbivorous。","sensesIntro":{"en":"Eight senses apply one adjective to diet, teeth, gut, insects, strictness, fossils, reefs and casual talk.","cn":"八个义项把同一个形容词用于食性、牙齿、消化道、昆虫、严格程度、化石、礁体与口语。"},"semanticMap":{"core":{"en":"CORE IMAGE: flat molars grinding dry grass into paste.","cn":"核心意象：扁平臼齿把干草磨成糊。"},"chain":["PLANT DIET","GRINDING TEETH","FERMENTING GUT","INSECT MAJORITY","STRICT EXCLUSION","FOSSIL AND REEF"],"branches":[{"senses":"01","en":"DIET: the base sense says the food is plant material.","cn":"食性：基本义说食物是植物材料。"},{"senses":"02 · 03","en":"ANATOMY: teeth and gut carry the diet in bone and tissue.","cn":"解剖：牙齿与消化道把食性写进骨骼与组织。"},{"senses":"04 · 05","en":"SCOPE: insects dominate the class, and strictness separates it from omnivory.","cn":"范围：昆虫在这一类中占主导，严格程度则把它与杂食分开。"},{"senses":"06 · 07","en":"APPLIED FIELDS: palaeontology infers it from fossils, reef management relies on it.","cn":"应用领域：古生物学从化石推断它，礁体管理依赖它。"},{"senses":"08","en":"DRIFT: the adjective becomes a gentle metaphor for diet and temperament.","cn":"漂移：这个形容词成为饮食与性情的温和比喻。"}]},"affixes":{"intro":{"en":"Herbivorous is a Latin adjective whose ending -vorous is a productive classifier in zoology.","cn":"herbivorous 是拉丁形容词，其结尾 -vorous 在动物学中是能产的分类成分。"},"latinIntro":{"en":"Herba is the plant, vorare the eating, and -vorus the adjectival form of the eating verb.","cn":"herba 是植物，vorare 是吃，-vorus 是吃的动词的形容词形式。"},"items":[{"word":"herbivorous","structure":"herba (grass) + vorare (devour) + -ous (adjective)","meaning":"plant-eating","meaningCN":"植食的","example":"The lizard is entirely herbivorous.","exampleCN":"这种蜥蜴完全植食。"},{"word":"herbivore","structure":"herba + vorare + noun ending","meaning":"a plant-eating animal","meaningCN":"植食动物","example":"Each herbivore has its preferred grass.","exampleCN":"每种植食动物都有偏好的草。"},{"word":"herbivory","structure":"herbivore + -y (abstract noun)","meaning":"the process of plant eating","meaningCN":"植食过程","example":"Herbivory varies with leaf toughness.","exampleCN":"植食程度随叶片硬度变化。"},{"word":"carnivorous","structure":"caro (flesh) + vorare + -ous","meaning":"flesh-eating","meaningCN":"食肉的","example":"Carnivorous plants trap insects.","exampleCN":"食肉植物会捕获昆虫。"},{"word":"omnivorous","structure":"omni- (all) + vorare + -ous","meaning":"eating both plants and flesh","meaningCN":"既吃植物也吃肉的","example":"Omnivorous birds take grain and grubs.","exampleCN":"杂食鸟类既吃谷物也吃幼虫。"},{"word":"insectivorous","structure":"insectum (insect) + vorare + -ous","meaning":"insect-eating","meaningCN":"食虫的","example":"Insectivorous bats hunt after dusk.","exampleCN":"食虫蝙蝠入夜后捕食。"},{"word":"frugivorous","structure":"frux (fruit) + vorare + -ous","meaning":"fruit-eating","meaningCN":"食果的","example":"Frugivorous birds spread the seeds.","exampleCN":"食果鸟类传播种子。"},{"word":"herb","structure":"Latin herba (grass, herb)","meaning":"a plant valued for food or medicine","meaningCN":"用于食物或药物的植物","example":"The herb grows in damp shade.","exampleCN":"这种草本长在潮湿的荫处。"},{"word":"voracious","structure":"vorare + -acious (inclined)","meaning":"devouring greedily","meaningCN":"贪食的","example":"The larvae are voracious.","exampleCN":"这些幼虫非常贪食。"}],"latinEntries":[{"word":"herba","structure":"herba, herbae (n., first declension)","meaning":"grass, green plant","meaningCN":"草、绿色植物"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour","meaningCN":"吞食"},{"word":"herbivorus","structure":"herbivorus, herbivora, herbivorum (adj., scientific Latin)","meaning":"plant-eating","meaningCN":"植食的"}]}},{"word":"carnivore","ipa_uk":"/ˈkɑːnɪvɔː/","ipa_us":"/ˈkɑːrnɪvɔːr/","definition_zh":"食肉动物；肉食者；食虫植物","definition_en":"an animal that feeds chiefly on the flesh of other animals, or a plant that traps and digests small animals","core_image":"一只狼低头撕咬猎物后腿，嘴边沾着血，雪地上留着拖行的痕迹","scene":"The wolf is a social carnivore that brings down prey far larger than itself.","sceneCN":"这里 carnivore 指「食肉动物」（第 1 个义项：以动物肉为主要食物）；狼是群居食肉动物，能放倒比自己大得多的猎物。图中可辨识物件：狼、猎物、雪地拖痕、血迹。","pos":[{"tag":"n.","zh":"食肉动物；肉食者；食虫植物（可数，复数 carnivores）"}],"collocations":[{"phrase":"top carnivore","zh":"顶级食肉动物"},{"phrase":"large carnivore","zh":"大型食肉动物"},{"phrase":"obligate carnivore","zh":"专性食肉动物；必须吃肉才能存活"},{"phrase":"carnivore conservation","zh":"食肉动物保护"},{"phrase":"carnivore guild","zh":"食肉动物集团；同一群落中共享猎物的食肉者集合"},{"phrase":"carnivorous plant","zh":"食虫植物（常用形容词形式）"},{"phrase":"human carnivore","zh":"人类的食肉者；以肉为主食的人"}],"forms":[{"label":"复数","form":"carnivores"},{"label":"形容词","form":"carnivorous（食肉的）"},{"label":"名词（食肉行为）","form":"carnivory（食肉；肉食性）"},{"label":"形容词（罕用）","form":"carnivoral（食肉动物类的；多用于分类学）"}],"derivatives":[{"word":"carnivorous","pos":"adj.","zh":"食肉的；肉食性的"},{"word":"carnivory","pos":"n.","zh":"食肉；肉食性"},{"word":"carnassial","pos":"adj./n.","zh":"裂齿的；食肉动物用于剪切肉类的牙齿"},{"word":"Carnivora","pos":"n.","zh":"食肉目；哺乳动物中的一个目"},{"word":"herbivore","pos":"n.","zh":"食草动物（对照词）"},{"word":"omnivore","pos":"n.","zh":"杂食动物（对照词）"}],"senses":[{"no":"01","title":"Flesh-eating animal","titleCN":"食肉动物：以动物肉为主食","definition":"an animal whose diet consists mainly of the flesh of other animals","definitionCN":"指以其他动物的肉为主要食物的动物","example":"Wolves are carnivores that hunt in packs.","exampleCN":"狼是成群狩猎的食肉动物。","why":"The word names a dietary class by its food, so a carnivore is defined by what it eats rather than by how it kills.","whyCN":"这个词按食物命名食性类别，因此食肉动物由吃什么界定，而不是由如何杀界定。"},{"no":"02","title":"Obligate carnivore","titleCN":"专性食肉：无法靠植物维生","definition":"a carnivore that cannot survive on plant food alone because it lacks the enzymes or gut microbes to use it","definitionCN":"指因缺乏利用植物的酶或肠道微生物、无法仅靠植物维生的食肉动物","example":"The domestic cat is an obligate carnivore that needs taurine from meat.","exampleCN":"家猫是专性食肉动物，必须从肉类获得牛磺酸。","why":"Physiology, not preference, makes the class: an obligate carnivore would starve on a vegetarian diet.","whyCN":"决定这一类的是生理而非偏好：专性食肉者吃素会饿死。"},{"no":"03","title":"Apex carnivore","titleCN":"顶级食肉者：成年后几无天敌","definition":"a carnivore at the top of its food chain that suffers little or no predation itself","definitionCN":"指处于食物链顶端、自身几乎或完全不被捕食的食肉动物","example":"The removal of the apex carnivore let the deer herd grow unchecked.","exampleCN":"顶级食肉者的消失让鹿群无限制增长。","why":"The label marks position rather than appetite: the top carnivore regulates the levels below it.","whyCN":"这个标签标出位置而非食欲：顶级食肉者调节其下各层。"},{"no":"04","title":"Carnassial shear","titleCN":"裂齿剪切：食肉动物的牙齿构造","definition":"a carnivore identified by specialised shearing teeth that slice flesh rather than grind it","definitionCN":"指以专门剪切齿、切割而非研磨肉类的食肉动物","example":"The fossil's carnassial teeth show it was a carnivore.","exampleCN":"化石上的裂齿表明它是食肉动物。","why":"Anatomy is evidence: paleontologists read the diet of extinct animals from the shape of their teeth.","whyCN":"解剖即证据：古生物学家从牙齿形状读出已灭绝动物的食性。"},{"no":"05","title":"Carnivore guild","titleCN":"食肉集团：共享猎物的竞争者","definition":"in community ecology, the set of carnivores in one habitat that partition prey by size, time or hunting method","definitionCN":"群落生态学中指同一生境中按猎物大小、时间或狩猎方式分工的一群食肉动物","example":"The carnivore guild splits the night into separate hunting shifts.","exampleCN":"食肉集团把夜晚分成不同的狩猎班次。","why":"Competition forces the class to divide resources, so the word becomes a unit of community structure.","whyCN":"竞争迫使这一类分配资源，因此这个词成为群落结构的单位。"},{"no":"06","title":"Carnivorous plant","titleCN":"食虫植物：捕虫并消化吸收","definition":"a plant that captures and digests small animals, usually insects, to obtain nutrients","definitionCN":"指捕获并消化小动物（通常为昆虫）以获取养分的植物","example":"The pitcher plant is a carnivore that digests insects in its fluid.","exampleCN":"猪笼草是一种在液体中消化昆虫的食肉植物。","why":"The word is borrowed for plants because the mechanism is the same: capture, kill and absorb.","whyCN":"这个词被借用于植物，因为机制相同：捕获、杀死并吸收。"},{"no":"07","title":"Human carnivore","titleCN":"人类的食肉者：以肉为主食的人","definition":"a person whose diet is based mainly on animal flesh, or a cultural label for meat-centred eating","definitionCN":"指以动物肉为主食的人，或指以肉为中心的饮食文化标签","example":"The festival celebrates the region's identity as a land of carnivores.","exampleCN":"这个节庆庆祝该地区作为食肉者之乡的身份。","why":"The zoological label becomes a cultural identity, usually light-hearted rather than clinical.","whyCN":"这个动物学标签变成文化身份，通常轻松而非临床。"},{"no":"08","title":"The order Carnivora","titleCN":"食肉目：分类学上的一个目","definition":"in taxonomy, the mammalian order Carnivora, which includes cats, dogs, bears and seals, some of which eat little meat","definitionCN":"分类学中哺乳动物的食肉目，包括猫、犬、熊与海豹，其中有些很少吃肉","example":"Not every member of Carnivora is a strict carnivore; bears eat berries.","exampleCN":"食肉目并非每个成员都是严格食肉者；熊也吃浆果。","why":"Taxonomy and diet diverge here, which is why the order name can mislead a reader about a species' food.","whyCN":"分类与食性在此分岔，因此目名可能误导读者对该物种食物的判断。"}],"etymology":{"intro":{"en":"Carnivore joins Latin caro 'flesh' with vorare 'to devour', literally 'flesh devourer', and it was fixed in scientific Latin before entering English.","cn":"carnivore 由拉丁语 caro「肉」与 vorare「吞食」构成，字面即「吞食肉者」，先在科学拉丁语中定型，后进入英语。"},"items":[{"era":"LATIN CARO","en":"Caro, carnis meant flesh, especially animal flesh, and it also gives English carnal and carnage.","cn":"caro, carnis 意为肉，尤指动物肉，它也是英语 carnal 与 carnage 的来源。"},{"era":"LATIN VORARE","en":"Vorare meant to swallow or devour, the same second element as in herbivore and omnivore.","cn":"vorare 意为吞咽、吞食，与 herbivore、omnivore 中的后半部分相同。"},{"era":"SCIENTIFIC LATIN","en":"Carnivorus was used in modern scientific Latin for flesh-eating animals, and Cuvier's classification is usually credited with popularising it in the early nineteenth century. The exact coining is uncertain.","cn":"carnivorus 在近代科学拉丁语中用于食肉动物；一般认为居维叶在 19 世纪早期的分类体系推广了它，但确切的造词者存疑。"},{"era":"ENGLISH ENTRY","en":"English carnivore appears in the nineteenth century, and the exact first citation is uncertain.","cn":"英语 carnivore 在 19 世纪出现，确切首见书证存疑。"},{"era":"TAXONOMIC ORDER","en":"Carnivora was fixed as an order name, later creating the awkward fact that some carnivorans are largely herbivorous.","cn":"Carnivora 被定为目名，后来造成一个尴尬事实：有些食肉目成员其实以植物为主食。"},{"era":"PLANT SENSE","en":"The nineteenth-century discovery of insect-eating plants extended carnivore to plants, where it remains a common though informal label.","cn":"19 世纪对食虫植物的发现把 carnivore 扩展到植物，这一标签至今常用，但属非正式说法。"}]},"similar":{"note":{"en":"The look-alike group shares the -vore ending; the near-meaning group separates a diet class from hunting behaviour and taxonomy.","cn":"形近组共享 -vore 结尾；近义组区分食性类别、狩猎行为与分类学。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"herbivore","ipa":"/ˈhɜːbɪvɔː/","tag":"plant eater","definition":"An animal that eats plants. It is the opposite diet class, differing only in the first element of the compound.","definitionCN":"指以植物为食的动物。它是相反的食性类别，复合词只在第一部分不同。"},{"word":"omnivore","ipa":"/ˈɒmnɪvɔː/","tag":"both diets","definition":"An animal that eats both plants and flesh. A carnivore may occasionally eat plants without becoming an omnivore in the classificatory sense.","definitionCN":"指既吃植物也吃肉的动物。食肉动物偶尔吃植物，并不因此在分类上变成杂食动物。"},{"word":"carnivorous","ipa":"/kɑːˈnɪvərəs/","tag":"the adjective","definition":"The adjective form. Carnivore is the noun for the animal, so a plant is described as carnivorous, not as a carnivore in formal writing.","definitionCN":"形容词形式。carnivore 是动物的名词，因此在正式写作中植物应说成 carnivorous，而不是 carnivore。"}]},{"heading":"NEAR MEANING","entries":[{"word":"predator","ipa":"/ˈpriːdeɪtə/","tag":"the hunter","definition":"One that hunts and kills. A predator may eat plants as well, and a carnivore may be a scavenger that never hunts.","definitionCN":"指猎杀者。捕食者也可能吃植物，而食肉动物可能是从不狩猎的食腐者。"},{"word":"raptor","ipa":"/ˈræptə/","tag":"grasping hunter","definition":"A bird of prey, or in palaeontology a grasping dinosaur. It names a hunting form, not a diet class.","definitionCN":"指猛禽，古生物学中也指具抓握能力的恐龙。它命名狩猎形态，而非食性类别。"},{"word":"insectivore","ipa":"/ɪnˈsektɪvɔː/","tag":"insect eater","definition":"An animal that eats mainly insects. It is a narrower diet class that can sit inside carnivory.","definitionCN":"指以昆虫为主食的动物，是更窄的食性类别，可归入食肉范畴。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"caro 'flesh' + vorare 'devour': the flesh devourer.","cn":"caro「肉」+ vorare「吞食」：吞食肉者。"},{"en":"The family runs carnivorous, carnivory, carnassial and the order name Carnivora.","cn":"同族词包括 carnivorous、carnivory、carnassial 以及目名 Carnivora。"},{"en":"Fixed phrases: obligate carnivore, top carnivore, large carnivore, carnivore guild.","cn":"固定搭配：专性食肉动物、顶级食肉动物、大型食肉动物、食肉集团。"},{"en":"Carnivora is an order, not a diet rule: bears belong to it and still eat berries.","cn":"Carnivora 是一个目，不是食性规则：熊属于该目，却仍吃浆果。"},{"en":"Carnal and carnage share the caro- root, which is about flesh rather than eating.","cn":"carnal 与 carnage 共享 caro- 词根，该词根指肉，而非吃。"}],"abstract":[{"en":"Picture a wolf worrying a carcass while the pack waits in a ring.","cn":"想象一只狼撕扯尸体，狼群在外圈等待。"},{"en":"Picture a pitcher plant holding a fly in its fluid.","cn":"想象猪笼草把一只苍蝇泡在液体里。"},{"en":"Picture a fossil jaw with one blade-like tooth standing taller than the rest.","cn":"想象一块化石颌骨，其中一枚刀状齿高出其余。"}]},"examples":[{"en":"Large carnivores need wide ranges and abundant prey.","cn":"大型食肉动物需要广阔的活动范围与充足的猎物。"},{"en":"The cat is an obligate carnivore and cannot thrive on plants.","cn":"猫是专性食肉动物，无法靠植物良好生存。"},{"en":"Carnivorous plants supplement their mineral intake with insects.","cn":"食虫植物用昆虫补充矿物质摄入。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"carni（肉）+ vore（吃……者）→ 吃肉的 → carnivore 食肉动物","word":"carnivore"},"root":"拉丁 caro, carnis「肉」+ vorare「吞食」→ 科学拉丁语 carnivorus／carnivore「吞食肉者」。","sensesIntro":{"en":"Eight senses all name a flesh eater, but the boundary shifts: physiology, position in the chain, tooth shape, community role, plants and taxonomy each redraw it.","cn":"八个义项都指食肉者，但边界不断移动：生理、链条位置、齿形、群落角色、植物与分类学各自重新划定它。"},"semanticMap":{"core":{"en":"CORE IMAGE: a wolf tearing at a carcass while the pack circles.","cn":"核心意象：一只狼撕扯尸体，狼群在外围。"},"chain":["FLESH DIET","OBLIGATE NEED","TOP POSITION","SHEARING TEETH","COMMUNITY GUILD","TAXONOMIC ORDER"],"branches":[{"senses":"01 · 02","en":"DIET AND PHYSIOLOGY: eating flesh is the base, and inability to use plants makes it obligatory.","cn":"食性与生理：吃肉是基本义，无法利用植物则使它成为专性。"},{"senses":"03 · 05","en":"POSITION AND COMMUNITY: apex carnivores and guilds describe how the class is arranged.","cn":"位置与群落：顶级食肉者与食肉集团描述这一类的排列方式。"},{"senses":"04","en":"EVIDENCE: shearing teeth let palaeontologists read diet from bone.","cn":"证据：裂齿让古生物学家从骨骼读出食性。"},{"senses":"06 · 08","en":"BOUNDARY CASES: plants and the order Carnivora both stretch the label past its diet meaning.","cn":"边界个案：食虫植物与食肉目都把标签拉伸到食性义之外。"},{"senses":"07","en":"CULTURE: human meat eating borrows the zoological word as identity.","cn":"文化：人类食肉借用这个动物学词汇作为身份。"}]},"affixes":{"intro":{"en":"Carnivore is the flesh branch of the -vore family, and its stem caro- also feeds words about the body and about slaughter.","cn":"carnivore 是 -vore 词族中的「肉」支，其词干 caro- 还衍生出关于身体与屠杀的词。"},"latinIntro":{"en":"Caro, carnis is a third-declension noun for flesh, vorare a first-conjugation verb for devouring, and -vorus the adjectival form.","cn":"caro, carnis 是第三变格的「肉」名词，vorare 是第一变格的「吞食」动词，-vorus 是形容词形式。"},"items":[{"word":"carnivore","structure":"caro (flesh) + vorare (devour)","meaning":"flesh-eating animal","meaningCN":"食肉动物","example":"The forest holds three large carnivores.","exampleCN":"这片森林里有三种大型食肉动物。"},{"word":"carnivorous","structure":"carnivore + -ous (adjective)","meaning":"flesh-eating","meaningCN":"食肉的","example":"Carnivorous fish patrol the reef edge.","exampleCN":"食肉鱼类巡游在礁缘。"},{"word":"carnivory","structure":"carnivore + -y (abstract noun)","meaning":"the practice of eating flesh","meaningCN":"食肉习性","example":"Carnivory appears in several lizard lineages.","exampleCN":"食肉习性出现在好几个蜥蜴谱系中。"},{"word":"carnassial","structure":"carn- (flesh) + -assial (adapted for cutting)","meaning":"a shearing tooth of a carnivore","meaningCN":"食肉动物用于剪切的牙齿","example":"The carnassial pair works like scissors.","exampleCN":"那对裂齿像剪刀一样工作。"},{"word":"Carnivora","structure":"caro + vorare + -a (order name)","meaning":"the mammalian order of flesh eaters","meaningCN":"哺乳动物的食肉目","example":"Carnivora includes both hunters and berry eaters.","exampleCN":"食肉目既包含猎手，也包含吃浆果者。"},{"word":"carnal","structure":"caro, carnis + -al (adjective)","meaning":"of the flesh, bodily","meaningCN":"肉体的、身体层面的","example":"The poem contrasts carnal appetite with reason.","exampleCN":"这首诗把肉体欲望与理性对照。"},{"word":"carnage","structure":"caro, carnis + French -age (mass noun)","meaning":"mass slaughter","meaningCN":"大量屠杀","example":"The battlefield was a scene of carnage.","exampleCN":"战场是一片屠杀景象。"},{"word":"herbivore","structure":"herba (grass) + vorare","meaning":"plant-eating animal","meaningCN":"植食动物","example":"Herbivores and carnivores split the grass crop.","exampleCN":"植食动物与食肉动物分食草料。"},{"word":"omnivore","structure":"omni- (all) + vorare","meaning":"animal eating both","meaningCN":"杂食动物","example":"The omnivore takes fruit and insects alike.","exampleCN":"杂食动物既吃果实也吃昆虫。"}],"latinEntries":[{"word":"caro","structure":"caro, carnis (n., third declension)","meaning":"flesh, meat","meaningCN":"肉、肉体"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour","meaningCN":"吞食"},{"word":"carnivorus","structure":"carnivorus, carnivora, carnivorum (adj., scientific Latin)","meaning":"flesh-eating","meaningCN":"食肉的"}]}},{"word":"carnivorous","ipa_uk":"/kɑːˈnɪvərəs/","ipa_us":"/kɑːrˈnɪvərəs/","definition_zh":"食肉的；肉食性的","definition_en":"describing an animal or plant that feeds on animal flesh, or a diet based on meat","core_image":"一枚刀状裂齿咬合另一枚，像剪刀一样把韧带剪断","scene":"Carnivorous plants such as sundews digest insects to supplement the poor soil.","sceneCN":"这里 carnivorous 指「食肉的」（第 1 个义项：以动物肉体为食）；茅膏菜等食肉植物消化昆虫，以弥补贫瘠土壤的养分。图中可辨识物件：裂齿、剪刀状咬合、茅膏菜、昆虫。","pos":[{"tag":"adj.","zh":"食肉的；肉食性的（比较级 more carnivorous，最高级 most carnivorous）"}],"collocations":[{"phrase":"carnivorous plant","zh":"食虫植物；食肉植物"},{"phrase":"carnivorous dinosaur","zh":"肉食性恐龙"},{"phrase":"carnivorous fish","zh":"肉食性鱼类"},{"phrase":"carnivorous mammal","zh":"肉食性哺乳动物"},{"phrase":"carnivorous diet","zh":"肉食性食谱"},{"phrase":"strictly carnivorous","zh":"严格食肉的"},{"phrase":"carnivorous larva","zh":"肉食性幼虫"}],"forms":[{"label":"比较级","form":"more carnivorous"},{"label":"最高级","form":"most carnivorous"},{"label":"副词形式","form":"carnivorously（以食肉方式；罕用）"},{"label":"名词形式","form":"carnivore（食肉动物）；carnivory（食肉性）"},{"label":"作定语","form":"carnivorous + 名词（如 carnivorous plant、carnivorous beetle）"}],"derivatives":[{"word":"carnivore","pos":"n.","zh":"食肉动物；食虫植物"},{"word":"carnivory","pos":"n.","zh":"食肉；肉食性"},{"word":"carnassial","pos":"adj./n.","zh":"裂齿的；食肉动物的剪切齿"},{"word":"Carnivora","pos":"n.","zh":"食肉目"},{"word":"herbivorous","pos":"adj.","zh":"植食性的（对照词）"},{"word":"omnivorous","pos":"adj.","zh":"杂食性的（对照词）"}],"senses":[{"no":"01","title":"Flesh as the main food","titleCN":"食肉性：以动物肉体为主要食物","definition":"describing an animal whose diet is mainly the flesh of other animals","definitionCN":"描述以其他动物的肉体为主要食物的动物","example":"The carnivorous beetle hunts smaller insects in the leaf litter.","exampleCN":"这种肉食性甲虫在落叶层中猎食更小的昆虫。","why":"The adjective states a diet class, so it can describe any animal without committing to a taxonomic group.","whyCN":"这个形容词陈述食性类别，因此能描述任何动物，而不必归属于某个分类群。"},{"no":"02","title":"Carnivorous plants","titleCN":"食虫植物：捕虫补养分","definition":"describing a plant that traps and digests small animals to obtain nitrogen or other nutrients","definitionCN":"描述通过捕获并消化小动物来获取氮等养分的植物","example":"The bog is full of carnivorous plants that thrive where roots cannot feed.","exampleCN":"这片酸性泥炭沼泽满是食虫植物，它们在根系无法取食的地方繁茂生长。","why":"The plant does not hunt for energy but for minerals, so the adjective is borrowed for a nutrient strategy.","whyCN":"这些植物捕猎不是为了能量，而是为了矿物质，因此这个形容词被借来描述一种养分策略。"},{"no":"03","title":"Carnivorous dinosaurs","titleCN":"肉食恐龙：以化石齿型判定","definition":"describing extinct reptiles identified as meat eaters from curved, serrated teeth and jaw mechanics","definitionCN":"描述依据弯曲锯齿状牙齿与颌部力学判定为食肉的已灭绝爬行动物","example":"Carnivorous dinosaurs such as tyrannosaurs had recurved serrated teeth.","exampleCN":"暴龙这类肉食恐龙长有向后弯的锯齿状牙齿。","why":"Palaeontology reads diet from morphology, so the adjective often appears beside tooth and jaw evidence.","whyCN":"古生物学从形态读出食性，因此这个形容词常与牙齿和颌部证据一起出现。"},{"no":"04","title":"Carnivorous fish","titleCN":"肉食鱼类：以其他鱼或甲壳类为食","definition":"describing fish that prey on other fish, crustaceans or molluscs","definitionCN":"描述捕食其他鱼、甲壳类或软体动物的鱼类","example":"Carnivorous fish dominate the upper levels of the reef food web.","exampleCN":"肉食鱼类主导礁体食物网的上层。","why":"Aquaculture and fisheries use the label to separate feed requirements, since carnivorous fish need protein-rich feed.","whyCN":"水产养殖与渔业用这个标签区分饲料需求，因为肉食鱼需要高蛋白饲料。"},{"no":"05","title":"Carnivorous mammals","titleCN":"肉食哺乳动物：裂齿与咬合","definition":"describing mammals with shearing carnassial teeth and jaws built for cutting flesh","definitionCN":"描述具有剪切裂齿与适合切割肉类的颌部的哺乳动物","example":"The carnivorous skull has a short jaw and powerful bite muscles.","exampleCN":"肉食性头骨具有短颌与强劲咬肌。","why":"Mammalian carnivory has a distinctive anatomical signature, and the adjective often flags that signature in fossils.","whyCN":"哺乳动物食肉有独特的解剖签名，这个形容词常在化石中标出该签名。"},{"no":"06","title":"Carnivorous birds","titleCN":"肉食鸟类：猛禽与食肉水鸟","definition":"describing birds that hunt or scavenge animal flesh, such as hawks, owls and vultures","definitionCN":"描述猎食或食腐动物肉的鸟类，如鹰、鸮与秃鹫","example":"Carnivorous birds concentrate at the river during the fish run.","exampleCN":"鱼汛期间，肉食鸟类聚集在河边。","why":"Flight adds a hunting style of its own, but the diet label stays the same as for ground predators.","whyCN":"飞行带来独特的狩猎方式，但食性标签与地面捕食者相同。"},{"no":"07","title":"A carnivorous human diet","titleCN":"人类肉食饮食：以肉为主的食谱","definition":"describing a human diet that is based mainly or entirely on animal products","definitionCN":"描述主要或完全以动物性食物为基础的人类饮食","example":"The clinic studied a carnivorous diet low in fibre and high in fat.","exampleCN":"诊所研究了一种低纤维、高脂肪的肉食饮食。","why":"Here the adjective moves from zoology to nutrition, where it labels a diet rather than a species.","whyCN":"这里这个形容词从动物学移到营养学，标注的是食谱而非物种。"},{"no":"08","title":"Carnivorous behaviour in insects","titleCN":"昆虫的肉食行为：捕食与寄生","definition":"describing insects that kill and eat other insects, whether as hunters or as parasitoids","definitionCN":"描述杀死并取食其他昆虫的昆虫，无论是捕食者还是拟寄生者","example":"Carnivorous wasps are used to control caterpillar pests.","exampleCN":"肉食性蜂类被用来控制毛虫害虫。","why":"Biological control depends on this label, because only a flesh-eating insect can regulate a pest population.","whyCN":"生物防治依赖这个标签，因为只有食肉的昆虫才能调节害虫种群。"}],"etymology":{"intro":{"en":"Carnivorous is the Latin adjective carnivorus, from caro 'flesh' and vorare 'devour'. It is the adjectival twin of the noun carnivore.","cn":"carnivorous 是拉丁形容词 carnivorus，由 caro「肉」与 vorare「吞食」构成，是名词 carnivore 的形容词孪生形式。"},"items":[{"era":"LATIN CARO","en":"Caro, carnis meant flesh or meat, and it also survives in carnal and carnage.","cn":"caro, carnis 意为肉或肉体，也保存在 carnal 与 carnage 中。"},{"era":"LATIN VORARE","en":"Vorare meant to devour. The compound pattern -vorus 'eating' was used for diet adjectives in scientific Latin.","cn":"vorare 意为吞食；复合成分 -vorus「吃……的」在科学拉丁语中用于构成食性形容词。"},{"era":"SCIENTIFIC LATIN","en":"Carnivorus was the standard adjective for flesh-eating in modern scientific Latin, and its exact first use is uncertain.","cn":"carnivorus 是近代科学拉丁语中表示食肉的标准形容词，确切首用存疑。"},{"era":"ENGLISH ENTRY","en":"English carnivorous appears in the seventeenth century, earlier than the noun in common use. The exact first citation is uncertain.","cn":"英语 carnivorous 在 17 世纪出现，比名词的通行用法更早；确切首见书证存疑。"},{"era":"PLANT SENSE","en":"The plant sense developed in the nineteenth century as botanists described species that trap insects.","cn":"植物义在 19 世纪发展出来，当时植物学家描述捕虫的物种。"}]},"similar":{"note":{"en":"The look-alike group shares the -vorous ending and differs by stem; the near-meaning group separates diet, behaviour and taxonomy.","cn":"形近组共享 -vorous 结尾而词干不同；近义组区分食性、行为与分类。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"carnivore","ipa":"/ˈkɑːnɪvɔː/","tag":"the noun","definition":"The animal or plant itself. Use carnivorous when the word must modify a noun, as in carnivorous plant.","definitionCN":"指动物或植物本身。需要修饰名词时应使用 carnivorous，如 carnivorous plant。"},{"word":"herbivorous","ipa":"/hɜːˈbɪvərəs/","tag":"plant-eating","definition":"Describes a plant diet. The stem herba- is the only difference, and the two adjectives mark opposite diets.","definitionCN":"描述植食。词干 herba- 是唯一差别，两个形容词标示相反食性。"},{"word":"omnivorous","ipa":"/ɒmˈnɪvərəs/","tag":"eating both","definition":"Describes a mixed diet. It is broader than carnivorous, because plant food is included.","definitionCN":"描述混合食性。它比 carnivorous 更宽，因为包含植物性食物。"}]},{"heading":"NEAR MEANING","entries":[{"word":"predatory","ipa":"/prɪˈdeɪtəri/","tag":"hunting behaviour","definition":"Describes hunting and killing. A carnivorous animal may live on carrion and never hunt, so the two adjectives answer different questions.","definitionCN":"描述猎杀行为。食肉动物可能靠腐肉为生而从不狩猎，因此两个形容词回答不同问题。"},{"word":"flesh-eating","ipa":"/ˈfleʃ iːtɪŋ/","tag":"the plain paraphrase","definition":"A transparent compound with the same meaning but no scientific register. It is common in news writing about outbreaks.","definitionCN":"透明的复合词，含义相同但不带科学语域，常见于疫情新闻报道。"},{"word":"insectivorous","ipa":"/ˌɪnsektɪˈvɔːrəs/","tag":"insects only","definition":"Describes a diet of insects. It is a narrower class that can fall inside carnivorous.","definitionCN":"描述以昆虫为食，是更窄的类别，可归入食肉范畴。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"caro 'flesh' + -vorous 'eating': flesh-eating.","cn":"caro「肉」+ -vorous「吃……的」：食肉的。"},{"en":"Typical phrases: carnivorous plant, carnivorous dinosaur, carnivorous fish, carnivorous diet.","cn":"典型搭配：食虫植物、肉食恐龙、肉食鱼类、肉食饮食。"},{"en":"The family runs carnivore, carnivory, carnassial and Carnivora.","cn":"同族词包括 carnivore、carnivory、carnassial、Carnivora。"},{"en":"Carnivorous answers what it eats; predatory answers how it gets it.","cn":"carnivorous 回答吃什么；predatory 回答怎么得到。"},{"en":"The plant sense is about minerals, not energy: the bog soil is too poor for roots.","cn":"植物义关乎矿物质而非能量：沼泽土壤太贫瘠，根系取不到养分。"}],"abstract":[{"en":"Picture two blade-like teeth sliding past each other like scissors.","cn":"想象两枚刀状齿像剪刀一样相互滑过。"},{"en":"Picture a sundew's sticky tentacles curling around a fly.","cn":"想象茅膏菜的黏性触须卷住一只苍蝇。"},{"en":"Picture a hawk's curved beak tearing a fish on the riverbank.","cn":"想象鹰的弯喙在河岸撕开一条鱼。"}]},"examples":[{"en":"Carnivorous plants grow where the soil lacks nitrogen.","cn":"食虫植物生长在缺氮的土壤上。"},{"en":"The carnivorous dinosaur's teeth were built for slicing, not grinding.","cn":"这种肉食恐龙的牙齿适合切割而非研磨。"},{"en":"Carnivorous fish require high-protein feed in captivity.","cn":"肉食性鱼类在人工饲养下需要高蛋白饲料。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"carnivore（食肉动物）+ ous（……的）→ 食肉的 → carnivorous","word":"carnivorous"},"root":"拉丁 caro, carnis「肉」+ vorare「吞食」→ 科学拉丁语 carnivorus「食肉的」→ 英语 carnivorous。","sensesIntro":{"en":"Eight senses apply the flesh-diet adjective to animals, plants, fossils, fish, mammals, birds, human diets and insects.","cn":"八个义项把这个食肉形容词用于动物、植物、化石、鱼类、哺乳动物、鸟类、人类饮食与昆虫。"},"semanticMap":{"core":{"en":"CORE IMAGE: two blade-like teeth sliding together like scissors.","cn":"核心意象：两枚刀状齿像剪刀一样咬合。"},"chain":["FLESH DIET","PLANT TRAP","FOSSIL TEETH","AQUATIC HUNTER","MAMMALIAN SHEAR","HUMAN DIET"],"branches":[{"senses":"01","en":"DIET: the base sense says flesh is the main food.","cn":"食性：基本义说肉是主要食物。"},{"senses":"02","en":"PLANTS: the adjective is borrowed for a mineral strategy, not a hunt for energy.","cn":"植物：这个形容词被借来描述养分策略，而非为能量捕猎。"},{"senses":"03 · 05","en":"DEEP TIME: teeth and jaws let the label be read from fossils.","cn":"深层时间：牙齿与颌部让这个标签能从化石读出。"},{"senses":"04 · 06 · 08","en":"HUNTERS: fish, birds and insects show how many forms the flesh diet takes.","cn":"猎手：鱼、鸟与昆虫展示了食肉方式的多样形态。"},{"senses":"07","en":"NUTRITION: the same adjective labels a human diet rather than a species.","cn":"营养：同一个形容词标注人类食谱而非物种。"}]},"affixes":{"intro":{"en":"Carnivorous is the adjective branch of the -vore family, with caro- 'flesh' as its stem.","cn":"carnivorous 是 -vore 词族中的形容词支，词干为 caro-「肉」。"},"latinIntro":{"en":"Caro is a third-declension noun, vorare a first-conjugation verb, and -vorus the adjective ending used in diet compounds.","cn":"caro 是第三变格名词，vorare 是第一变格动词，-vorus 是食性复合词中的形容词词尾。"},"items":[{"word":"carnivorous","structure":"caro (flesh) + vorare (devour) + -ous","meaning":"flesh-eating","meaningCN":"食肉的","example":"The carnivorous snail drills into other shells.","exampleCN":"这种肉食性螺钻进其他贝壳。"},{"word":"carnivore","structure":"caro + vorare + noun ending","meaning":"flesh-eating animal or plant","meaningCN":"食肉动物或食虫植物","example":"The carnivore hunts at night.","exampleCN":"这只食肉动物夜间狩猎。"},{"word":"carnivory","structure":"carnivore + -y (abstract noun)","meaning":"the practice of eating flesh","meaningCN":"食肉习性","example":"Carnivory evolved repeatedly in mammals.","exampleCN":"食肉习性在哺乳动物中多次演化。"},{"word":"carnassial","structure":"carn- (flesh) + -assial (cutting)","meaning":"shearing tooth","meaningCN":"剪切齿","example":"The carnassials meet like scissors.","exampleCN":"裂齿像剪刀一样咬合。"},{"word":"Carnivora","structure":"caro + vorare + -a (order)","meaning":"the flesh-eater order","meaningCN":"食肉目","example":"Carnivora contains seals as well as cats.","exampleCN":"食肉目既含海豹也含猫。"},{"word":"herbivorous","structure":"herba (grass) + vorare + -ous","meaning":"plant-eating","meaningCN":"植食的","example":"Herbivorous mammals have flat molars.","exampleCN":"植食哺乳动物臼齿扁平。"},{"word":"omnivorous","structure":"omni- (all) + vorare + -ous","meaning":"eating both diets","meaningCN":"杂食的","example":"Omnivorous animals switch with the season.","exampleCN":"杂食动物随季节切换食物。"},{"word":"insectivorous","structure":"insectum (insect) + vorare + -ous","meaning":"insect-eating","meaningCN":"食虫的","example":"Insectivorous birds nest in the orchard.","exampleCN":"食虫鸟类在果园筑巢。"},{"word":"carnage","structure":"caro, carnis + -age (mass noun)","meaning":"mass slaughter","meaningCN":"大量屠杀","example":"The flood left carnage along the valley.","exampleCN":"洪水在谷地留下惨烈景象。"}],"latinEntries":[{"word":"caro","structure":"caro, carnis (n., third declension)","meaning":"flesh, meat","meaningCN":"肉、肉体"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour","meaningCN":"吞食"},{"word":"carnivorus","structure":"carnivorus, carnivora, carnivorum (adj., scientific Latin)","meaning":"flesh-eating","meaningCN":"食肉的"}]}},{"word":"omnivore","ipa_uk":"/ˈɒmnɪvɔː/","ipa_us":"/ˈɑːmnɪvɔːr/","definition_zh":"杂食动物；杂食者；兴趣广泛的人","definition_en":"an animal that eats both plant and animal food, or a person with broadly varied tastes and interests","core_image":"一只熊一手扒开蚁巢、一手拽下浆果，嘴里既嚼昆虫也嚼果实","scene":"The bear is an omnivore that switches from berries in summer to salmon in autumn.","sceneCN":"这里 omnivore 指「杂食动物」（第 1 个义项：既吃植物也吃动物）；这只熊夏季吃浆果，秋季改吃鲑鱼。图中可辨识物件：熊、蚁巢、浆果、鲑鱼。","pos":[{"tag":"n.","zh":"杂食动物；杂食者；兴趣广泛的人（可数，复数 omnivores）"}],"collocations":[{"phrase":"opportunistic omnivore","zh":"机会主义杂食者；遇到什么吃什么"},{"phrase":"omnivore diet","zh":"杂食食谱"},{"phrase":"human omnivore","zh":"人类杂食者"},{"phrase":"omnivore population","zh":"杂食动物种群"},{"phrase":"cultural omnivore","zh":"文化杂食者；品味跨越高雅与通俗的人"},{"phrase":"digital omnivore","zh":"数字杂食者；跨多种设备与平台使用内容的人"},{"phrase":"a true omnivore","zh":"真正的杂食动物"}],"forms":[{"label":"复数","form":"omnivores"},{"label":"形容词","form":"omnivorous（杂食的）"},{"label":"名词（杂食性）","form":"omnivory（杂食性；杂食行为）"},{"label":"副词形式","form":"omnivorously（杂食地；广泛地；罕用）"}],"derivatives":[{"word":"omnivorous","pos":"adj.","zh":"杂食的；兴趣广泛的"},{"word":"omnivory","pos":"n.","zh":"杂食性"},{"word":"omni-","pos":"prefix","zh":"全、都（构词前缀）"},{"word":"omnibus","pos":"n.","zh":"汇编本；公共汽车（同出 omnis）"},{"word":"herbivore","pos":"n.","zh":"食草动物（对照词）"},{"word":"carnivore","pos":"n.","zh":"食肉动物（对照词）"}],"senses":[{"no":"01","title":"Eating both plants and animals","titleCN":"杂食动物：植物与动物通吃","definition":"an animal whose diet includes substantial amounts of both plant and animal material","definitionCN":"指食物中植物与动物材料都占相当比重的动物","example":"The raccoon is an omnivore that takes fruit, insects and carrion.","exampleCN":"浣熊是杂食动物，吃果实、昆虫与腐肉。","why":"The word fills the plus-plus dietary cell, defined by neither plant nor flesh alone but by both.","whyCN":"这个词填补食性表格中「两者都吃」的格子，既不只靠植物也不只靠肉，而是两者兼有。"},{"no":"02","title":"The human omnivore","titleCN":"人类杂食者：生理上适应混合饮食","definition":"a human considered as a species adapted to a mixed diet of plants and animal products","definitionCN":"指从物种层面被看作适应植物与动物性混合饮食的人类","example":"As an omnivore, the human gut can use both grains and meat.","exampleCN":"作为杂食者，人的肠道既能利用谷物也能利用肉类。","why":"The label is used in nutrition and anthropology to describe a species-level capacity, not an individual choice.","whyCN":"这个标签在营养学与人类学中描述物种层面的能力，而非个人选择。"},{"no":"03","title":"Opportunistic omnivore","titleCN":"机会主义杂食者：随资源变化切换","definition":"an omnivore whose diet shifts with whatever is available, rather than following a fixed preference","definitionCN":"指食性随可得资源变化、而非遵循固定偏好的杂食动物","example":"The fox is an opportunistic omnivore that follows the fruit season.","exampleCN":"狐狸是机会主义杂食者，跟着果实季节改变食物。","why":"Flexibility is the point: the same animal can live through seasons when one food source fails.","whyCN":"灵活性是关键：当一种食物来源失败时，同一种动物仍能熬过季节。"},{"no":"04","title":"Member of a feeding guild","titleCN":"取食集团成员：生态学分类单位","definition":"in community ecology, an omnivore as a member of a guild that feeds at several trophic levels","definitionCN":"群落生态学中指作为在多个营养级取食的集团成员的杂食动物","example":"Omnivores link the plant and animal channels of the food web.","exampleCN":"杂食动物连接食物网中的植物通道与动物通道。","why":"Omnivores complicate the tidy trophic pyramid, because one species occupies several levels at once.","whyCN":"杂食动物让整齐的营养金字塔变复杂，因为一个物种同时占据多个层级。"},{"no":"05","title":"Gut generalist","titleCN":"消化道泛化：酶与菌群兼顾两类食物","definition":"an omnivore defined by a digestive system able to handle both plant fibre and animal protein","definitionCN":"指消化道能够同时处理植物纤维与动物蛋白的杂食动物","example":"The omnivore's midgut carries enzymes for starch as well as for protein.","exampleCN":"杂食者的中肠既带淀粉酶也带蛋白酶。","why":"The class is physiological as well as behavioural: the gut must be a compromise between two diets.","whyCN":"这一类既是行为类别也是生理类别：消化道必须是两种食性的折中。"},{"no":"06","title":"Cultural omnivore","titleCN":"文化杂食者：品味跨越雅俗","definition":"in sociology, a person who consumes both highbrow and popular culture rather than sticking to one tier","definitionCN":"社会学中指既消费高雅文化也消费通俗文化、不固守单一层级的人","example":"The survey found that cultural omnivores attended both opera and football.","exampleCN":"调查发现文化杂食者既看歌剧也看足球。","why":"The metaphor borrows the dietary word because taste is treated as a menu with many courses.","whyCN":"这个比喻借用饮食词汇，因为品味被当作有许多菜目的菜单。"},{"no":"07","title":"Digital omnivore","titleCN":"数字杂食者：跨设备跨平台使用内容","definition":"in media research, a user who consumes content across several devices and platforms rather than one channel","definitionCN":"媒介研究中指跨多种设备与平台、而非只用单一渠道消费内容的用户","example":"Digital omnivores move between phone, laptop and television in one evening.","exampleCN":"数字杂食者一个晚上就在手机、笔记本与电视之间切换。","why":"Media studies extends the diet metaphor to attention, where the menu is platforms rather than plants and meat.","whyCN":"媒介研究把饮食比喻扩展到注意力，菜单从植物与肉变成平台。"},{"no":"08","title":"A broadly curious person","titleCN":"兴趣广泛者：什么都想读一点","definition":"an informal use for a person who reads, studies or tries many unrelated things","definitionCN":"口语用法，指阅读、研究或尝试许多不相关事物的人","example":"He is an omnivore of ideas, equally at home in physics and poetry.","exampleCN":"他是观念上的杂食者，在物理与诗歌中都自在。","why":"The dietary metaphor softens specialisation into appetite, which is why it is used approvingly.","whyCN":"饮食比喻把专业化软化为胃口，因此这个说法常带赞许。"}],"etymology":{"intro":{"en":"Omnivore combines Latin omnis 'all' with vorare 'to devour'. The adjective omnivorous is older; the noun is generally treated as a later back-formation.","cn":"omnivore 由拉丁语 omnis「全部」与 vorare「吞食」构成。形容词 omnivorous 出现更早，名词一般认为是由它逆构而来。"},"items":[{"era":"LATIN OMNIS","en":"Omnis meant all or every, and it also gives omnibus, omnipotent and omniscient.","cn":"omnis 意为全部、每个，也是 omnibus、omnipotent、omniscient 的来源。"},{"era":"LATIN VORARE","en":"Vorare meant to devour, the same verb that closes herbivore and carnivore.","cn":"vorare 意为吞食，与 herbivore、carnivore 结尾的动词相同。"},{"era":"SCIENTIFIC LATIN","en":"Omnivorus was formed in scientific Latin as the adjective for a mixed diet. Its exact first use is uncertain.","cn":"omnivorus 在科学拉丁语中构成，作为混合食性的形容词；确切首用存疑。"},{"era":"ENGLISH ADJECTIVE","en":"English omnivorous is recorded in the seventeenth century. The exact first citation is uncertain, and the early uses may have been figurative.","cn":"英语 omnivorous 见于 17 世纪；确切首见书证存疑，早期用法可能已是比喻。"},{"era":"NOUN AS BACK-FORMATION","en":"Omnivore as a noun is generally dated to the nineteenth century and treated as a back-formation from omnivorous, though the dating is not fixed.","cn":"名词 omnivore 一般认为出现在 19 世纪，被视为由 omnivorous 逆构而来，但年代并不确定。"},{"era":"METAPHORICAL SPREAD","en":"Twentieth-century sociology and media studies formed cultural omnivore and digital omnivore, extending 'all' to tastes and platforms.","cn":"20 世纪的社会学与媒介研究造出文化杂食者与数字杂食者，把「全部」扩展到品味与平台。"}]},"similar":{"note":{"en":"The look-alike group is the three diet classes; the near-meaning group separates the broad eater from the flexible strategist.","cn":"形近组是三个食性类别；近义组区分广泛取食者与灵活策略者。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"herbivore","ipa":"/ˈhɜːbɪvɔː/","tag":"plants only","definition":"An animal that eats plants. It is the plant-only class, and the first element herba- marks the difference.","definitionCN":"指以植物为食的动物。它是纯植食类别，前半 herba- 标出差别。"},{"word":"carnivore","ipa":"/ˈkɑːnɪvɔː/","tag":"flesh only","definition":"An animal that eats flesh. It is the flesh-only class, and omni- 'all' is what separates it from omnivore.","definitionCN":"指以肉为食的动物。它是纯肉食类别，正是 omni-「全部」把它与杂食动物区分开。"},{"word":"omnivorous","ipa":"/ɒmˈnɪvərəs/","tag":"the adjective","definition":"The adjective form meaning mixed-diet. Omnivore is the noun, so a bear is an omnivore and has an omnivorous diet.","definitionCN":"形容词形式，意为混合食性的。omnivore 是名词，因此熊是 omnivore，饮食是 omnivorous。"}]},{"heading":"NEAR MEANING","entries":[{"word":"generalist","ipa":"/ˈdʒenrəlɪst/","tag":"broad niche","definition":"A species that uses many resources. It overlaps with omnivore but is broader, since a generalist may use many habitats without eating both plants and meat.","definitionCN":"指利用多种资源的物种。它与杂食动物重叠但更宽，因为广适种可能利用多种生境却不吃植物与肉。"},{"word":"opportunist","ipa":"/ˌɒpəˈtjuːnɪst/","tag":"flexible strategy","definition":"One that takes whatever chance offers. It describes behaviour, while omnivore describes diet.","definitionCN":"指抓住任何机会者。它描述行为，而 omnivore 描述食性。"},{"word":"polyphagous","ipa":"/pɒˈlɪfəɡəs/","tag":"many food types","definition":"A technical adjective for feeding on many kinds of food, common in entomology. It is close to omnivorous but usually applied to invertebrates.","definitionCN":"技术形容词，指取食多种食物，常见于昆虫学。它接近 omnivorous，但多用于无脊椎动物。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives.","cn":"正常联想：真实构词成分、真实搭配与真实同族词。"},"normal":[{"en":"omni 'all' + vore 'eater': the eater of everything.","cn":"omni「全部」+ vore「吃……者」：什么都吃者。"},{"en":"The family runs omnivorous, omnivory, omnibus, omnipotent and omniscient.","cn":"同族词包括 omnivorous、omnivory、omnibus、omnipotent、omniscient。"},{"en":"Typical phrases: opportunistic omnivore, omnivore diet, cultural omnivore, digital omnivore.","cn":"典型搭配：机会主义杂食者、杂食食谱、文化杂食者、数字杂食者。"},{"en":"The three classes share -vore; only the first element changes: herbi-, carni-, omni-.","cn":"三个类别共享 -vore，只有前半变化：herbi-、carni-、omni-。"},{"en":"The noun is generally a back-formation from the older adjective omnivorous.","cn":"名词一般被视为由更早的形容词 omnivorous 逆构而来。"}],"abstract":[{"en":"Picture a bear pulling berries with one paw and breaking into an anthill with the other.","cn":"想象熊一只爪摘浆果，另一只爪扒开蚁巢。"},{"en":"Picture a reader with opera tickets and a football scarf in the same bag.","cn":"想象一位读者的包里同时装着歌剧票与球迷围巾。"},{"en":"Picture one person switching between phone, laptop and television before dinner ends.","cn":"想象一个人在晚饭结束前就在手机、笔记本与电视之间切换。"}]},"examples":[{"en":"The raccoon is an omnivore that thrives beside human settlements.","cn":"浣熊是杂食动物，在人类聚居地旁也能繁盛。"},{"en":"As omnivores, humans can digest both starch and meat.","cn":"作为杂食者，人类既能消化淀粉也能消化肉类。"},{"en":"The survey described her as a cultural omnivore with wide tastes.","cn":"调查把她描述为品味广泛的文化杂食者。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"omni（全部）+ vore（吃……者）→ 什么都吃 → omnivore 杂食动物","word":"omnivore"},"root":"拉丁 omnis「全部」+ vorare「吞食」→ 科学拉丁语 omnivorus；名词 omnivore 一般认为由形容词 omnivorous 逆构而来。","sensesIntro":{"en":"Eight senses start with the mixed diet and extend 'all' to human physiology, opportunity, trophic levels, taste and platforms.","cn":"八个义项从混合食性出发，把「全部」扩展到人类生理、机会、营养级、品味与平台。"},"semanticMap":{"core":{"en":"CORE IMAGE: a bear taking berries and ants with different paws.","cn":"核心意象：熊用两只不同的爪子取浆果与蚂蚁。"},"chain":["MIXED DIET","HUMAN CAPACITY","OPPORTUNISM","TROPHIC LINK","BROAD TASTE","MULTI-PLATFORM USE"],"branches":[{"senses":"01","en":"DIET: the base sense is both plant and animal food.","cn":"食性：基本义是植物与动物性食物兼有。"},{"senses":"02 · 05","en":"PHYSIOLOGY: the human species and its gut are described as mixed-diet generalists.","cn":"生理：人类物种及其肠道被描述为混合食性的泛化者。"},{"senses":"03 · 04","en":"ECOLOGY: flexibility lets the animal follow seasons and link trophic levels.","cn":"生态：灵活性让动物随季节变化，并连接不同营养级。"},{"senses":"07 · 08","en":"MEDIA AND CURIOSITY: platforms and reading habits become menus with many courses.","cn":"媒介与好奇心：平台使用与阅读习惯也成了多道菜的菜单。"},{"senses":"06","en":"CULTURAL WIDENING: 'all' extends from food to a taste that crosses every level.","cn":"文化扩展：「全部」从食物延伸到跨越各层级的口味。"}]},"affixes":{"intro":{"en":"Omnivore is the 'all' branch of the -vore family, and the prefix omni- is productive far beyond diet.","cn":"omnivore 是 -vore 词族中的「全部」支，前缀 omni- 的能产性远超饮食领域。"},"latinIntro":{"en":"Omnis is a Latin adjective meaning all; vorare is the eating verb; the noun ending was added in scientific Latin and later in English.","cn":"omnis 是意为「全部」的拉丁形容词，vorare 是吃的动词，名词词尾先在科学拉丁语、后在英语中加上。"},"items":[{"word":"omnivore","structure":"omni- (all) + vorare (devour) + noun ending","meaning":"an animal eating both plants and flesh","meaningCN":"既吃植物也吃肉的动物","example":"Every omnivore has a favourite food.","exampleCN":"每种杂食动物都有偏爱的食物。"},{"word":"omnivorous","structure":"omni- + vorare + -ous (adjective)","meaning":"mixed-diet; broadly curious","meaningCN":"杂食的；兴趣广泛的","example":"The omnivorous reader takes any genre.","exampleCN":"这位杂食读者任何体裁都读。"},{"word":"omnivory","structure":"omnivore + -y (abstract noun)","meaning":"the practice of eating both diets","meaningCN":"兼食两类的习性","example":"Omnivory blurs the trophic pyramid.","exampleCN":"杂食性模糊了营养金字塔。"},{"word":"omni-","structure":"omni- (prefix, from omnis)","meaning":"all, everywhere","meaningCN":"全部、处处","example":"Omni- appears in omnibus and omnipotent.","exampleCN":"omni- 出现在 omnibus 与 omnipotent 中。"},{"word":"omnibus","structure":"omni- + omnibus (dative plural of omnis)","meaning":"for all; a collected volume; a bus","meaningCN":"为所有人的；汇编本；公共汽车","example":"The publisher issued an omnibus of the trilogy.","exampleCN":"出版社推出了三部曲的合集。"},{"word":"herbivore","structure":"herba (grass) + vorare","meaning":"plant eater","meaningCN":"植食动物","example":"Herbivores and omnivores share the meadow.","exampleCN":"植食动物与杂食动物共用这片草甸。"},{"word":"carnivore","structure":"caro (flesh) + vorare","meaning":"flesh eater","meaningCN":"食肉动物","example":"The carnivore takes only meat.","exampleCN":"这只食肉动物只吃肉。"},{"word":"generalist","structure":"general + -ist (one who)","meaning":"a species or person using many resources","meaningCN":"利用多种资源的物种或人","example":"The omnivore is a dietary generalist.","exampleCN":"杂食动物是食性上的泛化者。"},{"word":"polyphagous","structure":"poly- (many) + phagein (eat) + -ous","meaning":"feeding on many foods","meaningCN":"取食多种食物","example":"Polyphagous insects damage many crops.","exampleCN":"多食性昆虫危害多种作物。"}],"latinEntries":[{"word":"omnis","structure":"omnis, omne (adj., third declension)","meaning":"all, every","meaningCN":"全部、每个"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour","meaningCN":"吞食"},{"word":"omnivorus","structure":"omnivorus, omnivora, omnivorum (adj., scientific Latin)","meaning":"eating all kinds of food","meaningCN":"各类食物都吃的"}]}},{"word":"omnivorous","ipa_uk":"/ɒmˈnɪvərəs/","ipa_us":"/ɑːmˈnɪvərəs/","definition_zh":"杂食性的；什么都吃的；兴趣广泛的","definition_en":"describing an animal or person that consumes both plant and animal material, or more broadly one with very wide tastes","core_image":"一张餐桌上同时摆着谷物、浆果、鱼与昆虫，一把叉子伸向每一种","scene":"The omnivorous bear eats berries in July and salmon in September.","sceneCN":"这里 omnivorous 指「杂食性的」（第 1 个义项：植物与动物性食物都吃）；这只杂食性的熊七月吃浆果，九月吃鲑鱼。图中可辨识物件：餐桌、谷物、浆果、鱼、昆虫。","pos":[{"tag":"adj.","zh":"杂食性的；什么都吃的；兴趣广泛的（比较级 more omnivorous，最高级 most omnivorous）"}],"collocations":[{"phrase":"omnivorous animal","zh":"杂食动物"},{"phrase":"omnivorous diet","zh":"杂食食谱"},{"phrase":"omnivorous bird","zh":"杂食性鸟类"},{"phrase":"omnivorous insect","zh":"杂食性昆虫"},{"phrase":"omnivorous reader","zh":"什么书都读的人"},{"phrase":"omnivorous curiosity","zh":"什么都想知道的求知欲"},{"phrase":"largely omnivorous","zh":"大体上杂食的"}],"forms":[{"label":"比较级","form":"more omnivorous"},{"label":"最高级","form":"most omnivorous"},{"label":"副词形式","form":"omnivorously（杂食地；广泛地）"},{"label":"名词形式","form":"omnivore（杂食动物）；omnivory（杂食性）"},{"label":"作定语","form":"omnivorous + 名词（如 omnivorous fish、omnivorous reader）"}],"derivatives":[{"word":"omnivore","pos":"n.","zh":"杂食动物；兴趣广泛的人"},{"word":"omnivory","pos":"n.","zh":"杂食性"},{"word":"omni-","pos":"prefix","zh":"全、都"},{"word":"omnibus","pos":"n.","zh":"汇编本；公共汽车"},{"word":"herbivorous","pos":"adj.","zh":"植食性的（对照词）"},{"word":"carnivorous","pos":"adj.","zh":"食肉的（对照词）"}],"senses":[{"no":"01","title":"Eating both diets","titleCN":"杂食性：植物与动物性食物兼食","definition":"describing an animal that eats both plant and animal material in substantial amounts","definitionCN":"描述大量食用植物与动物性材料两者的动物","example":"The omnivorous diet of the fox includes fruit, insects and small mammals.","exampleCN":"狐狸的杂食食谱包括果实、昆虫与小型哺乳动物。","why":"The adjective marks the mixed-diet class, which is neither herbivorous nor carnivorous.","whyCN":"这个形容词标出混合食性类别，既非植食也非食肉。"},{"no":"02","title":"Bears and other switch eaters","titleCN":"熊类：随季节切换食物","definition":"describing animals such as bears that shift between plant and animal foods as seasons change","definitionCN":"描述熊这类随季节在植物性与动物性食物之间切换的动物","example":"Omnivorous bears gain weight on berries before the salmon run.","exampleCN":"杂食的熊在鲑鱼洄游前靠浆果增重。","why":"Seasonal switching is the practical advantage of the class: the animal is never stuck with one failing food.","whyCN":"季节切换是这一类的实际优势：动物不会困在单一失败的食物上。"},{"no":"03","title":"Omnivorous birds","titleCN":"杂食鸟类：谷物、昆虫与腐肉都吃","definition":"describing birds that take seeds, fruit, insects, eggs or carrion depending on opportunity","definitionCN":"描述视机会取食种子、果实、昆虫、卵或腐肉的鸟类","example":"Omnivorous birds adapt quickly when a crop fails.","exampleCN":"作物歉收时，杂食鸟类能迅速适应。","why":"Flight lets birds sample many patches, which makes a mixed diet especially efficient.","whyCN":"飞行让鸟类能采样许多斑块，因此混合食性尤其高效。"},{"no":"04","title":"Omnivorous insects","titleCN":"杂食昆虫：既取食植物也取食动物","definition":"describing insects that feed on plant tissue and on other animals or carrion","definitionCN":"描述既取食植物组织、也取食其他动物或腐肉的昆虫","example":"Omnivorous ants scavenge seeds, insects and dead vertebrates.","exampleCN":"杂食蚂蚁取食种子、昆虫与死亡脊椎动物。","why":"Many ants are the clearest examples, because a colony can exploit several food channels at once.","whyCN":"许多蚂蚁是最清楚的例子，因为一个蚁群能同时利用多条食物通道。"},{"no":"05","title":"The human mixed diet","titleCN":"人类混合饮食：谷物与肉并用","definition":"describing the human species' capacity to live on a combination of plant and animal foods","definitionCN":"描述人类物种靠植物与动物性食物组合生活的能力","example":"Human beings are omnivorous and can survive on many different food mixes.","exampleCN":"人类是杂食性的，能靠许多不同的食物组合生存。","why":"The adjective is used at species level in nutrition, describing a capacity rather than a recommended diet.","whyCN":"这个形容词在营养学中用于物种层面，描述一种能力，而不是推荐食谱。"},{"no":"06","title":"An omnivorous reader","titleCN":"什么书都读的人：阅读范围极广","definition":"figuratively describing a person who reads widely across genres, subjects and levels of difficulty","definitionCN":"比喻描述跨越体裁、主题与难度广泛阅读的人","example":"She is an omnivorous reader who moves from biology to detective novels.","exampleCN":"她是个什么书都读的人，从生物学读到侦探小说。","why":"The dietary metaphor turns reading into eating: the reader consumes every kind of text.","whyCN":"饮食比喻把阅读变成进食：读者消耗各种文本。"},{"no":"07","title":"Omnivorous curiosity","titleCN":"无所不包的求知欲：什么都想了解","definition":"figuratively describing an appetite for knowledge that ranges across unrelated fields","definitionCN":"比喻描述横跨不相关领域的求知欲望","example":"His omnivorous curiosity led him from fossils to finance.","exampleCN":"他无所不包的求知欲把他从化石带到金融。","why":"The metaphor extends from texts to questions, where the 'food' is any subject at all.","whyCN":"这个比喻从文本扩展到问题，这里的「食物」可以是任何主题。"},{"no":"08","title":"Cultural and media omnivorousness","titleCN":"文化杂食：品味与平台都不设限","definition":"in sociology and media studies, describing a taste or usage pattern that crosses highbrow, popular and multiple platforms","definitionCN":"社会学与媒介研究中描述跨越高雅、通俗与多种平台的品味或使用模式","example":"The study found an omnivorous pattern of news consumption across print, video and social media.","exampleCN":"研究发现了一种跨纸媒、视频与社交媒体的杂食型新闻消费模式。","why":"The adjective has become a technical term for boundary-crossing, not merely for eating everything.","whyCN":"这个形容词已成为描述跨界的技术术语，不再只是「什么都吃」。"}],"etymology":{"intro":{"en":"Omnivorous is a scientific Latin adjective from omnis 'all' and vorare 'devour', older than the English noun omnivore.","cn":"omnivorous 是科学拉丁语形容词，由 omnis「全部」与 vorare「吞食」构成，比英语名词 omnivore 更早。"},"items":[{"era":"LATIN OMNIS","en":"Omnis meant all or every, and its prefix form omni- spread into words about power, knowledge and transport.","cn":"omnis 意为全部、每个，其前缀形式 omni- 扩散到关于权力、知识与交通的词中。"},{"era":"LATIN VORARE","en":"Vorare meant to devour, the eating verb shared with herbivorous and carnivorous.","cn":"vorare 意为吞食，与 herbivorous、carnivorous 共用的吃的动词。"},{"era":"SCIENTIFIC LATIN","en":"Omnivorus was the adjective for a mixed diet in modern scientific Latin. Its exact first use is uncertain.","cn":"omnivorus 是近代科学拉丁语中表示混合食性的形容词；确切首用存疑。"},{"era":"ENGLISH ADJECTIVE","en":"English omnivorous is recorded in the seventeenth century and was soon used figuratively for broad reading. The exact first citation is uncertain.","cn":"英语 omnivorous 见于 17 世纪，很快被比喻用于广泛阅读；确切首见书证存疑。"},{"era":"MODERN TECHNICAL USE","en":"Sociology and media studies turned omnivorous into a term for crossing cultural and platform boundaries in the late twentieth century.","cn":"20 世纪后期，社会学与媒介研究把 omnivorous 变成描述跨越文化与平台边界的术语。"}]},"similar":{"note":{"en":"The look-alike group shares the -vorous ending; the near-meaning group separates mixed diet from wide interest and technical breadth.","cn":"形近组共享 -vorous 结尾；近义组区分混合食性、广泛兴趣与技术性广度。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"omnivore","ipa":"/ˈɒmnɪvɔː/","tag":"the noun","definition":"The animal or person itself. It is a count noun, so a bear is an omnivore with an omnivorous diet.","definitionCN":"指动物或人本身。它是可数名词，因此熊是 omnivore，其食谱是 omnivorous。"},{"word":"herbivorous","ipa":"/hɜːˈbɪvərəs/","tag":"plant-eating","definition":"Describes a plant-only diet. The stem herba- replaces omni- and reverses the class.","definitionCN":"描述纯植食。词干 herba- 替换 omni-，类别随之相反。"},{"word":"carnivorous","ipa":"/kɑːˈnɪvərəs/","tag":"flesh-eating","definition":"Describes a flesh-only diet. The stem caro- replaces omni-, and the diet narrows.","definitionCN":"描述纯肉食。词干 caro- 替换 omni-，食性随之收窄。"}]},{"heading":"NEAR MEANING","entries":[{"word":"generalist","ipa":"/ˈdʒenrəlɪst/","tag":"broad ecology","definition":"A species or person that uses many resources. It is broader than omnivorous, which is specifically about food.","definitionCN":"指利用多种资源的物种或人。它比 omnivorous 更宽，后者专指食物。"},{"word":"eclectic","ipa":"/ɪˈklektɪk/","tag":"broad taste","definition":"Describes tastes drawn from many sources. It matches the figurative sense of omnivorous but is used of style and choice, not diet.","definitionCN":"描述从多种来源汲取的品味。它对应 omnivorous 的比喻义，但用于风格与选择，而非食性。"},{"word":"polyphagous","ipa":"/pɒˈlɪfəɡəs/","tag":"technical many-food","definition":"A technical adjective for feeding on many kinds of food, mostly used of insects. It overlaps with omnivorous but belongs to entomology.","definitionCN":"技术形容词，指取食多种食物，多用于昆虫。它与 omnivorous 重叠，但属昆虫学用语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real suffixes, real collocations and real relatives.","cn":"正常联想：真实后缀、真实搭配与真实同族词。"},"normal":[{"en":"omni 'all' + -vorous 'eating': eating everything.","cn":"omni「全部」+ -vorous「吃……的」：什么都吃。"},{"en":"Typical phrases: omnivorous animal, omnivorous diet, omnivorous reader, omnivorous curiosity.","cn":"典型搭配：杂食动物、杂食食谱、什么书都读的人、无所不包的求知欲。"},{"en":"The family runs omnivore, omnivory, omnibus and omni- words such as omnipotent.","cn":"同族词包括 omnivore、omnivory、omnibus，以及 omnipotent 这类 omni- 词。"},{"en":"Swap the stem to change the class: omni-, herbi-, carni-.","cn":"换词干就换类别：omni-、herbi-、carni-。"},{"en":"In sociology, omnivorous means boundary-crossing taste, not literal eating.","cn":"在社会学中，omnivorous 指跨界的品味，而非字面进食。"}],"abstract":[{"en":"Picture one table holding grain, berries, fish and insects, with a fork reaching everywhere.","cn":"想象一张桌上摆着谷物、浆果、鱼与昆虫，叉子伸向每一处。"},{"en":"Picture a reader with a biology paper and a detective novel open at once.","cn":"想象一位读者同时摊开一篇生物学论文和一本侦探小说。"},{"en":"Picture one person reading news in print, on video and on a phone before noon.","cn":"想象一个人在中午前就从纸媒、视频与手机上读新闻。"}]},"examples":[{"en":"The omnivorous bear moves from berries to salmon as autumn arrives.","cn":"秋天到来时，这只杂食的熊从浆果转向鲑鱼。"},{"en":"Omnivorous ants exploit both seeds and dead insects.","cn":"杂食蚂蚁既利用种子也利用死昆虫。"},{"en":"Her omnivorous reading made her hard to surprise in conversation.","cn":"她什么书都读，交谈时很难被难住。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"omnivore（杂食动物）+ ous（……的）→ 杂食的 → omnivorous","word":"omnivorous"},"root":"拉丁 omnis「全部」+ vorare「吞食」→ 科学拉丁语 omnivorus「各类食物都吃的」→ 英语 omnivorous。","sensesIntro":{"en":"Eight senses apply one adjective to diet, seasonal switching, birds, insects, human capacity, reading, curiosity and cultural breadth.","cn":"八个义项把同一个形容词用于食性、季节切换、鸟类、昆虫、人类能力、阅读、求知欲与文化广度。"},"semanticMap":{"core":{"en":"CORE IMAGE: one table holding grain, berries, fish and insects, reached from every side.","cn":"核心意象：一张桌上摆着谷物、浆果、鱼与昆虫，四面都能取用。"},"chain":["MIXED DIET","SEASONAL SWITCHING","BIRD AND INSECT","HUMAN CAPACITY","WIDE READING","BOUNDARY CROSSING"],"branches":[{"senses":"01 · 02","en":"DIET: mixed eating is the base, and seasonal switching is its practical payoff.","cn":"食性：混合取食是基本义，季节切换是它的实际收益。"},{"senses":"03 · 04","en":"ANIMALS: birds and insects show the class across very different body plans.","cn":"动物：鸟类与昆虫展示了这一类在差异极大的体型中的表现。"},{"senses":"05","en":"HUMANS: the adjective describes a species-level capacity, not a menu plan.","cn":"人类：这个形容词描述物种层面的能力，而非一份菜单。"},{"senses":"06 · 07","en":"METAPHOR: reading and curiosity become forms of eating.","cn":"比喻：阅读与求知欲变成进食的形式。"},{"senses":"08","en":"TECHNICAL: sociology uses the word for taste that crosses every boundary.","cn":"技术用法：社会学用这个词描述跨越一切边界的品味。"}]},"affixes":{"intro":{"en":"Omnivorous is the adjective branch of the 'all-eating' family, and omni- is one of the most transparent prefixes in English.","cn":"omnivorous 是「什么都吃」词族的形容词支，omni- 是英语中最透明的前缀之一。"},"latinIntro":{"en":"Omnis means all, vorare means devour, and -vorus is the scientific adjective ending used across diet words.","cn":"omnis 意为全部，vorare 意为吞食，-vorus 是各类食性词共用的科学形容词词尾。"},"items":[{"word":"omnivorous","structure":"omni- (all) + vorare (devour) + -ous","meaning":"eating everything; widely curious","meaningCN":"什么都吃的；兴趣广泛的","example":"The omnivorous fish takes plants and larvae.","exampleCN":"这种杂食鱼既吃植物也吃幼虫。"},{"word":"omnivore","structure":"omni- + vorare + noun ending","meaning":"a mixed-diet animal","meaningCN":"混合食性的动物","example":"The omnivore samples every food patch.","exampleCN":"这只杂食动物尝试每一处食物斑块。"},{"word":"omnivory","structure":"omnivore + -y (abstract noun)","meaning":"mixed-diet practice","meaningCN":"杂食习性","example":"Omnivory is common among ants.","exampleCN":"杂食性在蚂蚁中很常见。"},{"word":"omni-","structure":"omni- (prefix)","meaning":"all, everywhere","meaningCN":"全部、处处","example":"Omni- also forms omnipotent and omniscient.","exampleCN":"omni- 还构成 omnipotent 与 omniscient。"},{"word":"omnibus","structure":"omni- + -bus (dative plural ending)","meaning":"for all; a collected volume","meaningCN":"为所有人的；汇编本","example":"The omnibus edition collects all four novels.","exampleCN":"合集版收录了全部四部小说。"},{"word":"herbivorous","structure":"herba (grass) + vorare + -ous","meaning":"plant-eating","meaningCN":"植食的","example":"Herbivorous animals have fermentation chambers.","exampleCN":"植食动物有发酵腔。"},{"word":"carnivorous","structure":"caro (flesh) + vorare + -ous","meaning":"flesh-eating","meaningCN":"食肉的","example":"Carnivorous animals have shearing teeth.","exampleCN":"食肉动物有剪切齿。"},{"word":"generalist","structure":"general + -ist (one who)","meaning":"one using many resources","meaningCN":"利用多种资源者","example":"Omnivorous species are often habitat generalists.","exampleCN":"杂食物种常常也是生境广适种。"},{"word":"eclectic","structure":"Greek eklegein (select out) + -ic","meaning":"drawing from many sources","meaningCN":"从多种来源汲取的","example":"The exhibit is eclectic in style.","exampleCN":"这个展览风格驳杂。"}],"latinEntries":[{"word":"omnis","structure":"omnis, omne (adj., third declension)","meaning":"all, every","meaningCN":"全部、每个"},{"word":"vorare","structure":"vorare, voro, voravi, voratum (v., first conjugation)","meaning":"to devour","meaningCN":"吞食"},{"word":"omnivorus","structure":"omnivorus, omnivora, omnivorum (adj., scientific Latin)","meaning":"eating all kinds of food","meaningCN":"各类食物都吃的"}]}}]);
